window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-20"]={"block":"med:med-clinica-medica-med-clm-20","label":"MED · MED CLM 20","count":472,"questions":[{"id":"med-clinica-medica-med-clm-20-345452","number":"345452","sourceNumber":"345452","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na artrite reumatóide, quais características clínicas são típicas dessa artropatia:","options":{"A":"Rigidez matinal prolongada, simetria, sintomas gerais, não deformante.","B":"Rigidez matinal prolongada, assimetria, sintomas gerais, deformante.","C":"Rigidez matinal fugaz, simetria, sintomas gerais, deformante.","D":"Rigidez matinal prolongada, simetria, sintomas gerais, deformante."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-343836","number":"343836","sourceNumber":"343836","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 45 anos, retorna ao ambulatório de reumatologia com resultado do exames,\nVHS (40 mm) e radiografias de mãos com\naumento de partes moles e erosões marginais em\narticulações interfalangeanas proximais e processo estiloide ulnar. Diante deste quadro qual exame\nlaboratorial com maior probabilidade de vir positivo na paciente?","options":{"A":"HLA-B27.","B":"Anti Sm.","C":"Anti CCP.","D":"ASLO."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-283278","number":"283278","sourceNumber":"283278","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Qual a manifestação ocular esperada para um paciente com artrite reativa?","options":{"A":"Conjuntivite asséptica.","B":"Ceratite.","C":"Irite.","D":"Neurite."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-283283","number":"283283","sourceNumber":"283283","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 48 anos de idade está em seguimento por quadro de poliartrite simétrica de\ngrandes e pequenas articulações há 6 meses. Exames complementares revelaram atividade\ninflamatória elevada e fator reumatoide fortemente positivo. Qual das seguintes medicações é\nmodificadora do curso dessa doença?","options":{"A":"Azatioprina.","B":"Cloroquina.","C":"Pregabalina.","D":"Naproxeno."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-281112","number":"281112","sourceNumber":"281112","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem, 53 anos, hipertenso, portador de doença renal crônica em tratamento\nconservador (creatinina basal = 1,7 mEq/L),\napresenta artrite no joelho esquerdo, que teve início\nsúbito nas últimas 24h, após churrasco em família. Faz uso regular de clortalidona e valsartana, é\ntabagista e etilista. Refere que não apresentou febre nas últimas 24 horas e o exame físico não\nrevela sinais sistêmicos. Nota-se edema articular com hiperemia, dor e limitação funcional à\nmobilização do joelho esquerdo.","options":{"A":"Punção articular e drenagem.","B":"Colchicina.","C":"Clindamicina.","D":"Prednisolona intra-articular.","E":"Alopurinol."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-283307","number":"283307","sourceNumber":"283307","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Com relação a artrites agudas na infância, marque a alternativa CORRETA:","options":{"A":"A artrite da febre reumática é, principalmente, uma poliartrite migratória de grandes\narticulações\nacometendo de forma transitória e intermitente.","B":"A artrite séptica é considerada uma emergência médica, sendo mais frequente nos adolescentes\ndo sexo masculino.","C":"A artrite reativa pode ocorrer em qualquer idade, geralmente, após 1 mês de infecção\ngastrointestinal ou genitourinária, acometendo as articulações de membros superiores.","D":"Os tumores ósseos benignos e malignos, frequentemente, cursam mais com artrite do que com\ndor."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-247186","number":"247186","sourceNumber":"247186","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina com 9 anos de idade e história de artrite no punho direito por 3 dias, seguida\npor artrite no tornozelo esquerdo com duração\nde 2 dias e por artrite no joelho que também durou 2\ndias. Apresentou melhora com aspirina. Na avaliação laboratorial apresentou aumento das provas\nde atividade inflamatória. Uma semana depois apresentou cansaço aos médios esforços. Quais os\nachados mais prováveis na ausculta cardíaca?","options":{"A":"Bradicardia e sopro diastólico em foco aórtico.","B":"Bradicardia e sopro sistólico em foco aórtico.","C":"Taquicardia e sopro diastólico em foco aórtico.","D":"Taquicardia e sopro sistólico em foco mitral.","E":"Bradicardia e sopro diastólico em foco mitral."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-251928","number":"251928","sourceNumber":"251928","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Os critérios de Jones são utilizados para o diagnóstico de Febre Reumática, sendo sua\nultima modificação realizada em 2015, qual das abaixo consta a assertiva que contém a\ncombinação dos critérios, que fazem o diagnóstico dessa doença no primeiro surto.","options":{"A":"Cardite, febre e ASO positivo.","B":"Artrite, febre e aumento do espaço P-R.","C":"Eritema marginado, artralgia, e ASO positivo.","D":"Poliartralgia, febre e convulsões."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-217713","number":"217713","sourceNumber":"217713","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma mulher de 54 anos evolui há 3 meses com fadiga e anorexia, acompanhadas de\ndor e rigidez, principalmente matinal,\nque acomete a musculatura do pescoço e da cintura\nescapular e perdura por cerca de 45 minutos. Exames laboratoriais solicitados revelam Hb: 9,6 g/dl,\ncom hemácias microcíticas e hipocrômicas; VHS: 96 mm/h; FAN: reativo e ferritina normal. A\nanamnese dirigida identificou apenas artralgia de cotovelos e emagrecimento de 4 kg no período.\n\nAusculta cardíaca, pulmonar e palpação do abdome sem achados anormais. Kerning, Brudzinski e\nLasegue negativos. Considerando a hipótese\ndiagnóstica mais provável, a conduta MAIS\nADEQUADA, dentre as oferecidas é:","options":{"A":"Tomografia computadorizada de tórax e abdome.","B":"Biópsia de artéria temporal.","C":"Punção lombar para análise liquórica.","D":"Prednisona 20 mg pela manhã."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-182694","number":"182694","sourceNumber":"182694","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Febre Reumática (FR) é uma doença muito frequente nos países em\ndesenvolvimento. Com relação à FR, marque a assertiva CORRETA:","options":{"A":"São sinais menores dos critérios de Jones: artralgia, febre, aumento do VHS, aumento do\nespaço PR e elevação da ASO.","B":"A profilaxia secundária para FR deve ser realizada com penicilina G benzatina de 28 em 28 dias,","C":"As válvulas cardíacas mais frequentemente acometidas são mitral e tricúspide.","D":"A Coréia de Sydenham surge tardiamente (2 meses a 1 ano após infecção estreptocócica), e\nisoladamente faz diagnóstico de FR."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-183129","number":"183129","sourceNumber":"183129","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Nas uveítes associadas com artrite juvenil crônica, é INCORRETO afirmar que:","options":{"A":"20% dos casos são bilaterais.","B":"O olho fica branco mesmo na presença de severa uveíte.","C":"O envolvimento do segundo olho em casos unilaterais é raro após um ano.","D":"25% dos casos são severos e respondem pobremente ao tratamento.","E":"Cerca de 15% dos casos têm um curso que dura menos de 4 meses."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-159109","number":"159109","sourceNumber":"159109","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é uma complicação não supurativa da faringoamigdalite causada\npelo estreptococo beta-hemolítico do grupo A. Em\nrelação ao diagnóstico desta doença, quais são,\nrespectivamente, os critérios maiores e os menores para o diagnóstico de um surto?","options":{"A":"Maiores: cardite, miosite, artrite, cerebelite, amigdalite. Menores: sopro cardíaco,\nprolongamento\ndo intervalo PR, degeneração do folheto posterior\nda valva mitral, eritema.","B":"Maiores: cardiomegalia, eritema marginado, taquicardia, hepatomegalia, artralgia. Menores:\nfebre, artrite, coreia, exantema.","C":"Maiores: cardite, coreia de Sydenham, artrite, eritema marginado, nódulos subcutâneos.\n\nMenores: febre, artralgia, elevação das provas de fase aguda, intervalo PR prolongado.","D":"Maiores: cardite, artralgia, elevação da proteína C-reativa e da velocidade de\nhemossedimentação, coreia, febre. Menores: eritema marginado, nódulos subcutâneos,\nhepatomegalia, taquicardia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-135962","number":"135962","sourceNumber":"135962","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente com quadro de Anemia e contagem de reticulócitos elevada, sem história ou\nexame físico de perda de peso aguda ou\ncrônica, sem nenhum sintoma ou sinal de perda de\nsangue. Qual o provável diagnóstico?","options":{"A":"Aplasia de medula;","B":"Anemia hemolítica;","C":"Anemia ferropriva;","D":"Anemia por deficiência de folato."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-108645","number":"108645","sourceNumber":"108645","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Qual é o teste laboratorial útil no diagnóstico da anemia falciforme?","options":{"A":"Teste de Coombs.","B":"Eletroforese de hemoglobina.","C":"Diagnóstico morfológico primário.","D":"Haptoglobulina sérica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-108711","number":"108711","sourceNumber":"108711","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Após a gastrectomia total qual das vitaminas abaixo deve ser suplementada e qual a\nrepercussão disso?","options":{"A":"Ácido fólico - anemia perniciosa;","B":"Vitamina K - diátese hemorrágica;","C":"Vitamina C - anemia microcítica;","D":"Vitamina D - osteoporose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-84540","number":"84540","sourceNumber":"84540","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 45 anos, agricultor, morador da zona rural do município de Acrelândia -\nAcre, procura atendimento devido à febre,\ncefaleia, artralgia e calafrios. No exame físico, a única\nalteração era a detecção de febre (temperatura axilar: 38,4ºC). Pesquisa de Plasmodium: duas\ncruzes de P. vivax. Iniciada terapêutica adequada para o caso segundo as normas do Ministério da\nSaúde. Paciente retorna no quarto dia a partir do início do tratamento, apresentando icterícia\nintensa, vômitos e dor abdominal, que diz terem iniciado no dia anterior. Relata desaparecimento\ndos sintomas que apresentara no começo da doença. Provavelmente, a causa desse quadro e a\nconduta serão, respectivamente:","options":{"A":"Hemólise pela primaquina; suspensão do tratamento.","B":"Hemólise pela cloroquina; manter o esquema apenas com primaquina.","C":"Hemólise pelo quinino; substituí-lo pela cloroquina.","D":"Hepatotoxicidade devido à cloroquina e primaquina.","E":"Hepatotoxicidade devido exclusivamente ao quinino."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-66914","number":"66914","sourceNumber":"66914","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Com relação ao tratamento da anemia ferropriva na infância, marque a alternativa\nINCORRETA:","options":{"A":"Deve-se realizar orientação nutricional para uma alimentação com alta biodisponibilidade de\nferro.","B":"Os sais de ferro devem ser ingeridos com alimentos que facilitem a sua absorção, como por\nexemplo, suco de frutas cítricas e leite de vaca.","C":"Prescrever sais de ferro na quantidade de 3 a 5 mg de ferro elementar/kg/dia, fracionado de 2 a\n3 vezes.","D":"O tratamento com ferro deve ser realizado por 3 a 4 meses com a 1ª reavaliação (hemograma)\napós 4 semanas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-29405","number":"29405","sourceNumber":"29405","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Assinale a alternativa incorreta:","options":{"A":"Na presença de hemoglobina C é frequente o achado de hemácias em alvo","B":"Na anemia facilforme é comum o aparecimento de osteomielite por Salmonella SP","C":"Indivíduos com heterozigose para hemoglobina S apresentam anemia discreta.","D":"A deficiência de glicose 6-fosfato-desidrogenase (G6PD) é uma doença hemolítica recessiva\nligada ao cromossomo X.","E":"O teste de fragilidade osmótica é utilizado para o diagnóstico de esferocitose hereditária"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-29366","number":"29366","sourceNumber":"29366","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente com quadro de Anemia microcítica e dosagem de ferritina normal, têm\nprovavelmente?","options":{"A":"Anemia aplásica","B":"Anemia ferropriva","C":"Talassemia","D":"Anemia megaloblástica","E":"Anemia sideroblástica"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-307030","number":"307030","sourceNumber":"307030","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 50 anos de idade, procura atendimento ambulatorial por dores em articulações\ndas mãos. As dores foram iniciadas há 8 meses\ne são acompanhadas de rigidez matinal. De\nantecedentes, refere hipotireoidismo, em uso de levotiroxina. Ao exame físico, sinais vitais e\nausculta sem alterações. Notam-se edema e dor à movimentação passiva das articulações\ninterfalangianas proximais em ambas as mãos, inclusive dos polegares, além de punhos. Realizado\nfator reumatoide, reagente. Frente ao caso, considerando os critérios internacionais mais utilizados\npara o diagnóstico mais provável, é CORRETO afirmar:","options":{"A":"O acometimento de grandes articulações, como o punho, pontua menos.","B":"A presença do fator reumatoide é imprescindível para o diagnóstico.","C":"Para confirmação diagnóstica, é necessária a evidência de deformidade articular.","D":"A duração dos sintomas precisa ser de, no mínimo, seis semanas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-307031","number":"307031","sourceNumber":"307031","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 50 anos de idade, procura atendimento ambulatorial por dores em articulações\ndas mãos. As dores foram iniciadas há 8 meses\ne são acompanhadas de rigidez matinal. De\nantecedentes, refere hipotireoidismo, em uso de levotiroxina. Ao exame físico, sinais vitais e\nausculta sem alterações. Notam-se edema e dor à movimentação passiva das articulações\ninterfalangianas proximais em ambas as mãos, inclusive dos polegares, além de punhos. Realizado\nfator reumatoide, reagente. Frente ao caso, A fisiopatologia mais importante do diagnóstico mais\nprovável envolve:","options":{"A":"Sinovite crônica.","B":"Entesite crônica.","C":"Osteíte crônica.","D":"Capsulite crônica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-307032","number":"307032","sourceNumber":"307032","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 50 anos de idade, procura atendimento ambulatorial por dores em articulações\ndas mãos. As dores foram iniciadas há 8 meses\ne são acompanhadas de rigidez matinal. De\nantecedentes, refere hipotireoidismo, em uso de levotiroxina. Ao exame físico, sinais vitais e\nausculta sem alterações. Notam-se edema e dor à movimentação passiva das articulações\ninterfalangianas proximais em ambas as mãos, inclusive dos polegares, além de punhos. Realizado\nfator reumatoide, reagente. Frente ao caso, Segundo o protocolo do Sistema Único de Saúde, SUS,\na medicação de primeira linha, a ser oferecida, é:","options":{"A":"Prednisolona.","B":"Metotrexate.","C":"Hidroxicloroquina.","D":"Adalimumabe."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-314210","number":"314210","sourceNumber":"314210","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Considerando as causas inflamatórias da Artrite na infância e adolescência, assinale a\nalternativa INCORRETA.","options":{"A":"As artrites reativas são um grupo de artrites inflamatórias que incluem a febre reumática aguda,\nas artrites após infecções do trato\ngenitourinário ou gastrointestinal e as artrites pós-infecciosas e\npós-virais.","B":"A artrite psoriática juvenil é a artrite associada à lesão cutânea da psoríase.","C":"A artrite idiopática juvenil é a doença reumática crônica mais comum da infância e uma causa\nfrequente de incapacidade física.","D":"A denominação de artrite crônica na infância é clara; dessa forma, classificam-se como de início\njuvenil os quadros que começam aos 15 anos de idade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-315203","number":"315203","sourceNumber":"315203","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A sindrome de Reiter é descrita como uma patologia relacionada a uma Triade bem\ncomo a presença de um determinado agente\ninfeccioso. Cite a alternativa CORRETA:","options":{"A":"Alopecia, artrite e colite / estafilococos.","B":"Anemia, endocardite e artrite / estreptococos.","C":"Uretrite, conjuntivite e artrite/ clamídia.","D":"Gengivite, dermatite e artrite/ hpv.","E":"Nenhuma das alternativas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-275969","number":"275969","sourceNumber":"275969","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Com relação a ?artrite reativa?, patologia reumática que pertence à família das\nespondiloartropatias, podemos afirmar que:","options":{"A":"Não é precedida por processos infecciosos.","B":"Não apresentam associação com inflamação do esqueleto axial ou alteração da dosagem de\nHLA-B27 (antígeno leucocitário).","C":"Além da artralgia não apresentam alterações clínicas adicionais.","D":"Infecção venérea ou desinteria precedem em geral o quadro articular.","E":"Nenhuma das alternativas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-216214","number":"216214","sourceNumber":"216214","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Artrite Psoríaca (AP), comumente chamada de psoriásica ou psoriática, tem sido\ndefinida como uma artrite inflamatória crônica\nassociada à psoríase. Está INADEQUADO o seguinte\nitem:","options":{"A":"Dentre suas manifestações clínicas cardinais, destacam-se acometimentos articulares periférico\ne axial, entesites, tenossinovites e\ndactilites.","B":"A AP caracteriza-se também por apresentar diversas manifestações extra-articulares típicas.","C":"Caracterizam-se também por apresentar diversas manifestações entre elas os envolvimentos\ncutâneo (psoríase cutânea), ungueal\n(onicodistrofia), ocular (uveíte anterior).","D":"Caracteriza-se também por apresentar diversas manifestações cardiovascular (doença valvar\naórtica e aterosclerose), pulmonar (pneumonite intersticial) e renal (amiloidose, nefropatia sem\ndepósito de IgA)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-216241","number":"216241","sourceNumber":"216241","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação ao diagnóstico diferencial, a Artrite Psoríaca - AP se distingue da Artrite\nReumatoide pelas seguintes características clínicas:","options":{"A":"Assimetria do envolvimento articular e acometimento da coluna lombar.","B":"Apresentação oligoarticular, entesite e irite.","C":"Fator reumatoide positivo.","D":"Lesões ungueais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-215542","number":"215542","sourceNumber":"215542","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Artrite Reumatoide - AR é bastante variável quanto à apresentação clínica, à\ngravidade e ao prognóstico, está CORRETO apenas que:","options":{"A":"Sua forma clínica mais comum é a poliartrite simétrica de pequenas e grandes articulações com\ncaráter crônico e destrutivo, podendo levar a relevante limitação funcional.","B":"Sua forma clínica mais rara é a poliartrite simétrica de pequenas e grandes articulações com\ncaráter crônico e destrutivo, podendo levar a relevante limitação funcional.","C":"Sua forma clínica mais comum é a poliartrite assimétrica de pequenas e grandes articulações\ncom caráter crônico e destrutivo, podendo levar a\nrelevante limitação funcional.","D":"Sua forma clínica mais comum é a poliartrite simétrica de pequenas e grandes articulações com\ncaráter crônico e destrutivo, que nunca leva a relevante limitação funcional."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-216311","number":"216311","sourceNumber":"216311","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Artrite Psoríaca (AP), tem sido definida como uma artrite inflamatória crônica\nassociada à psoríase, descrições iniciais da\ndoença sugeriram que a AP possui manifestações\nclínicas mais brandas quando comparada a outras artrites inflamatórias crônicas. Sendo assim,\npodemos apenas aceitar um dos itens abaixo como ERRADO:","options":{"A":"Em relação à patogênese, a AP é uma doença autoimune poligênica, de etiologia indefinida.","B":"As citocinas relacionadas a linfócito T desempenham papel central.","C":"A ocorrência da AP está ligada a uma suscetibilidade genética complexa, associada a fatores\nambientais e não a mecanismos imunológicos.","D":"Os fatores ambientais (microtrauma e agentes infecciosos) têm sido relacionados."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-219899","number":"219899","sourceNumber":"219899","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Escolar de 10 anos de idade é trazida ao controle na unidade básica de saúde com\nhistória de ter cardiopatia reumática:\nprimeiro surto de febre reumática aos seis anos de idade, dois\nsurtos subsequentes, com acometimento das valvas mitral e aórtica. No momento, apesar do\ntratamento utilizado (fez pulsoterapia com corticosteroides no último surto) ainda apresenta\nsintomas (cansaço ao brincar e \"coração disparado\") e na ausculta cardíaca, além de taquicardia\nleve, apresenta sopro sistólico holossistólico de grande intensidade, mas audível na área mitral,\nirradiando para axila. Faz uso regular de penicilina benzatina (21 em 21 dias). O motivo da consulta\né o desejo da mãe de parar de aplicar injeções de penicilina (\"doem muito, fico com pena dela, tão\nmagrinha!\"). Qual a orientação que deve ser dada à mãe a respeito das injeções, após explicações\nsobre a necessidade da profilaxia?","options":{"A":"Deve usar profilaxia com penicilina benzatina até cinco anos após o último surto.","B":"Deve usar profilaxia com penicilina benzatina até os 40 anos de idade ou por toda vida.","C":"Deve usar profilaxia com penicilina benzatina de 21 em 21 dias até os 21 anos de idade.","D":"Deve usar profilaxia com penicilina benzatina por um ano após estar assintomático."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-219911","number":"219911","sourceNumber":"219911","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Com relação à febre reumática aguda, é CORRETO afirmar:","options":{"A":"As manifestações maiores da febre reumática aguda compreendem artralgia, cardite, coreia de\nSydenham, nódulos subcutâneos e eritema nodoso.","B":"Embora as sequelas sejam observadas classicamente a nível do endocárdio, miocardite e\npericardite são mais intensas do que a endocardite.","C":"A evolução das manifestações articulares não é modificada pelo uso de anti-inflamatório não\nesteroide ou corticosteroide.","D":"Os joelhos, tornozelos, punhos e cotovelos são as articulações mais frequentemente\nacometidas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-215213","number":"215213","sourceNumber":"215213","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Artrite Reumatoide (AR) é bastante variável quanto à apresentação clínica, à\ngravidade e ao prognóstico. Sua forma clínica\nmais comum é a poliartrite simétrica de pequenas e\ngrandes articulações com caráter crônico e destrutivo, podendo levar a relevante limitação\nfuncional, comprometendo a capacidade laboral e a qualidade de vida, estando inadequado o\nseguinte item:","options":{"A":"Pode resultar em significativo impacto pessoal e social, com elevados custos indiretos, segundo\nestimativas nacionais.","B":"A associação de AR a neutropenia e esplenomegalia, que ocorre mais nos casos de AR de\nlonga evolução, é chamada de síndrome de Felty.","C":"Dados de um estudo brasileiro de pacientes com AR inicial sugerem que a apresentação clínica\nmais comum seja a poliartrite aguda (70%) com sinovite persistente nas mãos (91%) e rigidez\nmatinal prolongada (mais de 2 horas).","D":"A rigidez matinal pode ser o sintoma inicial e costuma ser um indício de doença sem atividade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-215216","number":"215216","sourceNumber":"215216","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O tratamento de Artrite reumatoide (AR) deve ser iniciado o mais breve possível, uma\nvez que a terapia medicamentosa intensiva\ninstituída precocemente previne danos estruturais\n(erosões), melhorando a capacidade funcional, sendo CORRETO que:","options":{"A":"O tratamento não medicamentoso de AR exclui educação do paciente e de sua família, que não\napresenta resultados, fisioterapia, apoio psicossocial e cirurgia.","B":"O tratamento não medicamentoso de AR inclui educação do paciente e de sua família, terapia\nocupacional, exercícios, fisioterapia, apoio psicossocial e cirurgia.","C":"O tratamento não medicamentoso de AR inclui educação do paciente e de sua família, terapia\nocupacional, exercícios, fisioterapia e apoio psicossocial se mostram desnecessários.","D":"O tratamento não medicamentoso de AR inclui educação do paciente, não permitindo\nparticipação de sua família."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-215289","number":"215289","sourceNumber":"215289","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Artrite Reumatoide (AR) é uma doença autoimune, inflamatória, sistêmica e crônica,\ncaracterizada por sinovite periférica e por diversas manifestações extra-articulares. Quanto a isso,\npodemos considerar inadequado que:","options":{"A":"Apesar de a etiopatogenia de AR ainda não ser inteiramente conhecida, muito se avançou no\ntema nos últimos anos.","B":"No início, a observação do aumento da incidência de AR entre familiares, principalmente entre\ngêmeos heterozigóticos, sugeria um componente genético em sua etiopatogênese.","C":"Foi identificado o antígeno leucocitário humano (Human Leukocyte Antigen - HLA), considerado\no principal fator genético no desenvolvimento\ndessa doença.","D":"Diversos alelos de HLA-DRB1 vêm sendo associados a AR em populações variadas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-212203","number":"212203","sourceNumber":"212203","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Jean, 07 anos de idade, chega ao pronto-socorro com quadro de insuficiência cardíaca\ncaracterizado pela presença de ritmo de galope, sem descrição de patologia cardíaca anterior. Foi\nrealizado ecocardiograma que evidenciou insuficiência mitral, sem outras alterações. Assinale a\nalternativa que apresente diagnóstico mais provável para Jean.","options":{"A":"Sepse.","B":"Miocardite viral.","C":"Febre Reumática.","D":"Doença de Kawasaki.","E":"Miocardiopatia chagásica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-161265","number":"161265","sourceNumber":"161265","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A artrite reumatoide apresenta caráter crônico e destrutivo, que pode levar à importante\nlimitação funcional, com perda da capacidade laboral e qualidade de vida, a menos que o\ndiagnóstico seja feito em fase inicial da doença e o tratamento determine melhora clínica. A\nrespeito\nda doença, assinale a alternativa INCORRETA.","options":{"A":"O período inicial da doença é considerado uma janela de oportunidade terapêutica.","B":"O período inicial da doença é considerado um momento em que a intervenção farmacológica\nrápida e efetiva pode mudar o curso da doença em\nlongo prazo.","C":"O período inicial da doença, em especial seus 24 primeiros meses, é o chamado AR inicial.","D":"Esses fatores resultaram no melhor controle clínico da doença, com a possibilidade de remissão\nsustentada da AR."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-161280","number":"161280","sourceNumber":"161280","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Quando analisamos a Artrite Reumatoide (AR), conceituamos que é uma doença\nsistêmica, inflamatória, autoimune, que se\ncaracteriza pelo comprometimento da membrana sinovial\npreferencialmente das articulações periféricas. Quanto a sua epidemiologia, podemos considerar\ndiversos fatores, com EXCEÇÃO de um deles. Indique-o.","options":{"A":"Sua prevalência seja de 0,5% a 1% da população.","B":"Ocorre predominando no sexo masculino.","C":"Ocorre mais na faixa etária dos 30 aos 50 anos.","D":"O acometimento em geral simétrico das pequenas e grandes articulações é a característica\nprincipal da AR, sendo comum o envolvimento das\nmãos e pés."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-158761","number":"158761","sourceNumber":"158761","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A profilaxia secundária na febre reumática é indicada para evitar novos surtos da\ndoença. Em que consiste esse tratamento?","options":{"A":"Administração de eritromicina, nos casos de alergia à penicilina e à sulfa, na dose de 500\nmg/dia, de 6/6h.","B":"Aplicação de penicilina G benzatina até a terceira década de vida nos pacientes com lesão\nvalvar residual moderada a\n\nsevera.","C":"Administração de sulfadiazina nos pacientes alérgicos, em dose de 300 mg/dia até 30 kg e 500\nmg/dia naqueles acima desse peso.","D":"Aplicação de penicilina G benzatina a cada 21 dias até 21 anos ou até cinco anos após o último\nsurto nos pacientes com doença cardíaca.","E":"Aplicação de penicilina G benzatina a cada 21 dias até 25 anos ou 10 anos após o último surto\nnos pacientes com febre\n\nreumática com cardite prévia, insuficiência mitral residual ou resolução de lesão valvar."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-158792","number":"158792","sourceNumber":"158792","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática pode ser considerada um quebra-cabeças que somente foi\ncompletamente montado em 1886, quando as\nmanifestações articulares, cardíacas e neurológicas\nforam reconhecidas como parte da síndrome. Em 2004, a Organização Mundial de Saúde definiu\nnovos critérios, a partir dos de Jones para o diagnóstico do primeiro surto, e para cardiopatia\nreumática crônica. Esses critérios foram revisados pela American Heart Association, que passou a\nadotar critérios diferenciados conforme populações classificadas em baixo, médio ou alto risco.\n\nAssim, dadas as afirmativas, I. Para populações de baixo risco, a mono ou poliartrite ou\npoliartralgia\ncaracteriza critério maior de Jones revisado.; II. Para populações de baixo risco, a poliartralgia\ncaracteriza critério menor de Jones revisado.; III. Para populações de baixo risco, VHS (velocidade\nde hemossedimentação) maior/igual a 60 mm e/ ou PCR (proteína C reativa) maior/ igual a 3.0\ncaracterizam critério menor de Jones revisado.; IV. Tanto para populações de baixo quanto para de\nmoderado e alto risco, a febre caracteriza critério menor de Jones revisados.; Verifica-se que estão\ncorretas apenas:","options":{"A":"II, III e IV.","B":"I, III e IV.","C":"II e III.","D":"I e IV.","E":"I e II."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-140181","number":"140181","sourceNumber":"140181","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A anemia ocorre principalmente pela deficiência de ferro é a carência nutricional\nde maior magnitude no mundo. Atinge,\nprincipalmente, crianças menores de dois anos e\ngestantes e, no pré-natal, relacionase com o baixo peso ao nascer e à mortalidade\nmaterna. Em relação às estratégias criadas no Brasil para o controle e redução da anemia\npor deficiência de ferro, assinale a alternativa correta.","options":{"A":"Suplementação preventiva diária de 60 mg de sulfato ferroso e 5mg de ácido fólico para\ncrianças de 6 a 18 meses de idade e suplementação semanal de 25 mg de sulfato ferroso para\ngestantes a partir da 20ª semana.","B":"Suplementação preventiva semanal de 25 mg de sulfato ferroso para crianças de 6 a 18\nmeses de idade e suplementação diária de 60\nmg de sulfato ferroso e 5mg de ácido fólico\npara gestantes a partir da 20ª semana.","C":"Suplementação medicamentosa diária de\n\n60 mg de sulfato ferroso e 5mg de ácido fólico somente para gestantes\ncom diagnóstico de anemia falciforme.","D":"Fortificação das farinhas de trigo e milho com ferro e vitamina A: cada\n\n100g de farinha de trigo e de milho deverá conter 10,0 mg de ferro e 200.000 UI de vitamina\nA.","E":"fortificação das farinhas de mandioca e arroz com ferro e tiamina: cada 100g\n\nde farinha de mandioca e arroz deverão conter 10,0 mg de ferro e 150 mg de vitamina B1."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-134792","number":"134792","sourceNumber":"134792","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação às anemias carenciais, podemos afirmar que","options":{"A":"o diagnóstico laboratorial da anemia ferropriva inclui ferro sérico e ferritina sérica baixos,\ncapacidade total de ligação de ferro\n\nbaixa e saturação de transferrina alta.","B":"a deficiência de B12 e as talassemias são exemplos clássicos de anemias macrocíticas.","C":"nas crianças com anemia hemolítica esferocítica, está contraindicado o uso de sulfa e\nquinolonas.","D":"baixo peso ao nascimento, desmame precoce e baixa disponibilidade de ferro na dieta\npredipõem às anemias ferroprivas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-134267","number":"134267","sourceNumber":"134267","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A causa mais comum de anemia por deficiência de ferro na infância é","options":{"A":"Gemelaridade.","B":"Infecções crônicas.","C":"Desordens gastrointestinais.","D":"Ingestão inadequada de ferro."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-109992","number":"109992","sourceNumber":"109992","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo masculino, 35 anos, com antecedente de Anemia Falciforme,\napresenta no esfregaço de sangue periférico corpúsculos de Howell-Jolly. Assinale abaixo o\nsignificado desse achado.","options":{"A":"Crise de falcização.","B":"Processo infeccioso viral.","C":"Hipoesplenismo.","D":"Deficiência de folato."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-110542","number":"110542","sourceNumber":"110542","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A deficiência de ferro em lactentes e crianças maiores acompanha-se clinicamente de\ntodos os sinais e sintomas, EXCETO:","options":{"A":"Irritabilidade.","B":"Geofagia.","C":"Hipertrofia das papilas gustativas.","D":"Anorexia.","E":"Palidez."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-86612","number":"86612","sourceNumber":"86612","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Marcela, de seis anos de idade, é levada para consulta por apresentar palidez há seis\nmeses e falta de apetite. Exame físico: palidez cutâneo-mucosa e restante normal. Para\nconfirmação de anemia ferropriva, quais as alterações encontradas nos exames?","options":{"A":"Hb < 11 g/dl, contagem de reticulócitos aumentada, hipercromia e macrocitose.","B":"Hb < 11 g/dl, contagem de reticulócitos normal ou diminuída, hipocromia e microcitose.","C":"Hb < 11,5 g/dl, contagem de reticulócitos aumentada, hipercromia e macrocitose.","D":"Hb < 11,5 g/dl, contagem de reticulócitos normal ou diminuída, hipocromia e microcitose.","E":"Hb < 12 g/dl, contagem de reticulócitos aumentada, hipercromia e macrocitose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-86617","number":"86617","sourceNumber":"86617","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Marcela de seis anos de idade é levada para consulta por apresentar palidez há seis\nmeses e falta de apetite. Exame físico: palidez cutâneo-mucosa e restante normal. Após iniciar o\ntratamento para Anemia Ferropriva de Marcela, qual o exame mais adequado para avaliar\nprecocemente a sua resposta terapêutica?","options":{"A":"Dosagem de hemoglobina.","B":"Contagem de reticulócitos.","C":"Saturação de transferrina.","D":"Dosagem de ferro sérico.","E":"Ferritina sérica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-86879","number":"86879","sourceNumber":"86879","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Nas anemias por carência de ferro, a capacidade de ligação de ferro total e ferritina\nsérica mostram, respectivamente, o seguinte\npadrão:","options":{"A":"Aumentado ? diminuído;","B":"Aumentado ? normal;","C":"Diminuído ? normal;","D":"Diminuído ? aumentado;","E":"Normal ? aumentado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-86873","number":"86873","sourceNumber":"86873","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Lactente feminino, 20 meses de idade, é levado para consulta de puericultura sem\nqueixas. Usou leite materno até o quarto mês\nde vida, quando começou a usar a alimentação\ncomplementar adequada e também leite de vaca 6 vezes ao dia. Não usa ou usou medicamento\nalgum. Trouxe um hemograma que mostra Hb = 9,2 g/dl, VCM = 61 micro3, RDW = 18%. Assinale\na alternativa que apresenta o diagnóstico MAIS PROVÁVEL para o quadro acima.","options":{"A":"Anemia falciforme.","B":"Talassemia minor.","C":"Esferocitose hereditária.","D":"Anemia ferropriva.","E":"Anemia hemolítica autoimune."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-49597","number":"49597","sourceNumber":"49597","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"No teste do pezinho, qual resultado sugere anemia falciforme?","options":{"A":"Padrão FA.","B":"Padrão FAZ.","C":"Padrão FSA.","D":"Padrão FS.","E":"Nenhuma das respostas anteriores."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-362486","number":"362486","sourceNumber":"362486","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Jovem de 15 anos, morador de Parintins procurou o hospital da cidade queixando de\nfalta de ar, mal-estar geral, febre e dores\nem grandes articulações de início há 1 semana. Ao exame\nfísico, paciente se encontrava taquicárdica FC 130 bpm, com temperatura de 38,5ºC. A ausculta\ncardíaca, sopro sistólico 3+/6 em foco mitral irradiando para região axilar, joelho direito com\nhiperemia e calor local com critérios para artrite e nódulos firmes, móveis e indolores em região de\ncoluna vertebral. Foi realizado exames laboratoriais que demonstrou velocidade de\nhemossedimentação (VHS) de 55mm. Segundo os critérios de Jones revisado para o diagnóstico\nde febre reumática, este paciente apresenta:","options":{"A":"Um critério maior e três menores.","B":"Dois critérios maiores e um menor.","C":"Dois critérios maiores e dois menores.","D":"Três critérios maiores e dois menores."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-362480","number":"362480","sourceNumber":"362480","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 67 anos vem à consulta com queixa de dor intensa em joelho direito há 8\ndias. Refere episódios semelhantes autolimitados acometendo punho direito e joelhos, bem como\nartralgia mecânica recorrente de joelhos bilateralmente há cerca de 2 anos. Ao exame, apresenta\ndor, calor, edema e eritema de joelho direito. Sem outros dados clínicos relevantes. Qual o\ndiagnóstico mais provável?","options":{"A":"Artrite viral.","B":"Artrite reativa","C":"Artrite tuberculosa.","D":"Artrite microcristalina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-327239","number":"327239","sourceNumber":"327239","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na artrite reumatoide, qual é o padrão mais comum de comprometimento articular?\nAssinale a alternativa CORRETA:","options":{"A":"Oligoarticular assimétrico, aditivo.","B":"Poliarticular migratório, assimétrico.","C":"Poliarticular, simétrico, aditivo.","D":"Monoarticular recorrente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-298207","number":"298207","sourceNumber":"298207","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 19 anos apresentando há 4 dias poliartralgia e febre de 38,7ºC. Ao exame\nfísico artrite de tornozelo esquerdo e tenossinovite de punho direito e presença de lesões pápulo\neritematosas e algumas pústulas em região anterior das pernas. No hemograma leucócitos de\n\n18.000 e PCR de 40. Diante deste quadro, assinale a alternativa com a melhor opção de hipótese\ndiagnóstica/conduta:","options":{"A":"Artrite reativa; iniciar anti-inflamatório não hormonal.","B":"Gota; solicitar dosagem de ácido úrico sérico e iniciar corticoide oral.","C":"Artrite infecciosa; iniciar ceftriaxona e azitromicina.","D":"Artrite infecciosa; iniciar oxacilina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-286715","number":"286715","sourceNumber":"286715","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Artrite reativa é definida como artrite que se desenvolve logo depois de uma infecção\nem outros órgãos que não sejam as\narticulações. A relação de germes mais frequentemente\nimplicados no desenvolvimento da artrite reativa NÃO inclui:","options":{"A":"Chlamydia pneumoniae.","B":"Staphylococcus aureus.","C":"Campylobacter jejuni.","D":"Clostridioides (antigo Clostridium) difficile."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-252214","number":"252214","sourceNumber":"252214","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 10 anos com diagnóstico de febre reumática, sem cardite, deve manter\nprofilaxia secundária com penicilina benzatina\naté quando? Assinale a alternativa com o esquema\nCORRETO de profilaxia para este caso:","options":{"A":"Penicilina benzatina IM a cada 21 dias até os 21 anos ou 5 anos após o último surto (vale o que\ncobrir maior tempo).","B":"Penicilina benzatina IM a cada 30 dias até os 21 anos ou 10 anos após o último surto (vale o que\ncobrir maior tempo).","C":"Penicilina benzatina IM a cada 15 dias até os 18 anos ou 5 anos após o último surto (vale o que\ncobrir maior tempo).","D":"Penicilina benzatina IM a cada 21 dias até os 25 anos ou 10 anos após o último surto (vale o\nque cobrir maior tempo)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-252215","number":"252215","sourceNumber":"252215","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente 50 anos, sexo masculino, diagnóstico de artrite reumatoide há 5 anos em uso\nde Metotrexato e Prednisona. Vem para consulta\nqueixando de dor em joelho D iniciada há 4\nmeses. Relata ainda febre baixa intermitente e perda ponderal de 3 kg. Ao exame nota-se edema\ncom derrame, calor e limitação de movimentos no joelho D. Tem dor a palpação em punhos, mas\nsem edema ou calor. Qual a provável etiologia da artrite e conduta apropriada?","options":{"A":"Artrite infecciosa / iniciar antibioticoterapia empírica","B":"Atividade da doença / infiltrar joelho com corticoide","C":"Atividade da doença / aumentar corticoide oral","D":"Artrite infecciosa / artrocentese e análise do líquido sinovial"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-208408","number":"208408","sourceNumber":"208408","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 42 anos, sexo masculino, obeso, procura atendimento por crise de\nmonoartrite de joelho direito com início há\n24 horas, de forte intensidade, com calor e derrame\narticular. Relata ser o terceiro episódio de artrite em menos de 1 ano e que as crises melhoram com\nuso de AINH. Assinale a alternativa com a melhor opção para esclarecimento diagnóstico:","options":{"A":"Artrocentese + pesquisa de cristais no líquido sinovial.","B":"Solicitar hemograma.","C":"Solicitar hemocultura.","D":"Dosar ácido úrico sérico e urinário."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-151937","number":"151937","sourceNumber":"151937","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O antibiótico de primeira linha para erradicação do Estreptococo beta hemolítico (do\ngrupo A) da orofaringe, no tratamento da febre reumática é:","options":{"A":"Cefalexina.","B":"Tetraciclina.","C":"Claritromicin.","D":"Penicilina benzatina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-129816","number":"129816","sourceNumber":"129816","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 52 anos, no período de climatério, queixa-se de cansaço em suas atividades\ndiárias, sem outros sintomas. O exame clínico\né normal, exceto pelas mucosas discretamente\nhipocoradas. O hemograma mostra hemoglobina = 10 g/dl; hematócrito = 31%; VCM = 76 fl;\nferritina = 10 ng/ml; ferro = 60 µg/dl e capacidade total de ligação do ferro = 420 µg/dl. O\nprocedimento necessário para o diagnóstico da síndrome anêmica é:","options":{"A":"Investigar presença de sangue oculto nas fezes e o trato digestivo.","B":"Solicitar ureia e creatinina para o diagnóstico de insuficiência renal.","C":"Solicitar TSH, pois é comum hipotireoidismo em mulheres nesta faixa etária.","D":"Iniciar sulfato ferroso e acompanhar com hemograma seriado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-129761","number":"129761","sourceNumber":"129761","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A carência nutricional de ferro afeta o desenvolvimento mental de 40 a 60% das\ncrianças. Assinale a alternativa com as\nprincipais alterações bioquímicas encontradas na depleção\nde ferro SEM anemia:","options":{"A":"Hgb, VCM, RDW normais; ferro sérico e ferritina baixos.","B":"Hbg, ferro sérico e ferritina baixos; RDW e VCM normais.","C":"Hgb, ferro sérico, ferritina e VCM baixos; RDW normal.","D":"Hbg, VCM normais; RDW elevado; ferro sérico e ferritina baixos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-129767","number":"129767","sourceNumber":"129767","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um adolescente de 15 anos apresenta-se com dor no joelho direito. Ao exame físico,\nele não consegue apoiar seu próprio peso\nsobre a articulação afetada. O joelho está dolorido,\nedemaciado, quente, eritematoso e apresenta uma significativa redução da amplitude de\nmovimento. Qual das opções a seguir representa o melhor passo na avaliação?","options":{"A":"Prescrever um curso de esteroides sistêmicos.","B":"Obter mais dados da história, incluindo história sexual.","C":"Marcar uma consulta ambulatorial com ortopedista.","D":"Prescrever anti-inflamatórios."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-103812","number":"103812","sourceNumber":"103812","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O Helicobacter pylori tem sido relacionado à anemia de que tipo?","options":{"A":"Por deficiência de folato.","B":"Perniciosa.","C":"Autoimune.","D":"Ferropriva."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-107800","number":"107800","sourceNumber":"107800","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"MST, masculino, 14 anos, apresenta palidez, anorexia, astenia e sonolência excessiva.\nEstá crescendo muito rápido, segundo informa mãe.\nQual o diagnóstico mais provável?","options":{"A":"Giardíase.","B":"Mononucleose.","C":"Anemia ferropriva.","D":"Anemia megaloblástica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-103834","number":"103834","sourceNumber":"103834","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Anemia hipocrômica e microcítica ocorre principalmente por:","options":{"A":"Deficiência de ácido fólico.","B":"Deficiência de vitamina B12.","C":"Deficiência de G6PD.","D":"Deficiência de ferro."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-81998","number":"81998","sourceNumber":"81998","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação ao papel do hemograma com hematoscopia na avaliação de distúrbios\nhematológicos e do baço, é INCORRETO:","options":{"A":"Reticulocitose e esplenomegalia de tamanho médio são possíveis nas anemias hemolíticas.","B":"Pancitopenia e esplenomegalia maciça podem estar presente na mielofibrose.","C":"Esquizócitos e esplenomegalia afastam o diagnóstico de anemia hemolítica autoimune.","D":"Na leucemia de células cabeludas (tricoleucemia) a esplenomegalia é comum e os linfócitos têm\naspecto hematoscópico característico.","E":"Tanto a reação leucemoide como a leucemia mieloide crônica podem ter desvio à esquerda."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-81136","number":"81136","sourceNumber":"81136","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"MST, masculino,14 anos, apresenta palidez, anorexia, astenia e sonolência excessiva.\nEstá crescendo muito rápido, segundo informa mãe.\nQual diagnóstico mais provável?","options":{"A":"Giardíase","B":"Mononucleose","C":"Anemia ferropriva","D":"anemia megaloblástica","E":"depressão"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-61539","number":"61539","sourceNumber":"61539","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem, 50 anos, com diagnóstico de osteoartrite e uso intermitente de AINH, procura o\nambulatório de Clínica Médica devido ao diagnóstico de anemia. Queixa-se de fadiga com\nfacilidade, taquicardia aos esforços e epigastralgia. Trouxe hemograma com Hb = 10 g/dl, Ht =\n35%, microcitose, hipocromia, anisocitose e ferritina sérica de 20 mcg/l. Em uso de sulfato ferroso\n325 mg 3x/dia. Qual o diagnóstico diferencial e a investigação complementar necessária?","options":{"A":"Talassemia e capacidade de ligação do ferro total.","B":"Perda oculta de gastrointestinal e sangue oculto nas fezes.","C":"Perda oculta gastrointestinal e endoscopia digestiva alta.","D":"Anemia de doença crônica e capacidade de ligação de ferro total.","E":"Anemia de doença crônica e ferro sérico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-60891","number":"60891","sourceNumber":"60891","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre o RDW (red cell distribution width) é INCORRETO:","options":{"A":"Valores de normalidade entre 11% e 16%.","B":"Corresponde a uma medida quantitativa da anisocitose.","C":"Valores aumentados de RDW falam a favor de uma população eritrocitária homogênea.","D":"É obtido a partir do histograma de distribuição das hemácias de acordo com o volume das\ncélulas.","E":"Sua principal utilidade seria numa primeira diferenciação entre a anemia ferropriva e a\nbeta-talassemia heterozigótica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-61531","number":"61531","sourceNumber":"61531","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação aos estágios da deficiência de ferro no organismo, é CORRETO afirmar:","options":{"A":"Depleção de estoque; Hemoglobina normal; VCM diminuído; Ferro sérico diminuído; Ferritina\nnormal.","B":"Depleção de ferro com anemia; Hemoglobina diminuída; VCM normal; Ferro sérico diminuído;\nFerritina normal.","C":"Depleção de estoque; Hemoglobina aumentada; VCM diminuído; Ferro sérico normal; Ferritina\ndiminuída.","D":"Depleção de ferro sem anemia; hemoglobina normal; VCM normal; Ferro sérico diminuído;\nFerritina diminuída.","E":"Depleção de ferro com anemia; Hemoglobina diminuída; VCM aumentado; Ferro sérico\ndiminuído; Ferritina normal."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-61546","number":"61546","sourceNumber":"61546","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"São fatores de risco para o desenvolvimento de anemia ferropriva, EXCETO:","options":{"A":"Aleitamento materno exclusivo até os 6 meses de vida e complementar até 2 anos de idade.","B":"Ocorrência de pólipos e divertículos.","C":"Desnutrição intrauterina.","D":"Prematuridade.","E":"Baixa renda."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-61581","number":"61581","sourceNumber":"61581","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à presença de anemias na infância qual afirmativa NÃO está correta?","options":{"A":"As anemias podem ser decorrentes de alterações na produção; hemólise; perdas sanguíneas.","B":"Correspondem a desordens de produção; desordens imunológicas; falência absoluta da\neritropoiese.","C":"O VCM (Volume Corpuscular Médio) está aumentado na deficiência da vitamina B12 e na\ndeficiência de ácido fólico.","D":"São consideradas desordens por destruição do eritrócito; defeitos estruturais das hemáceas\n(congênitos); desordens imunológicas; destruição não mediada por anticorpos.","E":"A doença falciforme, as talassemias e as deficiências enzimáticas cursam com anemia devido a\ndesordens por destruição dos eritrócitos (hemólise)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-60883","number":"60883","sourceNumber":"60883","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Qual seria a ação política efetiva para resolver o problema da anemia ferropriva em\nlactentes e pré-escolares em nosso país?","options":{"A":"Aplicar doses preventivas de ferro nos dias nacionais de vacinação.","B":"Contraindicar a alimentação com leite de vaca para todas as crianças.","C":"Treinar pediatras para prevenção do ferro profilático.","D":"Conscientizar as mães para o problema.","E":"Garantir a fortificação exclusiva vit. \"D\"."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-60819","number":"60819","sourceNumber":"60819","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na anemia hipocrômica microcítica por deficiência ou falta de aproveitamento de ferro\nencontra-se:","options":{"A":"CHCM e VCM normal, RDW baixo","B":"CHCM e VCM baixo, RDW normal","C":"CHCN e VCN baixo, RDW aumentado","D":"CHCM e VCM aumentdo, RDW baixo","E":"CHCM e VCM aumentando, RDW aumentado"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-46712","number":"46712","sourceNumber":"46712","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Analise as afirmativas quanto à Anemia Ferropriva e assinale a INCORRETA:","options":{"A":"O melhor exame para estimar o ferro total do organismo, particularmente o dos depósitos, é o\nferro sérico.","B":"Os principais sinais e sintomas são palidez, adinamia, cefaleia, tontura, zumbido no ouvido,\nalterações na visão, dispneia, taquicardia e baixo desempenho no trabalho.","C":"É uma manifestação tardia e insidiosa da carência do ferro e surge quando as reservas de ferro\nesgotam-se em virtude do balanço negativo.","D":"As causas de carência podem ser classificadas: menor ingestão do nutriente, menor absorção\nintestinal, defeitos do transporte ou\nmetabolismo, aumento das excreções ou das perdas, aumento\ndas necessidades fisiológicas ou patológicas.","E":"A mais importante medida do tratamento desta anemia consiste em identificar a causa e\nremovê-la, se possível."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-46669","number":"46669","sourceNumber":"46669","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Pré-escolar com quatro anos vai a sua pediatra, trazido pela sua genitora, com história\nde palidez. A criança está com bom estado geral,\na alimentação é adequada e a família é de bom\nnível socioeconômico. O pai é de origem portuguesa e a mãe é italiana. Quanto ao exame\nlaboratorial: Hb: 10 g/dl; VCM: 60: SEM ANISOCITOSE. Não houve alteração de laboratórios após\ntratamento com ferro por um mês. O resultado mais provável da eletroforese de hemoglobina é:","options":{"A":"Presença de HbS.","B":"Presença de HbS e HbC.","C":"HbA2 baixa e HbF baixa.","D":"HbA2 elevada e presença de HbS.","E":"HbA2 elevada e HbF aumentada."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-46634","number":"46634","sourceNumber":"46634","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Que suplementação deve receber um filho de mãe vegetariana que não ingere produtos\nanimais, quando este estiver em aleitamento materno?","options":{"A":"Cálcio.","B":"Vit A.","C":"Vit C.","D":"Vit D.","E":"Vit B12."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-34113","number":"34113","sourceNumber":"34113","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A anemia por deficiência de ferro caracteriza-se, sobretudo por:","options":{"A":"Macrocitose, hipocromia e neutrófilos grandes com núcleo hipersegmentado.","B":"Microcitose, hipocromia e RDW alto.","C":"Microcitose, hipocromia, células em alvo e pontilhado basófilo no esfregaço de sangue\nperiférico.","D":"Microcitose, hipocromia e índice de anisocitose (RDW) normal.","E":"Normocitose, hipocromia e índice de anisocitose (RDW) alto."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-26449","number":"26449","sourceNumber":"26449","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Os mecanismos principais da anemia da insuficiência renal crônica são deficiências de:","options":{"A":"ferro e hemólise no sistema extracorpóreo.","B":"eritropoietina e de vitamina B12.","C":"ferro, perda sanguínea e intoxicação por alumínio.","D":"eritropoietina e diminuição da sobrevida dos eritrócitos.","E":"ferro e vitamina B12."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-26608","number":"26608","sourceNumber":"26608","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O que caracteriza anemia ferropriva?","options":{"A":"Nível sérico do ferro normal, transferrina elevada e RDW normal","B":"Nível sérico do ferro elevado, transferrida elevada e RDW baixo","C":"Nível sérico do ferro diminuído, transferrina elevada e RDW baixo","D":"Nível sérico do ferro diminuído, tranferrina baixa e RDW aumentado","E":"Nível sérico do ferro normal, tranferrina baixa e RDW aumentado"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-26514","number":"26514","sourceNumber":"26514","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Lactante, 8 meses, com evolução de dois meses com quadro de anemia, recebeu\ntransfusão de concentrado de hemácias há 15\ndias. Apresenta edema em mão e pés, distensão\nabdominal, febre e ao raio-x de tórax: condensação em terço inferior de pulmão direito. Hemograma\ncom leucocitose, anemia, plaquetose e reticulócitos aumentado. Mãe com história de anemia, foi\nsubmetida a colocistectomia para tratamento de litíase biliar. Qual o diagnóstico mais provável e\nqual exame indicado para o diagnóstico de certeza?","options":{"A":"Esferocitose, curva de fragilidade osmótica;","B":"Anemia Falciforme, eletroforese de hemoglobina;","C":"Anemia de Fanconi. Mielograma;","D":"Leucemia linfoide aguda. Mielograma;","E":"Linfoma de Hodgkin, biópsia de medula;"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-324695","number":"324695","sourceNumber":"324695","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina, 5 anos de idade, é atendida na UPA com história de dor no joelho esquerdo,\nreferindo, também, aumento de volume e limitação\nde movimentos, principalmente ao acordar.\n\nRelata que essa dor iniciou há 2 meses, sem trauma, evoluindo para acometimento de ombro\nesquerdo, joelho direito e quadris,\nbilateralmente. Há 15 dias, vem com envolvimento de punhos,\ncom mesmas características, além de febre com exantema. Queixa-se de dor ocular, que \"\"piora\ncom luz forte\"\" e que seus olhos ficam, permanentemente, vermelhos. Relata, ainda, dor ao\nmastigar e abrir a boca. Ao exame, a menor apresenta hiperemia ocular. Temperatura 38,0ºC.\nNota-se exantema cor de salmão em axilas e zonas de pressão. Apresenta discreta\nhepatoesplenomegalia. Linfonodos sem características patológicas. Nas articulações em foco,\nobservam-se edema, calor e redução da amplitude de movimentos. Hemograma mostra 15mil\nleucócitos/mm³ às custas de polimorfonucleares, com 400mil plaquetas/mm³. Considerando o\ndiagnóstico mais provável, sobre a avaliação laboratorial dessa criança, é correto afirmar:","options":{"A":"Fator Antinuclear é sempre positivo.","B":"Proteína C Reativa não é exame indicado.","C":"VHS normal não exclui diagnóstico","D":"Fator Reumatóide é positivo em mais de 80% dos casos iniciais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-324696","number":"324696","sourceNumber":"324696","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina, 5 anos de idade, é atendida na UPA com história de dor no joelho esquerdo,\nreferindo, também, aumento de volume e limitação\nde movimentos, principalmente ao acordar.\n\nRelata que essa dor iniciou há 2 meses, sem trauma, evoluindo para acometimento de ombro\nesquerdo, joelho direito e quadris,\nbilateralmente. Há 15 dias, vem com envolvimento de punhos,\ncom mesmas características, além de febre com exantema. Queixa-se de dor ocular, que \"\"piora\ncom luz forte\"\" e que seus olhos ficam, permanentemente, vermelhos. Relata, ainda, dor ao\nmastigar e abrir a boca. Ao exame, a menor apresenta hiperemia ocular. Temperatura 38,0ºC.\nNota-se exantema cor de salmão em axilas e zonas de pressão. Apresenta discreta\nhepatoesplenomegalia. Linfonodos sem características patológicas. Nas articulações em foco,\nobservam-se edema, calor e redução da amplitude de movimentos. Hemograma mostra 15mil\nleucócitos/mm³ às custas de polimorfonucleares, com 400mil plaquetas/mm³. Considerando a febre\nque, usualmente, acompanha quadros semelhantes, pode-se afirmar que costuma ser:","options":{"A":"Diária e elevada, em picos, com retorno à temperatura normal.","B":"Irregular, com variação de horários e dias sem febre.","C":"Contínua e baixa, associada à cefaleia.","D":"Elevada e contínua, com prostração intensa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-324697","number":"324697","sourceNumber":"324697","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina, 5 anos de idade, é atendida na UPA com história de dor no joelho esquerdo,\nreferindo, também, aumento de volume e limitação\nde movimentos, principalmente ao acordar.\n\nRelata que essa dor iniciou há 2 meses, sem trauma, evoluindo para acometimento de ombro\nesquerdo, joelho direito e quadris,\nbilateralmente. Há 15 dias, vem com envolvimento de punhos,\ncom mesmas características, além de febre com exantema. Queixa-se de dor ocular, que \"\"piora\ncom luz forte\"\" e que seus olhos ficam, permanentemente, vermelhos. Relata, ainda, dor ao\nmastigar e abrir a boca. Ao exame, a menor apresenta hiperemia ocular. Temperatura 38,0ºC.\nNota-se exantema cor de salmão em axilas e zonas de pressão. Apresenta discreta\nhepatoesplenomegalia. Linfonodos sem características patológicas. Nas articulações em foco,\nobservam-se edema, calor e redução da amplitude de movimentos. Hemograma mostra 15mil\nleucócitos/mm³ às custas de polimorfonucleares, com 400mil plaquetas/mm³. Considerando a\nhipótese diagnóstica mais provável, a complicação grave mais temível é:","options":{"A":"Insuficiência renal crônica.","B":"Insuficiência hepática aguda.","C":"Lesão de válvulas cardíacas.","D":"Síndrome de ativação macrofágica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-62857","number":"62857","sourceNumber":"62857","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, quatro anos de idade, apresenta dores intensas nas articulações de joelhos,\npunhos e tornozelos, há cerca de uma\nsemana, com febre e dificuldade para deambulação. Nos\nantecedentes, consta episódio semelhante aos dois anos de idade, ao exame, fácies de sofrimento,\nesclerótica, ictérica +++, palidez cutâneo-mucosa ++. Ausculta pulmonar com roncos. Abdome com\nfígado a 2 cm do RCD, baço palpável a 3 cm do RCE. Hemograma com 6,8 de HB, 20,3 de HTc,\ncom hipocromia, microcitose policromasia e poiquilocitose, reticulocitose importante de 15%. A\npatologia mais provável e o exame para o diagnóstico etiológico são, respectivamente:","options":{"A":"deficiência de GH e dosagem de GH.","B":"anemia falciforme e eletroforese de hemoglobina.","C":"leucemia e mielocultura.","D":"septicemia e hemocultura.","E":"sífilis congênita e VDLR quantitativo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-49276","number":"49276","sourceNumber":"49276","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, quatro anos de idade, iniciou com febre alta há três dias, associada a vômitos\ne hiporexia, que evoluíram com astenia intensa\ne palidez cutânea. O exame físico mostrava REG,\nhipoativa, taquipneica, descorada (+++/+4), pesando 14,5 kg, FC: 152 bpm, FR: 40 ipm, presença\nde SS +++/+6, plurifocal, baço a 6 cm RCE, fígado não palpável. Realizou sorologia: rk39, hepatites\nA, B e C, e TORCHS, todos negativos. Ácido fólico: 7,8 (VN 3-50), vitamina B12: 432 (VN 174-878).\nMielograma: hiperplasia da série eritrocítica e granulocítica (afastada aplasia medular, leucemia,\ncalazar). Hb: 9,4, Ht: 27, leuc.: 8600 (S52/E1/L42/M5), plaq: 339000/mm³, numerosos esferócitos\nno sangue periférico. Eletroforese de Hb: (A1 96,3%/A2 2,7%/F4%), reticulócitos: 8,7%, ferritina:\n115,7, G6PD: (-), BT: 3,2 (Bl: 2,6), curva de fragilidade osmótica com fragilidade osmótica\naumentada. O diagnóstico mais provável para o caso é:","options":{"A":"anemia falciforme.","B":"anemia esferocítica.","C":"intoxicação medicamentosa.","D":"deficiência enzimática de G6PD.","E":"calazar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-34994","number":"34994","sourceNumber":"34994","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Referente ao transporte de oxigênio no organismo humano, contribuem para o efeito\nBohr, EXCETO:","options":{"A":"Acidose metabólica.","B":"2,3-difosfoglicerato.","C":"Febre.","D":"Hemoglobina fetal.","E":"Altitude."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-34968","number":"34968","sourceNumber":"34968","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, 7 anos de idade, portador de anemia falciforme, em acompanhamento\nambulatorial, usando ácido fólico, com média de\nhemoglobina de 9,0 g. Apresenta palidez súbita,\nsudorese, queda do estado geral e febre moderada. O hemograma com Hb de 3,8 g e\nreticulopenia. A complicação mais provável dessa patologia é:","options":{"A":"Crise aplástica;","B":"Sequestro esplênico;","C":"Síndrome torácica aguda;","D":"Acidente vascular cerebral;","E":"Pneumonia subaguda."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-27445","number":"27445","sourceNumber":"27445","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Define-se classicamente transfusão maciça como sendo a:","options":{"A":"reposição de, pelo menos, uma volemia, em um intervalo de até 24 horas.","B":"reposição de, pelo menos, uma volemia, em um intervalo de até 12 horas.","C":"administração de mais de 4 unidades de concentrado de hemácias em curto período de tempo .","D":"administração de mais de 6 unidades de concentrado de hemácias em curto período de tempo.","E":"administração de mais de 8 unidades de concentrado de hemácias em curto período de tempo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-27461","number":"27461","sourceNumber":"27461","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, 9 anos de idade, apresenta quadro de tosse, febre e dor torácica, além de\ndores nos membros inferiores, anorexia e\nurina escura. Tem diagnóstico de doença falciforme. Ao\nexame, estado geral comprometido, fácies de sofrimento, esclerótica ictérica, palidez\ncutaneomucosa. Ausculta pulmonar com roncos e crépito nas bases. Ausculta cardíaca com SS em\nmesocárdio. Abdome com fígado a 10 cm do RCD, baço não palpável. Hemograma com Hb: 6,5,\nHtc: 28%, 29.800 leucócitos, segmentados de 72%, bastões 2%, linfócitos de 25%, monócitos 1%,\n\neosinófilos 0%. Plaquetas: 434.000 mm, bilirrubinas BI: 8,9, BT: 12,3. Reticulócitos de 6%.\nSaturando 92%, em ar ambiente. Nesse paciente, o evento clínico agudo a ser considerado é:","options":{"A":"síndrome torácica aguda.","B":"sequestro esplênico.","C":"crise aplástica.","D":"crise álgica.","E":"hepatite subaguda."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-27465","number":"27465","sourceNumber":"27465","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, 9 anos de idade, apresenta quadro de tosse, febre e dor torácica, além de\ndores nos membros inferiores, anorexia e\nurina escura. Tem diagnóstico de doença falciforme. Ao\nexame, estado geral comprometido, fácies de sofrimento, esclerótica ictérica, palidez\ncutaneomucosa. Ausculta pulmonar com roncos e crépito nas bases. Ausculta cardíaca com SS em\nmesocárdio. Abdome com fígado a 10 cm do RCD, baço não palpável. Hemograma com Hb: 6,5,\nHtc: 28%, 29.800 leucócitos, segmentados de 72%, bastões 2%, linfócitos de 25%, monócitos 1%,\n\neosinófilos 0%. Plaquetas: 434.000 mm, bilirrubinas BI: 8,9, BT: 12,3. Reticulócitos de 6%.\nSaturando 92%, em ar ambiente. O tratamento do\nevento descrito deve ser realizado em unidade\nhospitalar e considerar aspectos importantes, exceto:","options":{"A":"hidratação rigorosa com taxa hídrica de 150%.","B":"oxigenoterapia, se saturação de oxigênio \"menor que\" 90%.","C":"antibioticoterapia de amplo espectro.","D":"transfusão sanguínea com o objetivo de manter HbS \"menor que\" 30%.","E":"analgesia criteriosa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-215612","number":"215612","sourceNumber":"215612","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Embora os estudos epidemiológicos sobre a Artrite Psoríaca (AP) tenham sido\ninfluenciados por uma série de fatores,\nincluindo a falta de consenso em relação aos critérios de\nclassificação, a frequência da psoríase em diferentes áreas geográficas, os diversos métodos\nutilizados no diagnóstico, bem como os diferentes desenhos de estudos avaliados, determinam os\ndados abaixo. Indique a alternativa que se mostra INCORRETA:","options":{"A":"Dois aspectos devem ser considerados na análise epidemiológica: as incidência e prevalência e\na frequência de AP em pacientes com psoríase.","B":"Estudos revelaram incidência de 3,0-23,1 casos/100.000 pessoas e prevalência de 1-420\ncasos/100.000 pessoas.","C":"Resultados similares entre os países ocidentais.","D":"Essa grande variação decorre especialmente dos diferentes critérios utilizados no diagnóstico,\nmas não do tempo de evolução da psoríase\ncutânea."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-139756","number":"139756","sourceNumber":"139756","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Está indicado, rotineiramente, o uso de Penicilina, via intramuscular, profilática, em:","options":{"A":"Escolares com febre reumática e em crianças com cardiopatias congênitas com hiperfluxo\npulmonar.","B":"Crianças e adolescentes com febre reumática e em lactentes e pré-escolares com doença\nfalciforme.","C":"Escolares com glomerulonefrites pós-estreptocócica e em crianças e adolescentes com fibrose\ncística.","D":"Todos os casos acima mencionados."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-321302","number":"321302","sourceNumber":"321302","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 74 anos, com hipertensão arterial sistêmica e insuficiência renal crônica não\ndialítica, há 4 semanas com artralgia\nintermitente em mãos, pés e joelhos e há 2 dias com piora do\nquadro. Ao exame físico: nódulos de Bouchard, nódulo em face extensora de antebraço direito e\nartrite em joelho esquerdo. Exames realizados: hemograma normal; PCR 7.6 mg/dl (VR < 0,6\nmg/dl); Cr 1.6 mg/dl (VR 0.5-1.1 mg/dl) Ur 60 mg/dl (VR 10-50 mg/dl); fator reumatoide 25 UI/ml (VR\n\n< 20 UI/ml). Considerando o diagnóstico mais provável, qual a conduta farmacológica indicada?","options":{"A":"Corticoide.","B":"Alopurinol.","C":"Ceftriaxona.","D":"Metotrexato."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-292821","number":"292821","sourceNumber":"292821","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem, 33 anos, obeso, etilista, hipertenso em uso de hidroclorotiazida, com história\nde alta hospitalar, há 24 horas, após\ncolecistectomia, procura UPA com relato de dor intensa e\nalodínia em hálux esquerdo há 3 horas. Ao exame: estado geral regular, fácies de dor, T: 37,9°C;\nabdome flácido e ferida operatória sem sinais flogísticos; sistema osteoarticular: edema, rubor e\ndor\nà movimentação de hálux. Qual conduta está indicada neste momento?","options":{"A":"Coleta de duas amostras de hemoculturas.","B":"Punção de metatarsofalangiana.","C":"Dosagem de ácido úrico sérico.","D":"Iniciar cefalexina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-20/292821.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-259724","number":"259724","sourceNumber":"259724","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 33 anos, há 2 meses apresenta fadiga, dor em mãos, joelho esquerdo e\ntornozelo direito que pioram no repouso e\nmelhoram com atividade física. Nega queixas axiais. Há\n1 semana passou a apresentar edema difuso em 3° quirodáctilo direito. Nega alterações genitais,\nurinárias e intestinais. Ao exame: lesões eritematodescamativas em região extensora de cotovelos\ne em sulco interglúteo, depressões e sulcos transversais ungueais; dor e edema em punho direito,\n2° interfalangiana proximal esquerda e joelho esquerdo, e dor e calor em tornozelo direito. Traz os\nexames complementares: Hb 11,2 mg/dl (VR 12 mg/dl); PCR 1,65 mg/dl (VR < 0,6 mg/dl); TGO 35\ne TGP 25 (VR < 50 UI/L); ácido úrico: 5,5 mg/dl (VR 6,0 mg/dl); Cr 0,6 mg/dl (VR 1,0 mg/dl);\nsorologias para hepatites B e C, sífilis e HIV: negativas; radiografias de mãos, joelhos e\ntornozelos:\nsem alterações; FAN, fator reumatoide e anti-CCP negativos. LEGENDA: Hb: hemoglobina; VR:\nValor de Referência; PCR: Proteína C-Reativa; Cr: creatinina; FAN: Fator Antinúcleo; anti-CCP:\nanticorpos antipeptídeo citrulinado. Diante da hipótese diagnóstica mais provável, qual tratamento a\nser prescrito?","options":{"A":"Colchicina 0,5 mg/dia.","B":"Hidroxicloroquina mg/dia.","C":"Metotrexato 20 mg/semana.","D":"Sulfato de glucosamina 1.500 mg/dia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-234035","number":"234035","sourceNumber":"234035","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 53 anos relata dor e edema em mãos e punhos há aproximadamente quatro\nmeses. Há ainda adinamia durante todo o período, além de rigidez matinal de uma hora\naproximadamente. Ao exame: sinovite do primeiro ao quinto metacarpofalangianas e\ninterfalangianas proximais de ambas as mãos bem como calor e rubor em joelhos. Trouxe exames\nrealizados previamente: fator reumatoide ELISA 120 UI/ml (VR: < 15 UI/ml). Sobre a doença em\nquestão, marque a alternativa que contempla a hipótese clínica mais provável e um exame mais\nespecífico para o quadro clínico, respectivamente.","options":{"A":"Artrite reumatoide e antipeptídeo citrulinado.","B":"Lúpus eritematoso sistêmico e fator antinúcleo.","C":"Hepatite por vírus do tipo C e proteína C-reativa.","D":"Crioglobulinemia mista tipo II e radiografia de mãos e punhos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-20/234035.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-234055","number":"234055","sourceNumber":"234055","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança de 2 anos, sexo feminino, com história de que há 6 semanas vem\napresentando dor e edema em articulações dos\njoelhos acompanhados de febre intermitente. Há\n15 dias mãe relata febre alta diária e piora do quadro articular em joelhos, quadril e tornozelos\nque\ndificulta a deambulação, principalmente, pela manhã. Refere exantema róseo e macular que se\nintensifica na vigência da febre. Ao exame físico, apresenta palidez cutânea, adenomegalia\ncervical, axilar e inguinal; esplenomegalia leve e presença de sinais flogísticos em joelhos e\ntornozelos. Ao hemograma, observa-se anemia normocrômica, leucocitose com neutrofilia e desvio\nà esquerda. Proteína C-reativa e velocidade de hemossedimentação aumentados, fator reumatoide\nnegativo. Mielograma hipercelular sem células blásticas. Qual o diagnóstico mais provável?","options":{"A":"Febre reumática.","B":"Leucemia aguda.","C":"Artrite idiopática juvenil.","D":"Mononucleose infecciosa."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-199788","number":"199788","sourceNumber":"199788","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 60 anos deu entrada no pronto atendimento com dor, edema e eritema em\njoelho esquerdo há 12 horas. Sem outros sinais e sintomas. Realizou artroplastia total de quadril\nesquerdo há 5 dias. É portador de diabetes mellitus e hipertensão arterial sistêmica, em uso de\nhidroclorotiazida, insulina e enalapril. Exames laboratoriais: proteína C-reativa = 6,0 mg/dl (VR <\n0,6\nmg/dl); creatinina = 1,3 mg/dl (VR = 0,6?1,2 mg/dl); ureia = 56 mg/dl (VR = 20?40 mg/dl); ácido\núrico = 5,8 mg/dl (VR = 2,5?7,0 mg/dl); hemograma normal. Análise do líquido sinovial de joelho\nesquerdo: turvo, amarelado, com presença de elementos alongados e agulhados, intracelulares, de\nbirrefringência negativa à luz polarizada, com 40.000/?L de leucócitos, predomínio de\npolimorfonucleares (60%) e coloração Gram-negativa. LEGENDA: VR = Valor de Referência. Qual\né o tratamento medicamentoso indicado?","options":{"A":"Colchicina.","B":"Alopurinol.","C":"Gentamicina + oxacilina.","D":"Rifampicina + isoniazida + pirazinamida + etambutol."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-199698","number":"199698","sourceNumber":"199698","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Rapaz de 13 anos tem alta hospitalar após seu último surto agudo de febre reumática\napresentando lesão valvar residual moderada. No 1º episódio, aos 8 anos, foi diagnosticada\nendocardite. Qual a recomendação em relação à duração da profilaxia secundária da febre\nreumática, nesse caso?","options":{"A":"Até 18 anos de idade ou 3 anos após último surto.","B":"Até 21 anos de idade ou 5 anos após último surto.","C":"Até 25 anos de idade ou 10 anos após último surto.","D":"Até 40 anos de idade ou por toda a vida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-172995","number":"172995","sourceNumber":"172995","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, sexo feminino, 46 anos, queixa de fadiga e dor em punhos há 3 meses, com\nrigidez matinal de 45 minutos. Nega outros sinais e sintomas associados. Nega viagens,\nmedicações e doenças prévias. Ao exame físico: dor, edema e limitação funcional em punhos, 2°\nMetacarpofalangiana (MCF) direita, 2° interfalangiana proximal esquerda e 4° MCF esquerda, sem\noutros achados. Exames: proteína C-reativa = 2,87 mg/dl (VR < 0,5 mg/dl); fator reumatoide = 9,4\nUI/ml (VR < 10,5 UI/ml); hemograma completo, creatinina, TSH, sumário de urina e radiografia de\ntórax: normais; sorologias para sífilis, hepatites, HIV e arboviroses: não reagentes. Que exame e\nalteração seriam úteis para confirmar a principal suspeita diagnóstica?","options":{"A":"Radiografias de mãos com osteófitos e esclerose subcondral.","B":"Anticorpos antipeptídeos citrulinados cíclicos positivos em baixos títulos.","C":"Eletroforese de proteínas séricas com hipergamaglobulinemia policlonal.","D":"Fator antinuclear positivo, título 1:80, padrão nuclear pontilhado fino denso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-150803","number":"150803","sourceNumber":"150803","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 40 anos retorna ao ambulatório para reavaliação. Tem queixas de dor\narticular em mãos, cotovelos, tornozelos e\njoelhos, há cerca de 3 meses, com rigidez matinal que\ndura cerca de 20 minutos. Além disso, refere episódios de febre não mensurada e anorexia. Ela\ntrabalha como digitadora e tem história familiar de psoríase. Ao exame físico, você observa sinais\nde artrite em todas as interfalangianas proximais, segunda à quarta metacarpofalangianas\nbilateralmente, punhos, cotovelos e tornozelos. O hemograma revela leve anemia, VHS e PCR\nelevados, FAN = 1:80 (pontilhado fino), fator reumatoide negativo, sumário de urina, C3 e C4\nnormais. Baseado nesses dados, qual o diagnóstico mais adequado para essa paciente?","options":{"A":"Osteoartrite.","B":"Artrite psoriásica.","C":"Lúpus eritematoso.","D":"Artrite reumatoide."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-150830","number":"150830","sourceNumber":"150830","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma criança de 6 anos de idade chega ao pronto-socorro com queixas de febre alta há\ndois dias associadas com dor intensa e edema na articulação do joelho esquerdo. O resultado da\nbacterioscopia do material coletado na punção articular revelou cocos gram negativos. Qual a\nmelhor opção de tratamento antimicrobiano?","options":{"A":"Amicacina.","B":"Ceftriaxona.","C":"Oxacilina.","D":"Cefipime."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-127000","number":"127000","sourceNumber":"127000","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 45 anos é avaliada em ambulatório por poliartrite em ambas as mãos\n(interfalangianas proximais e\nmetacarpofalangianas) e joelhos, além de febre (até 38°C) e astenia.\nO quadro se iniciou há 2 meses e vem piorando. Exame físico confirma artrite em todas as\narticulações referidas, além de esplenomegalia (5 cm abaixo do rebordo costal esquerdo). Exames\nlaboratoriais ? hemograma: Hb = 12,5 g/dl; VCM = 93; leucócitos = 4.000 (segmentados = 30%;\neosinófilos = 1%; basófilos = 0,1%; linfócitos = 60%; monócitos = 8,9%); plaquetas = 150.000/mm³;\nC3 = 92 mg/dl (normal = 88?201); C4 = 20 mg/dl (normal = 12?45); creatinina = 0,8 mg/dl; VHS =\n105 mm/h; PCR = 6 mg/dl (normal até 0,3); sorologias para HIV, hepatites virais, sífilis, CMV, EBV e\nenterovírus negativas. FAN reagente 1:80 (padrão nuclear pontilhado fino); fator reumatoide = 130\nUI/ml (normal até 15); TSH = 2,5 mUI/L (normal = 0,5?5,4). Antes do resultado dos exames, foi\niniciada prednisona 10 mg por dia. No retorno, após 1 semana de tratamento, a paciente referida\nmelhora da dor e da disposição e negava novos episódios de febre; exame físico evidenciava\ndiscreta melhora. Com base nesses dados, qual conduta deve ser tomada nesse momento?","options":{"A":"Início de metotrexato.","B":"Dosagem de anti-CCP.","C":"Realização de mielograma.","D":"Aumentar dose de prednisona."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-102125","number":"102125","sourceNumber":"102125","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo feminino, 40 anos, testemunha de Jeová, procura ambulatório com\ndores constantes no baixo ventre em decorrência\nde um útero miomatoso. Ao exame físico,\nobserva-se massa palpável e os exames complementares estão normais, exceto por uma discreta\nanemia, hemoglobina de 10,5 g/dl e hematócrito de 38%. Considerando a questão legal frente a\nesta paciente, qual a melhor opção a ser tomada diante da possibilidade de transfusão sanguínea?","options":{"A":"Transfusão de sangue total autólogo fresco.","B":"Uso de hemácias autólogas armazenadas.","C":"Contraindicar a operação.","D":"Operar sem transfusão."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-65723","number":"65723","sourceNumber":"65723","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 60 anos foi internada com síndrome coronariana aguda. No 5º dia de\ninternação, foi diagnosticada com infecção do\ntrato urinário, sendo medicada com ceftriaxona, 2 g\npor dia, por via venosa. No 11º dia, apresentou piora hemodinâmica, precordialgia, sudorese,\npalidez cutâneo-mucosa e taquicardia. Não apresentava hepatoesplenomegalia. Resultados de\nexames laboratoriais no momento mostravam: hemácias: 1.450.000/mm³; hematócrito: 17,5%;\nhemoglobina: 6,5 g/dl; VCM: 120 fl; HCM = 36,8 pg; CHbCM = 30 g/dl; RDW = 26 %. Reticulócitos:\n18,5 %; esfregaço periférico com presença de anisocitose ++/4+; macrocitose +++/4+; microcitose\n\n+/4+; presença de esferócitos e policromasia. Leucócitos: 8.500/mm³ com diferencial dentro da\nnormalidade e plaquetas: 325.000/mm³; LDH = 1.200 UI/L. O exame colhido na admissão mostrou\nHb de 13,0 g/dl. Qual a conduta terapêutica mais adequada?","options":{"A":"Transfusão sanguínea e corticoterapia IV.","B":"Transfusão sanguínea e ciclofosfamida IV.","C":"Transfusão sanguínea.","D":"Corticoterapia IV.","E":"Rituximabe IV."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-65746","number":"65746","sourceNumber":"65746","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma criança de dois anos de idade, com dieta predominantemente láctea, é atendida\nno centro de saúde. O médico decide utilizar\ncompostos à base de ferro. Que orientações o médico\ndeve fornecer à família?","options":{"A":"Os estoques são recompostos nos primeiros 15 dias do tratamento.","B":"O ferro é mais bem absorvido quando administrado após a refeição de sal.","C":"Podem-se oferecer chás, leite, cereais e fibras, pois não interferem na absorção de ferro.","D":"Devem-se oferecer frutas cítricas e carboidratos, pois facilitam a absorção do ferro não heme.","E":"Em casos de crianças que aceitam mal a medicação, a alternativa é a transfusão de glóbulos\nvermelhos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-51211","number":"51211","sourceNumber":"51211","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Qual é a afirmação correta sobre as anemias microcíticas e hipocrômicas?","options":{"A":"A dosagem da ferritina sérica isoladamente é um parâmetro pouco útil para a avaliação do\nestoque de ferro.","B":"A anemia da doença renal crônica, desde o estágio inicial, caracteriza-se por ferro sérico baixo\ne\nTIBC elevada.","C":"A hiperplasia eritroide e o esfregaço com mais de 50% de rouleaux são observados quando os\nníveis de hemoglobina estão entre 7-8 g/dl.","D":"O diagnóstico diferencial de microcitose inclui deficiência de ferro, betatalassemia, intoxicação\npor chumbo e hemoglobinopatia Lepore."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-51228","number":"51228","sourceNumber":"51228","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 58 anos apresenta dormência inicialmente nas mãos e, posteriormente, já\nhá 2 anos, em ambos os pés e pernas\ndistais. A marcha é instável. Fez gastrectomia total há 10\nanos por neoplasia. Apresenta manchas hipocrômicas, descamativas, no pescoço e tórax. Há\nglossite e queilose. Reflexo aquileu ausente bilateralmente. Glicemia de jejum 101 mg/dl,\nhematócrito 28 g/dl, volume corpuscular médio 120 fl, VHS 22 mm. ECG normal. Qual é a causa do\nquadro clínico do paciente?","options":{"A":"Deficiência de vitamina B12.","B":"Intoxicação por arsênico.","C":"Dermatomiosite.","D":"Hanseníase."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-141623","number":"141623","sourceNumber":"141623","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A anemia ferropriva é uma das mais frequentes anemias carenciais. Na avaliação de\numa criança com anemia ferropriva, é\ncaracteristicamente encontrado um aumento de:","options":{"A":"Ferritina sérica.","B":"Volume corpuscular médio.","C":"Hemoglobina globular média.","D":"Capacidade de ligação com o ferro."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-45379","number":"45379","sourceNumber":"45379","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação às anemias na infância, é correto afirmar:","options":{"A":"O diagnóstico laboratorial da anemia ferropriva inclui ferro sérico e ferritina sérica baixos,\ncapacidade total de ligação do ferro baixa e saturação de transferrina alta.","B":"A deficiência de B12 e as talassemias são exemplos clássicos de anemias macrocíticas.","C":"Nas crianças com anemias hemolíticas esferocíticas estão contraindicados o uso de sulfas e\nquinolonas.","D":"Baixo peso ao nascimento, desmame precoce e baixa disponibilidade de ferro na dieta\npredispõem as anemias ferroprivas.","E":"Lactentes com deficiência de ferro quando apresentam alterações de desenvolvimento e\ncomportamento, geralmente são reversíveis após o tratamento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-32511","number":"32511","sourceNumber":"32511","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A transfusão maciça é definida como a reposição do volume sanguíneo do paciente\ncom concentrados de hemácias em 24h ou a transfusão\nde mais de 10 unidades de sangue em\npoucas horas. Em consequência disso pode ocorrer:","options":{"A":"Acidose metabólica.","B":"Aumento do 2,3-DPG.","C":"Hipercalemia.","D":"Hipercalcemia.","E":"Aumento na concentração sérica dos fatores V e VIII da coagulação."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-36987","number":"36987","sourceNumber":"36987","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 70 anos comparece para que seja avaliada a anemia. Seus exames revelam\nHb: 8,5 g/dl, VCM: 112 fL, LDH: 2.650 U/L.\nNo esfregaço do sangue periférico, há macro-ovalócitos\ne neutrófilos hipersegmentados. Há história de cirurgia de ?retirada do estômago? por úlcera há\noito anos. Ele não faz uso de medicações habitualmente. Qual o diagnóstico mais provável?","options":{"A":"Anemia Hemolítica autoimune.","B":"Deficiência de ácido fólico.","C":"Síndrome mielodisplásica.","D":"Deficiência de vitamina B12."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-32538","number":"32538","sourceNumber":"32538","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menino de 7 anos, com anemia ferropriva, em uso de sulfato ferroso (4 mg/kg/dia de\nferro elementar) há 5 dias. O médico do PSF\ndeseja assegurar-se de que a prescrição está sendo\ncumprida e de que está havendo uma resposta terapêutica satisfatória. Dentre os exames abaixo,\nqual o mais indicado para essa avaliação, com menos de uma semana de tratamento?","options":{"A":"Dosagem de ferro sérico.","B":"Contagem de reticulócitos.","C":"Dosagem de hemoglobina.","D":"Eletroforese de hemoglobina.","E":"Dosagem de ferritina sérica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-22824","number":"22824","sourceNumber":"22824","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"São condições associadas a hemólise, EXCETO:","options":{"A":"púrpura trombocitopênica trombótica","B":"deficiência de glicose-6-fosfato desidrogenase","C":"válvula mitral metálica","D":"aplasia pura de células vermelhas","E":"infecção por Clostridium"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-24311","number":"24311","sourceNumber":"24311","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 64 anos submetido à gastrectomia total por adenocarcinoma gástrico há 08\nmeses evolui com cansaço aos médios esforços,\npalidez cutâneomucosa e parestesias em MMII.\nTraz um hemograma que revela HT: 27% Hb: 8,2g/dl e VCM: 108 fl. Como devo proceder?","options":{"A":"Penso em anemia ferropriva por recidiva da lesão e solicito exames da cinética do ferro e\nendoscopia digestiva.","B":"Penso em anemia secundária à manifestação paraneoplásica e solicito TC de abdome.","C":"Penso em anemia microcítica por deficiência de folato e solicito dosagem sérica do ácido fólico.","D":"Penso em anemia macrocítica por deficiência de vitamina B12 e solicito sua dosagem sérica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-24391","number":"24391","sourceNumber":"24391","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Ademir, 5 anos, apresentou quadro de dor no quadril de evolução insidiosa. A princípio,\no traumato-ortopedista imaginou que poderia se tratar\nda doença de Legg-Calvé-Perthes (necrose\nasséptica idiopática da cabeça femoral), porém ao saber que a criança era portadora de uma\ndoença hematológica hereditária, logo percebeu que se tratava de uma osteonecrose da cabeça do\nfêmur, importante complicação da:","options":{"A":"Anemia falciforme","B":"Beta-Talassemia ?Minor?","C":"Esferocitose","D":"Deficiência da G6PD"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-6893","number":"6893","sourceNumber":"6893","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente idoso, dependente de familiares para ingestão de água e alimentos, é trazido\npara realização de desbridamento na região do\npé, foram solicitados exames pré-operatórios e\nconstatado sódio sérico de 172 mEq/L, a correção rápida deste íon pode resultar em:","options":{"A":"Fibrilação atrial e alteração do intervalo QT.","B":"Vasoconstrição e redução do fluxo sanguíneo cerebral.","C":"Perda de volume cerebral com ruptura de vasos e hemorragia.","D":"Edema cerebral, convulsões e coma.","E":"Mielinólise pontina central."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-8813","number":"8813","sourceNumber":"8813","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente procura atendimento com queixas sugestivas de anemia. Eritrograma mostra\nHb = 6,0 e VCM = 121. Com base nestes\ndados, qual das hipóteses abaixo deve ser excluída do\ndiagnóstico diferencial?","options":{"A":"Anemia megaloblástica.","B":"Anemia da insuficiência hepática.","C":"Anemia do hipotiroidismo.","D":"Talassemia.","E":"Síndrome mielodisplásica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-7258","number":"7258","sourceNumber":"7258","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"São medidas para o tratamento da hipercalemia, EXCETO:","options":{"A":"infusão intravenosa de sais de cálcio.","B":"inibidores de anidrase carbônica.","C":"infusão de glicose e insulina.","D":"hemodiálise imediata.","E":"diuréticos de alça."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-9057","number":"9057","sourceNumber":"9057","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Qual das seguintes associações é CORRETA em relação ao diagnóstico da anemia\nhemolítica?","options":{"A":"Esquistócitos - Hemólise associada a próteses intravasculares","B":"Esferócitos - Anemia falciforme","C":"Células em alvo - Hemólise por crioaglutininas","D":"Acantócitos - Talassemias"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-9106","number":"9106","sourceNumber":"9106","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Fernando, 3 anos, branco, compareceu a seu médico de família levado pela mãe com\nexames complementares já realizados. Fernando\nestava em bom estado geral, eutrófico e a única\nalteração apresentada no exame físico foi palidez palmar leve.\n\nOs exames apresentavam os seguintes resultados: Hb:10,3 g/dL, VCM: 70, CHCM: 28, ferritina\nsérica diminuída, saturação de transferrina\ndiminuída, ferro sérico diminuída. Qual o diagnóstico\nmais provável para Fernando?","options":{"A":"Depleção das reservas de ferro sem anemia.","B":"Deficiência de ferro sem anemia.","C":"Anemia ferropriva.","D":"Anemia grave."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-6941","number":"6941","sourceNumber":"6941","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Lactente masculino, 6 semanas, apresenta desde os 15 dias de vida vômitos não\nbiliosos, em jato, perda de peso e ondas peristálticas visíveis. O distúrbio mais provável de ser\nencontrado é:","options":{"A":"Acidose metabólica hipocalêmica.","B":"Alcalose metabólica hiponatrêmica.","C":"Alcalose metabólica hipoclorêmica.","D":"Acidose metabólica hiperclorêmica.","E":"Alcalose mista hipercalêmica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-9063","number":"9063","sourceNumber":"9063","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Otavinho apresentou icterícia neonatal. Após uma série de exames, chegou-se à\nconclusão de que se tratava de uma desordem\ngenética que culmina com um quadro de anemia do\ntipo normocítica e hipercrômica. Qual a provável patologia de Otavinho?","options":{"A":"Anemia falciforme","B":"Talassemia Beta","C":"Anemia ferropriva","D":"Esferocitose"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-6961","number":"6961","sourceNumber":"6961","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente com história de litíase renal de repetição chega ao Pronto-Socorro com\ndispneia. Exames de urgência mostram: sódio 135\nmEq/L, creatinina 0,9 mg/dL, potássio 1,8\nmEq/L, cloro 115 mEq/L, pH 7.08, PaCO2 40 mmHg, bicarbonato 11 mEq/L. Marque a alternativa\ncorreta:","options":{"A":"O ânion gap do paciente está normal, devendo-se pedir um gap urinário que, se estiver positivo,\nindica perda de bicarbonato na urina.","B":"O ânion gap do paciente está normal, devendo-se pedir um gap urinário que, se estiver positivo,\nindica perda de bicarbonato nas fezes.","C":"O ânion gap do paciente está normal, indicando intoxicação exógena, cetoacidose diabética ou\nacidose láctica.","D":"O ânion gap do paciente está aumentado, sendo necessário pedir o gap urinário para prosseguir\nna investigação etiológica.","E":"Trata-se de acidose metabólica e respiratória mista, sendo que apresenta ânion gap aumentado,\nprovavelmente por retenção de ácidos pela IRA."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-8908","number":"8908","sourceNumber":"8908","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma criança de dois anos de idade apresenta palidez mucosacutânea (++/4+) e é\nsolicitado um hemograma completo, que evidencia uma anemia microcítica. Uma eletroforese de\nhemoglobina, no seguimento, demonstra um aumento na concentração de hemoglobina A2.\n\nMarque a alternativa com o diagnóstico mais provável:","options":{"A":"Anemia por deficiência de ferro","B":"Traço betatalassêmico","C":"Anemia falciforme","D":"Anemia de doença crônica sistêmica","E":"Anemia por intoxicação com chumbo"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-6972","number":"6972","sourceNumber":"6972","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, 45 anos, chega à emergência com dispneia intensa há 3 dias após um\nresfriado. É portador de Esclerose Lateral\nAmiotrófica diagnosticada há 10 meses. Exame físico:\nfrequência respiratória de 32 irpm, PA: 160 x 95 mmHg, Pulso: 110 bpm, regular, em uso da\nmusculatura acessória (++/4), respiração paradoxal presente, SpO2 84%, expansibilidade torácica\nreduzida. Ausculta pulmonar: Murmúrio vesicular diminuído bilateralmente. Ausculta cardíaca:\nNormal. Quais os resultados mais prováveis na gasometria arterial colhida em ar ambiente?","options":{"A":"pH: 7,46; PaO2: 55 mmHg; PaCO2: 30 mmHg; SaO2: 86%","B":"pH: 7,35; PaO2: 55 mmHg; PaCO2: 45 mmHg; SaO2: 86%","C":"pH: 7,25; PaO2: 50 mmHg; PaCO2: 64 mmHg; SaO2: 83%","D":"pH: 7,20; PaO2: 80 mmHg; PaCO2: 25 mmHg; SaO2: 86%","E":"pH: 7,02; PaO2: 75 mmHg; PaCO2: 85 mmHg; SaO2: 83%"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-349745","number":"349745","sourceNumber":"349745","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Assinale a alternativa que apresenta corretamente as principais manifestações\nextra-articulares da artrite psoriática.","options":{"A":"Pneumopatia intersticial padrão não específico; esclerodactilia; microstomia; fenômeno de\nRaynaud.","B":"Entesite; pneumopatia intersticial usual; hipertensão pulmonar; mãos de mecânico.","C":"Sinal do Coldre; heliótropo; dactilite; ganglionopatia.","D":"Doença inflamatória intestinal; pneumopatia intersticial usual; xeroftalmia; fenômeno de\nRaynaud.","E":"Doença inflamatória intestinal; uveite; dactilite; entesite."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-322157","number":"322157","sourceNumber":"322157","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um homem de 56 anos procura atendimento médico por crise de artrite gotosa,\napresentando sinais clássicos de podagra.\nSobre o tratamento para esse caso, é correto afirmar\nque","options":{"A":"a colchicina está contraindicada se o paciente for portador de doença renal crônica e estiver em\nuso contínuo de carvedilol.","B":"o uso de corticosteroides por via oral não é recomendado.","C":"o alopurinol está indicado durante a crise aguda.","D":"o uso de inibidores de interleucina-1 é considerado tratamento de primeira escolha.","E":"a prednísona está indicada na dose de 5mg por via oral em dias alternados."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-322159","number":"322159","sourceNumber":"322159","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à febre reumática, é correto afirmar que","options":{"A":"a coreia de Sydenham é considerada um critério maior para o diagnóstico, sendo muito\nfrequente na apresentação inicial (80-90%).","B":"a dor articular (artralgia) é considerada um critério menor para o diagnóstico.","C":"a presença de febre baixa é essencial para o diagnóstico.","D":"a faixa etária mais acometida é de 40 ? 50 anos.","E":"o uso de corticoides está indicado na profilaxia de febre reumática"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-322162","number":"322162","sourceNumber":"322162","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à artrite reumatoíde, é correto afirmar que;","options":{"A":"os anti-inflamatórios não esteroidais (AINE) são considerados drogas modificadoras de doença.","B":"o diagnóstico deve ser confirmado pela dosagem do fator reumatoide.","C":"a presença de marcadores agudos de inflamação (proteína C reativa ou velocidade de\nhemossedimentação) adiciona 5 pontos aos critérios mais recentes de diagnóstico.","D":"o metotrexato é considerado droga de primeira escolha.","E":"o uso de corticosteroides intra-articulares está indicado na maioria dos casos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-305304","number":"305304","sourceNumber":"305304","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre a artrite reumatoide, é CORRETO afirmar que:","options":{"A":"70 a 80% dos pacientes apresentam Fator Reumatoide (FR) positivo em algum momento da\nvida.","B":"Corticoide oral, como prednisona, é uma das drogas de primeira escolha.","C":"Envolve exclusivamente estruturas articulares e periarticulares.","D":"O acometimento da coluna lombar é comum.","E":"A presença de Velocidade de Hemossedimentação Aumentada (VHS) tem valor preditivo\npositivo alto para o diagnóstico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-298888","number":"298888","sourceNumber":"298888","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma paciente de 1 ano e 6 meses de idade foi encaminhada ao pronto atendimento\npediátrico por apresentar febre, há três\ndias, entre 38ºC e 39,5ºC, sem outras queixas. A criança foi\nlevada pela avó materna, que se mostrou bastante preocupada, pois, além da febre, notou que a\ncriança apresenta manchas arrocheadas nos membros superiores e inferiores. A criança reside\ncom a mãe, um irmão de 5 anos de idade e o padrasto. Ao exame físico, ela mostra-se abatida e\nprostrada, mas está corada e hidratada. Constataram-se FC = 120 bpm, FR = 40 irpm, SatO2 =\n98% em AA, oroscopia sem petéquias, sem placas, sem lesões, otoscopia com membrana\ntimpânica translúcida, sem abaulamento, sem secreção, ausculta cardíaca BNF, RR, 2t, sem sopro\ne ausculta pulmonar MVUD, sem ruídos adventícios. Também foram observados abdome RHA+,\ndepressível, dor à palpação em baixo ventre, Blumberg e Murph negativos, sem sinais de\nmeningismo, membros inferiores com equimoses < 5 cm e membros superiores com equimoses > 5\ncm em braço esquerdo. Inicialmente foram solicitados exame qualitativo de urina com urocultura\n(via sondagem vesical; ainda sem resultado da urocultura) e radiografia de membro superior\nesquerdo. O exame qualitativo de urina pode ser verificado a seguir. Realizou-se, ainda, radiografia\nque evidenciou calo ósseo em rádio e ulna esquerda, conforme a imagem a seguir. Acerca desse\ncaso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Artrite\nidiopática juvenil é uma doença crônica autoimune das articulações, e a principal manifestação\nclínica é a artrite, caracterizada por dor, aumento de volume e de temperatura de uma ou mais\narticulações.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-261214","number":"261214","sourceNumber":"261214","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O aumento do átrio direito é a causa provável da compressão\nesofágica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-261215","number":"261215","sourceNumber":"261215","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Antibioticoterapia adequada com quinolona é a escolha inicial\npara evitar a ocorrência dessas complicações.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-274367","number":"274367","sourceNumber":"274367","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre a artrite gotosa, é correto afirmar que","options":{"A":"é mais comum em mulheres, na faixa de 30-40 anos.","B":"a alimentação rica em leguminosas deve ser estimulada devido ao perfil de melhora da doença\ncom esse tipo de alimento.","C":"alimentos ricos em cadeias longas de carbono com ligação insaturada devem ser estimulados.","D":"a doença na fase inicial normalmente poupa articulações do eixo central.","E":"o tratamento crônico visa diminuir os episódios de crises álgicas, sem interferir na evolução\nnatural da doença."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-255713","number":"255713","sourceNumber":"255713","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 50 anos de idade com eritema marginatum, pancardite, nódulos\nsubcutâneos, febre e artralgia procurou o\nreumatologista para receber um diagnóstico. Além disso,\napresentava anúria e atrito pericárdico. Considerando esse caso clínico e os conhecimentos\nmédicos correlatos, julgue o item a seguir.\n\nPacientes que têm essa patologia podem apresentar isoladamente coreia de Sydenham, que\nmelhora os movimentos durante o sono.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-214492","number":"214492","sourceNumber":"214492","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Determinada paciente de 22 anos de idade chega ao posto de saúde da família com\nhistórico de ocorrências de dores musculares e episódios intermitentes de dores em punhos e em\nmãos bilateralmente e simetricamente no último mês. Relata os episódios de dor como\nindependentes da realização de esforços. Refere ter percebido, no último mês, o surgimento de\nregiões de hiperemia e lesões de pele escamosas em cotovelos, mãos e no couro cabeludo. Ao\nexame, apresenta-se em bom estado geral, corada, hidratada, eupneica em ar ambiente, com PA =\n110 mmHg x 70 mmHg; FC = 74 bpm; FR = 21 irpm e SatO? = 98%. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o item a seguir:\n\na presença de uma poliartrite periférica simétrica fala mais a favor de quadros como artrite\nreumatoide e lúpus eritematoso sistêmico,\ndiminuindo a probabilidade diagnóstica de um quadro de\nartrite psoriática.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-177597","number":"177597","sourceNumber":"177597","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um menino de 5 anos de idade é levado por sua mãe a um serviço de pronto\natendimento pediátrico com queixas de odinofagia,\ntosse discreta e febre de até 39 °C, há 2 dias.\nAo exame físico, observam-se alguns linfonodos cervicais aumentados e dolorosos, ausculta\npulmonar normal, ausência de secreção nasal e orofaringe hiperemiada, com presença de placas\nesbranquiçadas na amígdala esquerda. Com base no hipotético caso citado e considerando os\nprincipais diagnósticos e as possíveis complicações, julgue o item a seguir. Caso a\nantibioticoterapia não seja iniciada e a criança venha a desenvolver a febre reumática, espera-se\num período de latência de 2 a 4 meses entre a infecção de orofaringe e o desenvolvimento da\ndoença cardíaca.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-177603","number":"177603","sourceNumber":"177603","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um menino de 5 anos de idade é levado por sua mãe a um serviço de pronto\natendimento pediátrico com queixas de odinofagia,\ntosse discreta e febre de até 39 °C, há 2 dias.\nAo exame físico, observam-se alguns linfonodos cervicais aumentados e dolorosos, ausculta\npulmonar normal, ausência de secreção nasal e orofaringe hiperemiada, com presença de placas\nesbranquiçadas na amígdala esquerda. Com base no hipotético caso citado e considerando os\nprincipais diagnósticos e as possíveis complicações, julgue o item a seguir. No quadro de febre\nreumática, a coreia de Sydenham costuma preceder as manifestações cardíacas da doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-177610","number":"177610","sourceNumber":"177610","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um menino de 5 anos de idade é levado por sua mãe a um serviço de pronto\natendimento pediátrico com queixas de odinofagia,\ntosse discreta e febre de até 39 °C, há 2 dias.\nAo exame físico, observam-se alguns linfonodos cervicais aumentados e dolorosos, ausculta\npulmonar normal, ausência de secreção nasal e orofaringe hiperemiada, com presença de placas\nesbranquiçadas na amígdala esquerda. Com base no hipotético caso citado e considerando os\nprincipais diagnósticos e as possíveis complicações, julgue o item a seguir. A artrite da febre\nreumática costuma ser poliarticular e assimétrica, além de acometer grandes articulações.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-152114","number":"152114","sourceNumber":"152114","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, rash salmão em face, principalmente\nquando ocorre febre, relata que, após passar a\nfebre, desaparece. Também refere perda de peso e\ndificuldade em realizar agachamentos. Apresenta dor de garganta e linfonodomegalia. Ao exame\nfísico, apresenta-se com hepatoesplenomegalia, sinais de sacroileíte. Com base nesse caso clínico,\njulgue o item a seguir. Alelo X Gene HLA B27 pode estar envolvido neste caso .","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-131823","number":"131823","sourceNumber":"131823","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Acerca do tratamento da gota, assinale a alternativa CORRETA:","options":{"A":"O tratamento de pacientes que apresentam hiperuricemia assintomática é sempre indicado, uma\nvez que mais de 95% deles desenvolverá\ngota.","B":"A colchicina é indicada exclusivamente para pacientes com gota que apresentam insuficiência\nrenal.","C":"O uso do alopurinol aumenta a síntese do ácido úrico e sua excreção.","D":"O uso de Anti-Inflamatórios Não Esteroides (AINEs) é contraindicado no tratamento da gota e\nindicado no tratamento da pseudogota.","E":"Antes da utilização de glicocorticoides intra-articulares para analgesia da gota, deve-se\nexcluir a\nartrite séptica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-140664","number":"140664","sourceNumber":"140664","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma paciente de trinta anos de idade foi atendida em ambulatório com queixas de\ndispneia aos esforços e fadiga. Ao exame\nfísico, o médico constatou palidez cutâneo-mucosa ++/+4\ne ''língua careca\" (papilas ausentes). Após a realização de hemograma, contagem de reticulócitos\nno sangue periférico e outros exames complementares específicos, a paciente foi diagnosticada\ncom anemia megaloblástica por deficiência de cobalamina. Com referência a esse caso clínico,\njulgue o item subsequente. Leucócitos totais de 2.800 células/µL, plaquetas a 120.000/µL,\ncontagem diferencial de leucócitos normal e presença de neutrófilos hipersegmentados\n(pleocariócitos), na avaliação da série branca e das plaquetas dessa paciente, são resultados\ncompatíveis com o diagnóstico proposto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-134979","number":"134979","sourceNumber":"134979","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Acerca de febre reumática, julgue o item que se segue. A coreia de Sydenham,\nmanifestação de febre reumática, é caracterizada tanto por habituais evidências de atividade\ninflamatória e estreptococcia, como também por deixar, frequentemente, sequelas tardias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-140727","number":"140727","sourceNumber":"140727","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"No item seguinte é apresentada uma situação hipotética seguida de uma assertiva a\nser julgada. Uma criança de um ano de idade,\nportadora de anemia falciforme, foi atendida em\nemergência pediátrica chorando muito e apresentando-se irritada. Ao exame físico, observaram-se\npalidez intensa, dor à palpação do abdome e volumosa esplenomegalia. O resultado do\nhemograma completo mostrou hematócrito de 15%, hemoglobina de 4,5 g/dL, 15.000\nleucócitos/mm³, 125.000 plaquetas/mm³. Nesse caso, a criança pode estar com crise de sequestro\nesplênico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-108154","number":"108154","sourceNumber":"108154","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Com relação ao tubo digestivo, às suas glândulas anexas e às patologias que\nacometem esses sistemas, julgue o item subsequente. O evento inicial para a produção de\nbilirrubina é representado pela destruição das hemácias no sistema reticuloendotelial.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-79678","number":"79678","sourceNumber":"79678","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A. J. S., 65 anos, cirrótico, histórico de diabetes tipo 2 apresentou exames de\ndiagnóstico salientando-se pancitopenia com\nmicrocitose e hipocromia, prolongamento do tempo de\nprotrombina e tromboplastina ativada, gama-GT e AST acima do limite superior da normalidade,\nácido fólico e vitamina B12 normais. É correto afirmar que se deve excluir cirrose por abuso de\nálcool","options":{"A":"pois o paciente é diabético.","B":"pois o paciente está pancitopênico.","C":"devido à presença de vitamina B12 em níveis normais.","D":"devido à AST elevada.","E":"devido ao tempo de protrombina ativada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-88628","number":"88628","sourceNumber":"88628","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Atualmente existem inúmeros pacientes em filas de espera para tratamentos definitivos.\nConsiderando que o tempo pode agravar as condições clínicas desses pacientes, julgue o item a\nseguir. Uma das causas do aumento da taxa de mortalidade no país encontra-se na longa espera\ndo paciente pela esplenectomia nos casos de anemia falciforme.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-79667","number":"79667","sourceNumber":"79667","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança com quadro febril fez uso de paracetamol, evoluiu com quadro súbito de\npalidez, icterícia, hemograma com anemia e\nreticulócitos aumentados. Assinale a alternativa que\napresenta o diagnóstico provável.","options":{"A":"Deficiência de G6PD.","B":"Talassemia.","C":"Anemia falciforme.","D":"Síndrome hemolítico-urêmica.","E":"Hepatite fulminante por paracetamol."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-88621","number":"88621","sourceNumber":"88621","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Acerca da crise álgica da anemia falciforme, julgue o item a seguir. Para resolução total\ndo quadro álgico em situação de dor intensa, recomenda-se a associação de paracetamol com\ndiclofenaco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-88631","number":"88631","sourceNumber":"88631","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Acerca da crise álgica da anemia falciforme, julgue o item a seguir. A crise álgica pode\nocorrer sem causa aparente ou ser desencadeada por desidratação, infecção, frio ou estresse\nfísico e emocional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-82078","number":"82078","sourceNumber":"82078","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma mulher de quarenta e cinco anos de idade foi atendida em ambulatório de clínica\nmédica com relato de que há oito anos apresentava dor na região plantar dos calcanhares e que,\napós ter sido submetida à avaliação médica, recebeu o diagnóstico de reumatismo e que lhe\nhaviam sido prescritos medicamentos cujos nomes não se recorda. Nesse intervalo de tempo,\npassou a apresentar dor e alterações nos punhos, que a impossibilitam de fechar as mãos, e\ntambém dor e vermelhidão nos joelhos e tornozelos. Ela relatou, ainda, rigidez matinal, com\nduração de três horas, por vários meses. Negou possuir outras doenças e informou que sua mãe\napresentava problema de reumatismo. Ao exame físico, observaram-se diminuição da flexão dos\npunhos (bilateralmente), dor nas articulações metacarpofalangianas (bilateralmente), presença de\ndiscreto derrame articular nos joelhos e dor à palpação das articulações metacarpofalangianas e\ndos calcanhares. Foram constatados três nódulos, com cerca de 2 cm de diâmetro cada um,\nindolores, firmes e móveis na região olecraniana direita. O restante do exame não apresentou\nalterações. Exames complementares realizados mostraram fator reumatoide (teste do látex)\npositivo, pesquisa de anticorpos contra peptídeos citrulinados cíclicos (CCP) positiva, níveis\nelevados de proteína C-reativa e aceleração da velocidade de hemossedimentação. Radiografias\ndas mãos e dos pés mostraram estreitamento dos espaços articulares e lesões ósseas erosivas.\nCom base nessas informações clinicolaboratoriais, julgue o item a seguir: o uso de metotrexato, útil\ncomo parte do tratamento farmacológico da paciente em tela, proporciona redução na progressão\ndas lesões radiográficas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-82069","number":"82069","sourceNumber":"82069","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Acerca do uso terapêutico e profilático de antibiótico em pediatria, julgue o item\nsubsequente. A um lactente de quatro meses com anemia falciforme não deve ser prescrito\nantibioticoprofilaxia com penicilina a fim de se prevenir infecções por pneumococo, uma vez que\napenas a vacina contra o Diplococcus pneumoniae é suficiente para previnir essa infecção.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-64677","number":"64677","sourceNumber":"64677","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Nos exames de rotina de trabalho, Jéssica, 72 anos, evidenciou uma anemia\nmicrocítica e hipocrômica, com os seguintes\nvalores laboratoriais para o perfil do ferro: ferritina 348\nmg/ml (aumentada), ferro sérico 40 ng/dl (diminuído), CTLT e IST normais e ausência de\ndismorfismo eritrocitário. A partir dos dados acima, pode-se afirmar que se trata da anemia:","options":{"A":"megaloblástica.","B":"ferropriva.","C":"de doença crônica.","D":"sideroblástica.","E":"falciforme."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-64624","number":"64624","sourceNumber":"64624","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação aos resultados apresentados pela\neletroforese quando realizado o teste do pezinho.","options":{"A":"Resultado FA para interpretação de normalidade.","B":"FAS traço falciforme.","C":"FAD para interpretação de traço D.","D":"FAC para interpretação de doença falciforme.","E":"FS para doença falciforme."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52631","number":"52631","sourceNumber":"52631","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A deficiência de ferro é uma das causas mais frequentes de anemia. Acerca da anemia\nferropriva, julgue o item abaixo. Pacientes com anemia por deficiência de ferro apresentam baixos\nníveis séricos de ferro, aumento na porcentagem de saturação de transferrina, concentração sérica\nde ferritina aumentada e diminuição da capacidade total de ligação do ferro.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52619","number":"52619","sourceNumber":"52619","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Acerca da anemia ferropriva, doença nutricional comum na infância, julgue o item\nsubsequente. As manifestações laboratoriais do paciente com anemia ferropriva incluem\nhipocromia, microcitose, reticulocitose e plaquetopenia.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52621","number":"52621","sourceNumber":"52621","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Acerca da anemia ferropriva, doença nutricional comum na infância, julgue o item\nsubsequente. O portador de anemia\nferropriva pode apresentar sopro cardíaco leve mesodiastólico,\ndevido ao estado hiperdinâmico da circulação sanguínea.","options":{"A":"Certo","B":"Errado"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52622","number":"52622","sourceNumber":"52622","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Acerca da anemia ferropriva, doença nutricional comum na infância, julgue o item\nsubsequente. Os principais fatores que devem ser observados ao surgimento da anemia ferropriva\nem crianças com menos de dois anos de idade são: nível de reserva de ferro ao nascimento; taxa\nde crescimento; tipo de dieta; perda de ferro.","options":{"A":"Certo.","B":"Errado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-29750","number":"29750","sourceNumber":"29750","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Julgue o item a seguir, relativo a doenças hematológicas. Presença de eritrócitos\nmicrocíticos e hipocrômicos, ferro sérico\nbaixo, capacidade total de ligação do ferro (TIBC) elevada,\nporcentagem de saturação da transferrina abaixo do normal e ferritina sérica baixa são elementos\nque indicam a anemia sideroblástica como diagnóstico principal.","options":{"A":"Certo","B":"Errada"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-8598","number":"8598","sourceNumber":"8598","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 15 anos de idade, portador de doença falciforme, procura atendimento\nmédico, francamente taquipneico, tossindo, febril,\ncom dores de predomínio torácico. A radiografia\nde tórax é mostrada a seguir: (VER IMAGEM). Quanto ao quadro clínico é correto afirmar:","options":{"A":"Mycoplasma pneumoniae, Clamydia pneumoniae e Streptococus pneumoniae devem ser\nconsiderados.","B":"Ao contrário das crises álgicas, a analgesia não tem indicação neste caso.","C":"A hidratação deve ser apenas via oral, pelo risco de congestão.","D":"Só deve receber hemotransfusão se Hb < 10 g/dl.","E":"Essa é uma apresentação clínica infrequente nos portadores de doença falciforme."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-8597","number":"8597","sourceNumber":"8597","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança, 18 meses de vida, há cerca de 8 horas apresenta irritabilidade, palidez, dor e\ndistensão abdominal. Nasceu de parto normal, sem intercorrências no período neonatal. Mudou de\ncidade há 2 meses e passou por sua primeira consulta de puericultura há 2 semanas, quando\nrecebeu prescrição de sulfato ferroso ?por estar descorada?. Ao exame clínico apresenta-se\nchorosa, moderadamente descorada, discretamente ictérica; frequência cardíaca = 130\nbatimentos/minuto, frequência respiratória = 36 movimentos/minuto. Veja a foto a seguir (VER\nIMAGEM). Considerando a principal hipótese diagnóstica, assinale o exame complementar\nnecessário para certeza do diagnóstico.","options":{"A":"Mielograma.","B":"Biópsia de crista ilíaca.","C":"Pesquisa de cariótipo.","D":"Biópsia de gânglio ou baço.","E":"Eletroforese de hemoglobina."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-334884","number":"334884","sourceNumber":"334884","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática (FR) é uma doença inflamatória, sistêmica, mais prevalente em\ncrianças na faixa etária de 5 a 15 anos de idade, deflagrada pelo Streptococcus ?-hemolítico do\ngrupo A de Lancefield e que acomete articulações, coração e pele. Considerando a patologia\ndescrita e os conhecimentos médicos atuais, assinale a alternativa correta","options":{"A":"O diagnóstico do primeiro surto de FR é realizado por dois critérios maiores, como poliartralgia\ne\nfebre.","B":"A artrite dá-se com o envolvimento de grandes e pequenas articulações, com caráter aditivo e\nprogressivo.","C":"Na FR recorrente, podem-se considerar três critérios menores, independentemente do grupo de\nrisco do paciente.","D":"O eritema marginado consiste em uma lesão macular com halo claro, que ocorre\nfrequentemente na face e que é muito pruriginosa.","E":"O ecodopplercardiograma deve ser solicitado apenas quando, na ausculta cardíaca, for\nencontrado sopro mitral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-307097","number":"307097","sourceNumber":"307097","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma paciente de 46 anos de idade, de um dia para outro, começou a queixar-se de\ndores articulares em dedos das mãos e punhos.\nFoi ao ortopedista que passou anti-inflamatório\nnão hormonal, e ela melhorou por uma semana, mas, logo após, as dores pioraram. Começou a\nsentir dor, edema, calor e rubor, com impedimento para as atividades diárias, sendo a rigidez pior\nna primeira hora da manhã. Foi a um médico reumatologista que a vizinha indicou, e teve o\ndiagnóstico de artrite reumatoide (AR). Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, assinale a alternativa correta.","options":{"A":"O tratamento da paciente com AR não precisa ter, necessariamente, uma abordagem\nmultidisciplinar coordenada por um reumatologista,\ncom conhecimento em qualquer especialidade.","B":"O tratamento da paciente com AR deve incluir orientações quanto a hábitos de vida, controle\nrigoroso das comorbidades e atualização do cartão de vacinas.","C":"O tratamento da paciente com AR deve ser embasado em decisões tomadas pelo médico e\npassadas ao paciente, sem muitos esclarecimentos acerca de sua enfermidade, iniciando a\nterapêutica de forma a não perder tempo para a doença.","D":"Não há meta do tratamento da paciente com AR por ser um estado persistente e crônico, sem\nperspectivas de remissão clínica.","E":"No tratamento da AR, não se utilizam mais drogas como hidroxicloroquina e metotrexato por\nineficiência medicamentosa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-301256","number":"301256","sourceNumber":"301256","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O acometimento pleuropulmonar em pacientes com doenças autoimunes sistêmicas é\ncomum e pode levar ao aumento da morbidade e mortalidade. O diagnóstico precoce dessas\nmanifestações oferece a melhor chance de intervir e melhorar o prognóstico. A respeito desse\nassunto, julgue o item a seguir. A manifestação pleuropulmonar mais comum em pacientes com\nartrite reumatoide é o derrame pleural, que tem concentração elevada de complemento.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-307104","number":"307104","sourceNumber":"307104","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um paciente de 53 anos de idade, portador de diabetes, foi admitido em uma unidade\ncoronariana por angina instável. Previamente ao cateterismo, fez uso de tirofiban por 72 horas,\nseguindo a realização do exame que apresentou elevada carga trombótica e lesão em artéria\ndescendente anterior. Começou a sentir dor e apresentar edema articular de moderada intensidade\nem tornozelo e calcanhar esquerdo. Foi realizada dosagem de ácido úrico e determinado o\ndiagnóstico de hiperuricemia. O paciente refere ter gota e fazer medicação previamente à\ninternação. Em relação a esse caso clínico e à gota, assinale a alternativa correta. Alternativas:","options":{"A":"O paciente tem que suspender a angioplastia em razão da crise de gota em curso.","B":"É preciso melhorar a hidratação e corrigir a alimentação até 30 dias após o tratamento das\ncoronárias.","C":"Pode-se usar anti-inflamatório não hormonal por cinco dias a sete dias e iniciar colchicina.","D":"Por se tratar do acometimento de somente uma articulação, pode-se deixar para segundo plano\no tratamento, pois haverá resolução espontânea.","E":"A associação de um inibidor da xantina oxidase com a benzbromarona na gota não deve ser\nusada quando se sabe que o alvo sérico de ácido úrico não é alcançado."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-263351","number":"263351","sourceNumber":"263351","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um adolescente com 11 anos de idade é atendido no pronto-socorro com história de\ndor e inchaço em joelho esquerdo há 5\ndias. Ele conta que, há 2 dias, iniciou com febre, dificuldade\npara deambular e aumento da dor e do inchaço na região. A mãe relata recusa alimentar e palidez\ncutânea há 1 dia. O adolescente apresenta antecedente de trauma local durante partida de futebol\nhá 1 semana e refere o uso de anti-inflamatório não esteroidal desde então, sem melhora do\nquadro. Ao exame físico, apresenta-se em regular estado geral, com palidez cutânea, febril\n(temperatura axilar = 38,2°C), eupneico, anictérico, acianótico, com tempo de enchimento capilar de\n3 segundos e pressão arterial normal para a idade. Apresenta, ainda, edema, rubor, calor e dor no\njoelho esquerdo, com bloqueio à tentativa de mobilização. O resultado do hemograma mostra\nleucocitose com desvio à esquerda. Também foram observados proteína C reativa e VHS elevados.\nNesse caso, qual é o agente etiológico mais provável e a antibioticoterapia endovenosa indicada?","options":{"A":"Streptococcus pneumoniae; ampicilina.","B":"Staphylococcus aureus; oxacilina.","C":"H. influenzae tipo B; amoxicilina.","D":"Kingella kingae; ceftriaxona."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-268895","number":"268895","sourceNumber":"268895","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma paciente de 27 anos de idade compareceu ao atendimento ambulatorial com\nrelato de que, há dois meses, iniciou\naumento de volume e dor nos punhos e em algumas\ninterfalangeanas proximais; a dor foi aumentando com o passar dos dias e surgiu rigidez articular\nmatinal com duração de três horas. Negou febre e outros sintomas. Ao exame físico, apresentava\nartrite nos punhos e na segunda, terceira e quarta interfalangeanas proximais bilateral. Não foram\nidentificadas outras alterações ao exame físico. Verificaram-se FC = 80 bpm, FR = 18 irpm e SatO2\n\n= 97%. Quanto aos exames laboratoriais, contataram-se hemograma e EAS normais, FAN = 1/160\npadrão nuclear pontilhados fino denso, VHS = 45 mm/hora e PCR = 9,2 mg/dL, sendo o valor de\nreferência < 1 mg/dL. Nesse caso, os exames para confirmação da principal hipótese diagnóstica\nsão","options":{"A":"fator reumatoide, anticorpos anti-DNA nativo, anti-Sm e proteinúria de 24 horas.","B":"fator reumatoide e anticorpos anti-CCP.","C":"fator reumatoide, anticorpos anti-Ro/SSA, anti-La/SSB e radiografia das articulações\nacometidas.","D":"anticorpos anti-DNA nativo, anti-Sm, anti-Ro/SSA, anti-La/SSB e radiografia das articulações\nacometidas.","E":"anticorpos anti-DNA nativo, anti-Sm, dosagem dos fatores de complemento C3 e C4 e\nproteinúria de 24 horas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-274610","number":"274610","sourceNumber":"274610","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Artrite Idiopática Juvenil (AIJ) é o conjunto de doenças inflamatórias crônicas que\nacomete as articulações de crianças e adolescentes antes dos 16 anos. Quanto à AIJ, é\nINCORRETO afirmar:","options":{"A":"A AIJ é uma condição comum que afeta os nervos periféricos, responsáveis por encaminhar\ninformações do cérebro e da medula espinhal para o restante do corpo. A AIJ pode causar danos\npermanentes aos nervos, sendo muitas vezes um problema incapacitante e, até mesmo, fatal.","B":"Crianças tipicamente apresentam rigidez articular, edema, derrame, dores e sensibilidade, mas\nalgumas crianças não têm dor. As manifestações nas articulações podem ser simétricas ou\nassimétricas e envolver grandes ou pequenas articulações. Entesite normalmente provoca\nsensibilidade da crista ilíaca e coluna vertebral, grande trocânter do fêmur, patela, tuberosidade\nda\ntíbia ou inserções da fáscia plantar e do tendão calcâneo.","C":"Quando a artrite acomete até quatro articulações. É mais comum em meninas entre os 4 e 5\nanos. Atinge articulações grandes, como\njoelhos, tornozelos ou cotovelos. Também é comum afetar\numa articulação específica em um lado do corpo apenas e pode ser acompanhada de uveíte. Por\nisso, é importante a realização periódica de exames oftalmológicos.","D":"A AIJ é uma condição do sistema imunológico inato. Os mensageiros, chamados de\ninterleucinas, que promovem a resposta\ninflamatória, têm um papel-chave no desenvolvimento da\nAIJ. As outras formas de AIJ são as doenças autoimunes, o que significa que elas envolvem\nanticorpos do sistema imunológico adquirido."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-274612","number":"274612","sourceNumber":"274612","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Artrite Idiopática Juvenil (AIJ), anteriormente conhecida como artrite reumatoide\njuvenil, é um conjunto de doenças\ninflamatórias crônicas que acomete as articulações de crianças e\nadolescentes antes dos 16 anos. A AIJ é uma doença:","options":{"A":"Bacteriana.","B":"Viral.","C":"Autoimune.","D":"Fúngica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-291553","number":"291553","sourceNumber":"291553","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma menina de 3 anos de idade iniciou subitamente um quadro febril alto,\napresentando irritabilidade e queixa de dor\nimportante em perna direita, parando de andar. Ao\nexame, estava toxêmica. Foi identificada dor localizada na face anterior do quadril direito,\npermanecendo na posição de flexão-abdução e rotação externa. Havia relato de trauma na escola\npoucos dias antes, tendo caído do balanço, mas não houve repercussão no dia do acidente. Diante\ndo quadro clínico apresentado, assinale a alternativa que define o diagnóstico provável.","options":{"A":"Febre reumática.","B":"Sinovite transitória do quadril.","C":"Doença de Legg-Perthes.","D":"Artrite séptica do quadril."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-230541","number":"230541","sourceNumber":"230541","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Apesar de a etiopatogenia de AR (Artrite Reumatoide) ainda não ser inteiramente\nconhecida, muito se avançou no tema nos últimos anos. Podemos APENAS aceitar que:","options":{"A":"A Artrite Reumatoide (AR) é uma doença autoimune, inflamatória, sistêmica e crônica,\ncaracterizada por sinovite periférica e sem manifestações extra-articulares.","B":"No início, a observação do aumento da incidência de AR (Artrite Reumatoide) entre familiares,\nprincipalmente entre gêmeos monozigóticos, sugeria um componente ambiental em sua\netiopatogênese.","C":"Com o avanço dos estudos, foi identificado o antígeno leucocitário humano (human leukocyte\nantigen - HLA), considerado o principal fator genético no desenvolvimento dessa doença.","D":"Diversos alelos de HLA-DRB vêm sendo associados a AR (Artrite Reumatoide) em populações\nafricanas apenas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-230547","number":"230547","sourceNumber":"230547","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Os principais fatores de risco para o desenvolvimento de Artrite Reumatoide (AR) foram\nà presença dos alelos HLA-DRB1 SE (shared\nepitope - epitopo compartilhado) e a detecção de\nanticorpos contra Peptídios Citrulinados Cíclicos (anti-CCP). Podemos assim ACEITAR que:","options":{"A":"Variações fenotípicas e de incidência não apontam para fatores ambientais além da\npredisposição genética.","B":"Variações fenotípicas e de incidência apontam para fatores ambientais que, além da\npredisposição genética, contribuem para o surgimento\nda doença, exceto tabagismo e infecções\nperiodontais.","C":"Variações fenotípicas e de incidência apontam para fatores ambientais que, além da\npredisposição genética, não contribuem para o surgimento da doença.","D":"Variações fenotípicas e de incidência apontam para fatores ambientais que, além da\npredisposição genética, contribuem para o\nsurgimento da doença, tais como tabagismo e infecções\nperiodontais."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-230549","number":"230549","sourceNumber":"230549","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Artrite Reumatoide sem tratamento adequado apresenta um curso de doença\nprogressivo, determinando deformidades decorrentes da\nlassidão ou ruptura dos tendões e das\nerosões articulares. Entre os achados tardios, podem-se identificar desvio e lesões diversas, qual\ndos itens está ERRADO?","options":{"A":"Desvio ulnar dos dedos ou ?dedos em ventania?.","B":"Deformidades em ?pescoço de cisne? ou hipoextensão das articulações IFP.","C":"Flexão das Interfalangianas Distais ? IFD.","D":"Deformidades em ?botoeira?, flexão das IFP e hiperextensão das IFD."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-230550","number":"230550","sourceNumber":"230550","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Quando na Artrite Reumatoide ocorre o acometimento da coluna cervical (C1-C2) com\nsubluxação atlantoaxial geralmente manifesta-se por dor irradiada para a região occipital, assim\npodemos CONCORDAR que:","options":{"A":"Quando sintomas neurológicos, como parestesias periféricas ou perda do controle esfincteriano,\nsurgem, a mortalidade é de 90% em 1 ano.","B":"Quando sintomas neurológicos, como perda do controle esfincteriano, não altera mortalidade.","C":"Quando sintomas neurológicos, como parestesias periféricas ou perda do controle esfincteriano,\nsurgem, a mortalidade em uma semana para\ntodos.","D":"Quando sintomas neurológicos, como parestesias periféricas ou perda do controle esfincteriano,\nsurgem, a mortalidade é de 50% em 1 ano."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-230551","number":"230551","sourceNumber":"230551","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Artrite Reumatoide (AR) tem em sua forma clínica mais comum a poliartrite simétrica de\npequenas e grandes articulações com\ncaráter crônico e destrutivo, podendo levar a relevante\nlimitação funcional, indique o item ERRADO:","options":{"A":"A AR é bastante variável quanto à apresentação clínica, à gravidade e ao prognóstico.","B":"Compromete a capacidade laboral e a qualidade de vida.","C":"Temos AR de longa evolução, que é chamada de Síndrome de Felty, quando ocorre associação\nde AR a neutropenia e hepatomegalia.","D":"Ocorre significativo impacto pessoal e social, com elevados custos indiretos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-230554","number":"230554","sourceNumber":"230554","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O acompanhamento por reumatologista para a Artrite Reumatoide é uma política\nassistencial custo-efetiva, devendo ser o preferencial. Somente NÃO podemos aceitar que:","options":{"A":"O abatacepte subcutâneo e o tofacitinibe são indicados para o tratamento da Artrite Reumatoide\nJuvenil (ARJ), pois seu uso foi aprovado\napenas para pacientes juvenis.","B":"Intervenções educacionais podem ser úteis na implementação de protocolos clínicos para essa\ndoença.","C":"A ciclosporina é preferencialmente recomendada na síndrome de ativação macrofágica, ou\nlinfo-histiocitose hemofagocítica.","D":"Na persistência de artrite, após 3 a 6 meses de tratamento, deve-se iniciar Medicamento\nModificador do Curso da Doença (MMCD) biológico, entre eles o adalimumabe, etanercepte,\ninfliximabe, abatacepte e tocilizumabe, sendo este último apenas para a forma sistêmica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-230555","number":"230555","sourceNumber":"230555","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"As recomendações de tratamento medicamentoso dos pacientes com Artrite\nReumatoide (AR), o acompanhamento sistemático\ncom progressão de medicamentos em caso de\nfalha terapêutica é considerado estratégia custo-efetiva, sendo ADEQUADA a alternativa:","options":{"A":"Pois impede de os pacientes se manterem laboralmente ativos, melhorando a capacidade\nfuncional e a qualidade de vida a um custo aceitável para doenças crônicas.","B":"Pois mantém os pacientes laboralmente ativos, mesmo que piorando a capacidade funcional e a\nqualidade de vida a um custo aceitável para doenças crônicas.","C":"Pois mantém os pacientes laboralmente ativos, melhorando a capacidade funcional e a\nqualidade de vida a um custo aceitável para doenças crônicas.","D":"Pois mantém os pacientes laboralmente ativos, melhorando a capacidade funcional e a\nqualidade de vida a um custo inaceitável para doenças crônicas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-212031","number":"212031","sourceNumber":"212031","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma mulher de 54 anos de idade, com diagnóstico de Artrite Reumatoide (AR),\napresenta um cisto sinovial poplíteo (cisto\nde Baker) no joelho direito. Considerando essa\nmanifestação articular da AR, julgue o item a seguir. Esse cisto pode dissecar e expandir-se para\nos tecidos da panturrilha ou sofrer ruptura com extravasamento para essa mesma região da perna.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-212088","number":"212088","sourceNumber":"212088","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma mulher de 54 anos de idade, com diagnóstico de Artrite Reumatoide (AR),\napresenta um cisto sinovial poplíteo (cisto de\nBaker) no joelho direito. Considerando essa\nmanifestação articular da AR, julgue o item a seguir. A eventual ruptura desse cisto com\nextravasamento do conteúdo inflamatório pode causar manifestação(ões) clínica(s) confundida(s)\ncom gota tofácea, fenômeno chamado de pseudogota.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-177227","number":"177227","sourceNumber":"177227","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 7 anos de idade, do sexo masculino, é levado a uma consulta por\napresentar quadro de edema, dor e aumento da\ntemperatura no joelho e no cotovelo esquerdos há\npelo menos 2 meses. Os responsáveis da criança negam qualquer episódio de febre. Na\ninvestigação com exames complementares, o paciente apresenta fator reumatoide e fator\nantinuclear negativos, além de anticorpos Aslo com valor normal. Considerando-se o caso clínico\napresentando e os conhecimentos médicos referentes a ele, é correto afirmar que o provável\ndiagnóstico é","options":{"A":"febre reumática.","B":"artrite séptica.","C":"dores do crescimento.","D":"lúpus eritematoso sistêmico.","E":"artrite idíopática juvenil."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-183945","number":"183945","sourceNumber":"183945","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"No que se refere a doenças cardiovasculares, isquêmicas e cerebrovasculares, julgue o\nitem a seguir. Insuficiência mitral é a lesão valvular mais comum resultante de febre reumática\naguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-159533","number":"159533","sourceNumber":"159533","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma professora do ensino fundamental, de vinte e oito anos de idade, procurou\natendimento médico por apresentar dispneia aos\nmédios esforços. O exame físico cardiovascular\nrevelou ictus cordis visível e palpável no 5º espaço intercostal na linha medioclavicular esquerda;\npresença de hiperfonese; e desdobramento fisiológico da segunda bulha em foco pulmonar. Na\nausculta do foco mitral, observaram-se hiperfonese da primeira bulha, estalido de abertura da mitral\ne sopro protomesodiastólico ? grau III de Levine ? associado a reforço pré-sistólico. No exame\nclínico, não foram observadas outras alterações significativas. Após avaliação clínica e\nlaboratorial,\no médico estabeleceu o diagnóstico de cardiopatia reumática crônica, tipo estenose mitral, de\nmoderada intensidade. Com referência a esse caso clínico, julgue o seguinte item: como a lesão\nvalvar definitiva está plenamente instalada, a profilaxia secundária para febre reumática não é\nrecomendada para a paciente em questão.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-111354","number":"111354","sourceNumber":"111354","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O achado clínico mais comumente observado nos pacientes portadores de carcinoma\nde cólon direito é:","options":{"A":"A alteração do hábito intestinal.","B":"O tenesmo.","C":"A hematoquezia.","D":"A obstrução.","E":"A anemia."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-111358","number":"111358","sourceNumber":"111358","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma criança do sexo feminino, de 11 meses de idade, é levada ao pediatra por falta de\napetite e palidez. História de prematuridade e aleitamento materno exclusivo até os 2 meses de\nidade, sendo então introduzido leite de vaca. Sem icterícia neonatal. Hemograma: hemoglobina =\n7,1 g/dl; hematócrito = 21%; VCM = 55 fl; reticulócitos = 0.5%; leucócitos = 6000/mm³; plaquetas\n700.000/mm³. Assinale a hipótese diagnóstica mais provável e os exames necessários para a\nconfirmação:","options":{"A":"Esferocitose - fragilidade osmótica.","B":"Anemia ferropriva - eletroforese de hemoglobina.","C":"Talassemia - dosagem de hemoglobina fetal.","D":"Deficiência de G6PD - dosagem de G6PD.","E":"Anemia ferropriva - dosagem de ferro sérico e ferritina."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-97829","number":"97829","sourceNumber":"97829","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma adolescente, com 15 anos de idade, vem à consulta com queixa de dor precordial,\nfebre intermitente com um ou dois picos diários\nnoturnos de 39°C, acompanhados de dores\nmusculares generalizadas e manchas avermelhadas na pele do tronco e raiz de coxa. Relata\ntambém dificuldade de se movimentar pela manhã e dores nas articulações dos joelhos, punhos,\nmãos, pés e nuca. Ao exame físico, observa-se: temperatura = 38,5°C, lesões maculopapulares de\ncor rosa-salmão em tronco e áreas proximais de membros, nódulos subcutâneos em região de\ncotovelo, linfadenomegalia simétrica (cervicais, axilares e inguinais), esplenomegalia e artrite nas\nregiões referidas. Exames laboratoriais trazidos pelo paciente mostraram os seguintes resultados:\nhemograma com anemia, leucocitose e trombocitose; elevação de proteína C-reativa da velocidade\nde hemossedimentação e dos níveis de enzimas hepáticas (ALT e AST). A hipótese diagnóstica\nCORRETA é:","options":{"A":"Doença de Kawasaki.","B":"Artrite idiopática juvenil.","C":"Artrite reativa pós-estreptocócica.","D":"Lúpus eritematoso sistêmico juvenil."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-75470","number":"75470","sourceNumber":"75470","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem com 49 anos de idade apresenta, há um ano e meio, quadro recorrente de\nmonoartrite aguda, durando cada episódio cerca de três a cinco dias. Inicialmente foi acometido o\njoelho esquerdo, posteriormente o direito, em seguida o tornozelo direito e, há três semanas, houve\nrecorrência do quadro no joelho esquerdo. Refere alívio dos sintomas com o uso de diclofenaco,\nque toma por conta própria. Notou que o intervalo entre os episódios, que inicialmente era de até\nseis meses, é agora mais reduzido, sendo o intervalo entre os dois últimos episódios, de apenas\num mês. Apresenta-se na consulta após dois dias do início da última crise. O joelho esquerdo tem\nsinais flogísticos (calor, rubor, aumento de volume), limitação para flexão, o que causa dificuldade\nna deambulação. Relatou um episódio febril ontem (37,6°C). O paciente é hipertenso e diabético há\ndez anos, em uso de hidroclorotiazida 25 mg/dia e glibenclamida 10 mg/dia. Refere tabagismo (5\ncigarros/dia) e etilismo (cerveja, especialmente nos finais de semana). O diagnóstico do paciente e\na conduta inicial a ser adotada são, respectivamente:","options":{"A":"gota não tofácea; realizar artrocentese e iniciar o uso de alopurinol imediatamente.","B":"artrite séptica; realizar artrocentese e aguardar a\nanálise laboratorial do líquido sinovial.","C":"gota não tofácea; não realizar artrocentese e manter o uso de anti-inflamatório não hormonal.","D":"osteoartrite; solicitar radiografia dos joelhos e iniciar o uso de anti-inflamatório não\nhormonal.","E":"artrite séptica; não há necessidade de exames complementares e deve-se iniciar\nantibioticoterapia imediatamente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-64426","number":"64426","sourceNumber":"64426","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na gastrite atrófica, ocorre deficiência na secreção de fator intrínseco, comprometendo\na absorção de:","options":{"A":"Vitamina K","B":"Proteínas","C":"Gorduras","D":"Vitamina B12","E":"Cálcio"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-75550","number":"75550","sourceNumber":"75550","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menino com 12 anos de idade é trazido pelo pai ao ambulatório de pediatria. Na\nhistória, apresenta febre e dor intensa nas\narticulações do joelho há uma semana, a qual passou a\nacometer cotovelos e punhos. Há três semanas apresentou infecção de garganta (sic) tratada com\namoxicilina. Ao exame, apresenta temperatura axilar = 38.4°C; frequência cardíaca = 132 bpm;\nestado geral comprometido; dispneia leve que piora com o decúbito. A ausculta cardíaca mostra\nsopro holossistólico, de média intensidade, mais audível em ápice, irradiando-se para a axila; 3ª\nbulha audível. Diante do quadro de alta suspeita diagnóstica de febre reumática, qual a medicação\na ser prescrita nesse momento?","options":{"A":"Ibuprofeno.","B":"Diclofenaco.","C":"Naproxeno.","D":"Prednisona.","E":"Ácido Acetilsalicílico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-137599","number":"137599","sourceNumber":"137599","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma adolescente de 12 anos de idade é levada pela mãe ao Ambulatório de\nPediatria, apresentando quadro de dor nas articulações há cerca de 1 semana. Inicialmente,\nas dores se concentravam no joelho esquerdo, passando, em seguida, para o direito,\ncotovelos e punhos. Relata ter apresentado quadro de amigdalite bacteriana há cerca de\ntrês semanas, porém sem uso de antibióticos para tratamento. Ao exame, apresentava-se\nem regular estado geral, com facies de dor , hipocorada 1+/4+, hidratada, anictérica e acianótica.\nO exame do aparelho cardiovascular evidenciou sopro sistólico 4+/6+ em bordo esternal\nesquerdo, com irradiação para todo o precórdio. Ausculta pulmonar sem anormalidades.\n\nAbdome indolor à palpação e sem visceromegalias. O exame articular evidencia dor , calor ,\nrubor e limitação do arco de movimento em punhos e joelhos, principalmente à direita.\n\nConsiderando o diagnóstico mais provável, a patologia cardíaca mais frequentemente\nassociada e a medicação de escolha para o\ntratamento do processo inflamatório cardíaco\nsão, respectivamente,","options":{"A":"atresia aórtica e AAS.","B":"estenose pulmonar e nimesulida.","C":"regurgitação mitral e prednisona.","D":"forame oval patente e ibuprofeno.","E":"insuficiência tricúspide e naproxeno."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-137603","number":"137603","sourceNumber":"137603","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma mulher de 45 anos, com queixas de dores articulares há 5 meses, comparece ao\nambulatório para mostrar resultado de exames. Seu quadro começou com dores em mãos e pés,\npela manhã, com melhora durante o dia. Evoluiu há um mês com um surto de dor em articulações\ninterfalangeanas proximais, punhos, cotovelos e joelhos, com sinais de flogose, que melhorou com\no uso de indometacina por 10 dias. Ao exame, apresenta hipocromia de mucosas, edema e sinais\nde flogose discretos em mãos, com presença de nódulos justa-articulares e ausência de\ndeformidades. Traz exames complementares solicitados na consulta anterior: hemograma com Hb\n\n= 11,0 g /dL (valor de referência: 13,8 ± 2,5 g /dL), VHS = 56 mm na primeira hora (valor de\nreferência: ? 20 mm/h), prova do látex para\nfator reumatoide positiva, e radiografia das mãos que\nmostram redução da densidade óssea periarticular em articulações interfalangeanas proximais e\npunhos. A paciente, costureira, teme não poder trabalhar mais. Qual a medicação que poderia\nimpedir a progressão da doença?","options":{"A":"Aspirina.","B":"Colchicina.","C":"Metotrexate.","D":"Indometacina.","E":"Metilprednisona."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-30949","number":"30949","sourceNumber":"30949","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Julgue o item seguinte, a respeito da anatomia e fisiologia humanas. O fator intrínseco,\nmucoproteína secretada pelas células parietais gástricas, é essencial para a absorção de vitamina\nB12 no íleo terminal?","options":{"A":"Certo.","B":"Errado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-30975","number":"30975","sourceNumber":"30975","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um jovem com 18 anos de idade com diagnóstico de anemia falciforme foi trazido ao\npronto-socorro em consequência de hemiparesia direta e afasia iniciadas há uma hora. Os\nantecedentes pregressos desse paciente são seis episódios de vasoclusão ao longo da vida e\npolitransfusões sanguíneas. Julgue o item a seguir, relativo ao caso clínico em apreço. A despeito\nde os episódios de vasoclusão apresentados pelo paciente em tela causarem diversas debilidades\ne piorarem a qualidade de vida, não existe relação entre frequência dessas crises e mortalidade.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-30980","number":"30980","sourceNumber":"30980","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um jovem, 18 anos de idade, com diagnóstico de anemia falciforme foi trazido ao\npronto-socorro em consequência de\nhemiparesia direta e afasia iniciadas há uma hora. Os\nantecedentes pregressos desse paciente são seis episódios de vaso-oclusão ao longo da vida e\npolitransfusões sanguíneas. Julgue o item a seguir, relativo ao caso clínico em apreço. Como nessa\nsituação o principal diagnóstico é de evento isquêmico cerebral, deve-se realizar hemotransfusão\ncomo parte essencial do tratamento.","options":{"A":"Certo.","B":"Errado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-30983","number":"30983","sourceNumber":"30983","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um jovem, 18 anos de idade, com diagnóstico de anemia falciforme foi trazido ao\npronto-socorro em consequência de hemiparesia direta e afasia iniciadas há uma hora. Os\nantecedentes pregressos desse paciente são seis episódios de vasoclusão ao longo da vida e\npolitransfusões sanguíneas. Julgue o item a seguir, relativo ao caso clínico em apreço. De acordo\ncom as atuais evidências científicas, recomenda-se o uso hidroxiureia no tratamento desse\npaciente.","options":{"A":"Certo.","B":"Errado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-138667","number":"138667","sourceNumber":"138667","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina, com seis anos de idade, foi levada pela mãe à consulta em Unidade Básica de\nSáude por apresentar, há uma semana,\nintensa adinamia, quadro febril intermitente (temperatura =\n38º C) e dor articular, localizada inicialmente no joelho esquerdo, acompanhada de calor e rubor\ndiscreto e que, há dois dias, acomete o tornozelo direito. A mãe informa que, há cerca de seis\nsemanas, a criança apresentou quadro de infecção de vias aéreas superiores (faringite), que\nregrediu com o uso de amoxicilina durante cinco dias. Ao exame físico a criança encontrava-se\nafebril, eupneica, hidratada, com intensa adinamia, hipocorada (+/4), Frequência cardíaca=125\nbpm, Pressão arterial= 100 x 60 mmHg. A ausculta cardíaca e a ausculta pulmonar foram normais.\nFoi observada hiperemia, calor e dor no tornozelo direito, com limitação de movimentos e a\npresença de áreas eritematosas com centros esbranquiçados no tronco e na região proximal de\nmembros superiores e inferiores. Os exames laboratoriais revelaram: hemoglobina=10 g/dL,\nhematócrito=34%, leucócitos=14000/mm3, velocidade de hemossedimentação = 26mm/h, proteína\nC reativa= 2,0 ng/ml (valor de referência= <0,1 ng/mL); glicose, ureia e creatinina normais. O\neletrocardiograma mostra um prolongamento do intervalo P-R (0,20 s). Com base no quadro clínico\ndescrito e nos exames complementares realizados, qual o provável diagnóstico dessa criança?","options":{"A":"Artrite idopática juvenil.","B":"Lupus eritematoso sistêmico.","C":"Febre reumática.","D":"Síndrome de Reiter.","E":"Espondilartrose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-22180","number":"22180","sourceNumber":"22180","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma mulher de 62 anos de idade tem diagnóstico, há mais de 15 anos, de artrite\nreumatoide e, associadamente, apresenta anemia\nnormocrômica, normocítica e hipoproliferativa\nassociada com diminuição do ferro sérico e da saturação da transferrina, mas com aumento do\nferro de depósito. Acerca desse caso e das alterações hematológicas relatadas, julgue o item a\nseguir. Considerando o tipo mais provável de anemia apresentada pela paciente, os possíveis\nmecanismos etiofisipatogênicos envolvidos são: resposta medular inadequada diante de secreção\ninapropriadamente baixa de eritropoetina (EPO), diminuição da resposta da medula óssea à\nadministração de EPO e uma menor oferta de ferro à medula óssea, entre outros.","options":{"A":"certo","B":"errado"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-22197","number":"22197","sourceNumber":"22197","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Nesta questão é apresentado um quadro clínico hipotético, seguido de uma assertiva a\nser julgada. Um paciente de 9 anos de idade, em uma consulta de rotina, queixou-se de prurido\nanal exacerbado e com piora à noite. O exame físico revelou a presença de lesões\npapulovesiculares eritematosas e pruriginosas nos espaços interdigitais, axilas, face extensora dos\ncotovelos e abdome. A mãe apresentava as mesmas lesões de pele. Exames realizados\nrecentemente mostraram os seguintes resultados: exame parasitológico de fezes com cistos e\ntrofozoítos de Giardia lamblia; hemograma evidencia diminuição da hemoglobina e do volume\ncorpuscular médio e microcitose. Nessa situação, o hemograma do paciente é compatível com\nanemia por deficiência de ferro, que inialmente cursa com declínio do ferro sérico e aumento da\ncapacidade de ligação do ferro, seguido por diminuição da ferritina sérica.","options":{"A":"Certo","B":"Errado"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-335070","number":"335070","sourceNumber":"335070","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Para fins de diagnóstico da artrite reumatoide, a enzima que é solicitada rotineiramente\né a","options":{"A":"proteína amiloide.","B":"alfa-1 macroglobulina.","C":"alfa-2 macroglobulina.","D":"proteína C-reativa."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-304845","number":"304845","sourceNumber":"304845","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A artrite reativa em indivíduos com gene HLA-B27 pode ser desencadeada pelo\nseguinte quadro infeccioso:","options":{"A":"Amidalite estreptocócica.","B":"Uretrite gonocócica.","C":"Candidíase.","D":"Shigelose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-291940","number":"291940","sourceNumber":"291940","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Artrite Idiopática Juvenil (AIJ) é a doença reumática crônica mais frequente na faixa\netária pediátrica. É um processo inflamatório crônico, autoimune e com manifestações\n\nextra-articulares que variam de acordo com o tipo de início. Sobre os tipos de início, assinale a\nalternativa CORRETA:","options":{"A":"Na artrite poliarticular com fator reumatoide positivo, a artrite se encontra em 4 ou mais\narticulações, sendo o fator reumatoide positivo\nem 2 dosagens com intervalos de 3 meses durante\nos 6 primeiros meses da doença.","B":"O início oligoarticular pode ser descrito em duas categorias distintas, sendo elas a\noligoarticular\npersistente, que não atinge mais de 4\narticulações no curso da doença e oligoarticular estendida,\nquando compromete mais de 4 articulações na evolução.","C":"Na artrite poliarticular com fator reumatoide negativo, encontramos características clínicas\nsemelhantes à artrite reumatoide do adulto, com maior risco de evolução para erosão óssea e\nincapacidade funcional.","D":"Independente da forma de início, o tratamento será o mesmo, visando a rápida remissão da\nartrite e de suas manifestações extra-articulares, prevenindo o aparecimento de deformidades\nsecundárias, atrofia muscular e a osteoporose."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-291941","number":"291941","sourceNumber":"291941","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é uma doença importante na prática clínica pediátrica. Sobre a febre\nreumática, é CORRETO afirmar que:","options":{"A":"Ela é uma doença inflamatória relacionada faringotonsilite causada pelo estreptococo\nbeta-hemolítico do grupo B.","B":"As manifestações clínicas da febre reumática surgem em média após um período de latência de\n2 a 3 meses, após a infecção\nestreptocócica.","C":"A identificação de pelo menos 1 dos critérios maiores de Jones é essencial para o diagnóstico\nda doença no primeiro episódio de febre\nreumática.","D":"Embora não seja a doença reumática mais comum na faixa etária pediátrica no Brasil, a febre\nreumática deve ser conduzida com cuidado, uma vez que suas complicações e sequelas impactam\ndiretamente na capacidade funcional da criança e do adolescente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-266358","number":"266358","sourceNumber":"266358","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"As infecções osteoarticulares na criança são potencialmente graves, pois podem\nacarretar sequelas ao osso em crescimento. Nas\ninfecções osteoarticulares é correto afirmar:","options":{"A":"Na osteomielite hematogênica aguda a radiografia, por ter um baixo custo, é um bom meio de se\nfazer o diagnóstico precoce. As primeiras alterações radiográficas aparecem já no 1º dia.","B":"O Staphylococcus aureus é o agente etiológico mais comum na osteomielite e na pioartrite em\ncrianças e adolescentes.","C":"A artrite séptica compromete predominantemente as articulações dos membros superiores.","D":"Se o tratamento das infecções osteoarticulares for instituído precocemente pode ser feito via\noral, com antibiótico de largo espectro, por 15 dias."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-287862","number":"287862","sourceNumber":"287862","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre a Artrite Reumatoide (AR), assinalar a alternativa CORRETA:","options":{"A":"Trata-se de uma doença inflamatória sistêmica crônica, que acomete primariamente o tecido\nsinovial, com predomínio em articulações das mãos, punhos, temporomandibulares e porção\nsuperior da coluna lombar.","B":"Como manifestação clínica, pode ocorrer desvio radial dos dedos das mãos e as deformidades\nem \"\"pescoço de cisne\"\". A AR raramente acomete as\ninterfalangeanas distais.","C":"As manifestações extra-articulares da AR são mais comuns nos pacientes com fator reumatoide\nou anticorpos ACPA (anticorpos anti-peptídeos\ncitrulinados) positivos e podem ocorrer em pele,\ncoração, pulmão, olhos e sistema nervoso.","D":"A presença do fator reumatoide não é específica da AR, mas está presente em 80% dos\npacientes. A presença de fator reumatoide não tem relação com gravidade da doença articular.","E":"Os glicocorticoides têm um papel significativo no tratamento da AR, são úteis para a melhora\nsintomática e têm a capacidade de parar o processo da doença da sinóvia, modificando o potencial\nde deformidade; por esse motivo, são considerados medicamentos antirreumáticos modificadores\nde doença. Podem ser utilizados de forma isolada ou em associação ao metotrexato."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-234406","number":"234406","sourceNumber":"234406","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um homem de 21 anos vai ao pronto atendimento queixando-se de dor e edema no\njoelho direito há 3 dias. Nega comorbidades,\ndoenças prévias, trauma, uso regular de\nmedicamentos ou uso de quaisquer drogas. Ao exame físico, apresenta-se alerta e orientado. Os\ndados vitais são PA: 120 X 74mmHg, FC: 98bpm, FR: 19ipm, SpO? em ar ambiente 96%, Tax:\n38,4°C. O joelho direito está com o volume aumentado, apresenta calor e rubor local, além do sinal\nda tecla positivo. Exames de laboratório: Sangue: hemoglobina 13,1g/dL; leucócitos 17.210/mm³;\nneutrófilos segmentados 15.980/mm³; plaquetas 390.000/mm³; proteína C reativa 68mg/L. Líquido\nsinovial: citometria 70.450/mm³ (VR<2.000/mm³); neutrófilos 90%; pesquisa com coloração de\nGram: sem microrganismos coráveis. Considerando o caso descrito, assinale o PRINCIPAL agente\netiológico nessa condição.","options":{"A":"Cristais de pirofosfato de cálcio.","B":"Cristais de urato.","C":"Neisseria gonorrhoeae.","D":"Staphylococcus aureus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-246356","number":"246356","sourceNumber":"246356","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, 42 anos, feminino, previamente hígida, tabagista há 10 anos, 5 cigarros/dia.\nIniciou há 10 meses quadro de artralgia em\nmãos e punhos, associado a rigidez matinal de\narticulações das mãos e pés. Em sua primeira consulta com reumatologista, encaminhada da UBS,\no especialista evidencia ao exame físico que existe edema, calor e rubor em 2ª e 3ª\ninterfalangeanas proximais direitas, 3ª e 5ª metacarpofangeanas esquerdas, além de edema e calor\nde punho esquerdo. Paciente mostra alguns exames complementares já realizados na UBS: FAN\nnegativo, Fator reumatoide positivo, PCR 10 (VR menor que 5), AST 23 UI (VR: 40), ALT 34 UI (VR:\n45), Creatinina 1,1 mg/dl, HbsAg negativo, anti Hbs positivo, antiHCV negativo, antiHbc negativo,\nVDRL negativo, anti HIV negativo. Considerando o caso clínico acima, assinale a alternativa\ncorreta.","options":{"A":"Já se encontra bem estabelecida a relação entre o uso de tabaco e a maior suscetibilidade ao\ndesenvolvimento da artrite reumatoide em pacientes HLA-B27 positivos, pois o cigarro acelera as\nreações de citrulinização em proteínas pulmonares, o que dispara a produção de autoanticorpos.","B":"O reconhecimento dos complexos imunes por fagócitos promove liberação de diversas citocinas\npró-inflamatórias, principalmente a interleucina 12, o que exacerba ainda mais o processo\ninflamatório.","C":"O fator reumatoide representa um grupo de autoanticorpos caracterizados pela habilidade de\nreagir com determinados epítopos da porção fragmento cristalizável (Fc) da IgG e atua ativamente\nna patogênese da artrite reumatoide, sendo sua presença sugestiva de prognóstico desfavorável.","D":"O tratamento mais adequado para a paciente seria o início de metotrexato associado a\nmedicação biológica da classe anti TNF."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-227098","number":"227098","sourceNumber":"227098","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é uma complicação inflamatória aguda, não supurativa da infecção\nfaríngea por estreptococos do grupo A,\nusando combinações de artrites, cardites, nódulos\nsubcutâneos, eritema marginado e coreia. O diagnóstico baseia-se na aplicação dos critérios\nmodificados de Jones relacionados com dados de história, exame e testes laboratoriais. Assinale a\nalternativa que evidencia um critério MENOR para a febre reumática.","options":{"A":"Poliartrite.","B":"Poliartralgia.","C":"Eritema marginado.","D":"Nódulos subcutâneos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-232143","number":"232143","sourceNumber":"232143","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é uma doença caracterizada por reação auto-imune cruzada, não\nsupurativa, por mimetismo molecular entre proteínas bacterianas e proteínas constituintes\norgânicas. Os achados clínicos e os sintomas da doença guardam correção com o tipo de resposta\nimune desenvolvida. Dessa forma, a seguinte manifestação clínica ocorre por resposta imune\npredominantemente celular:","options":{"A":"Coréia.","B":"Artralgia.","C":"Artrite.","D":"Cardite.","E":"Eritema marginado."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-255665","number":"255665","sourceNumber":"255665","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Os pacientes adultos com artrite reumatoide, em geral apresentam qual queixa, entre\nas abaixo, como sintoma inicial da doença?\nMARQUE A CORRETA:","options":{"A":"Dor ao longo do dia em repouso ou em movimento.","B":"Rigidez matinal que dura mais de 1 hora e que melhora com atividade física.","C":"Artralgia em grandes articulações e com envolvimento poliarticular (> 10 articulações).","D":"Limitação de movimentos pelo comprometimento de membros inferiores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-202765","number":"202765","sourceNumber":"202765","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação aos achados clínicos na febre reumática, é CORRETO afirmar:","options":{"A":"Apesar de infrequente, em indivíduos com sintomas agudos a poliartrite é migratória, dolorosa e\nde grandes articulações.","B":"Apesar de o exame clínico sugerir o diagnóstico da Coréia de Sydeham, o mesmo deve ser\nconfirmado por meio de exames de neuroimagem.","C":"Nódulos cutâneos são comuns e específicos para o diagnóstico de febre reumática.","D":"Na cardite reumática, a gravidade da disfunção do ventrículo esquerdo parece estar\ncorrelacionada à extensão da valvulite, e não à lesão miocárdica.","E":"O eritema marginado geralmente tem início tardio no curso da febre reumática aguda."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-199623","number":"199623","sourceNumber":"199623","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Febre Reumática (FR) é a doença reumática mais comum no Brasil e pode afetar\npacientes geneticamente predispostos. Na febre reumática é CORRETO afirmar:","options":{"A":"O diagnóstico de febre reumática é feito com a presença da tríade: história de tonsilite, febre e\nmanifestações articulares.","B":"A cardite costuma ser diagnosticada nas três primeiras semanas da fase aguda e a principal\ncaracterística diagnóstica é a endocardite.","C":"Na febre reumática, a antiestreptolisina O começa a se elevar na primeira semana, após a\ninfecção estreptocócica, e normaliza com quatro semanas e seus títulos têm relação com a\ngravidade da FR.","D":"A poliartrite ocorre na maioria dos casos. Acomete grandes e pequenas articulações com\npredileção por joelho, punhos e articulações das mãos e pés."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-174358","number":"174358","sourceNumber":"174358","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Escolar de oito anos, do sexo feminino, apresenta quadro agudo de febre alta, dor e\nsinais inflamatórios em joelho direito e exantema serpiginoso evanescente e não pruriginoso em\ntronco, que piora com o calor. Exames complementares: Leucocitose e elevação da VHS. Neste\ncaso, a hipótese diagnóstica mais provável é:","options":{"A":"Artrite reumatoide.","B":"Febre reumática.","C":"Lúpus eritematoso.","D":"Artrite juvenil.","E":"Doença de Kawasaki."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-172510","number":"172510","sourceNumber":"172510","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Não é considerado um critério maior para o diagnóstico da febre reumática:","options":{"A":"Cardite.","B":"Artrite.","C":"Coréia.","D":"Nódulos subcutâneos.","E":"Eritema nodoso."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-162581","number":"162581","sourceNumber":"162581","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Considere as afirmativas abaixo em relação à artrite reumatoide. I ? A presença do fator\nreumatoide não estabelece o diagnóstico de artrite reumatoide; II ? Dentre os pacientes com artrite\nreumatoide, os que apresentam manifestações extra-articulares têm maior mortalidade; III ? A\nSíndrome de Felty consiste em artrite reumatoide crônica associada à esplenomegalia e\nneutropenia. Quais estão CORRETAS?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-162591","number":"162591","sourceNumber":"162591","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente feminina de 75 anos de idade encontra-se em avaliação por acometimento\nsistêmico da artrite reumatoide. Assinale a alternativa que NÃO apresenta manifestação\n\nextra-articular da artrite reumatoide:","options":{"A":"Ecocardiograma com derrame pericárdico.","B":"Eletroneuromiografia com mononeurite múltipla.","C":"Radiografia de tórax com infiltrado intersticial.","D":"Colonoscopia com nódulos colônicos.","E":"Lesões de pele compatíveis com pioderma gangrenoso."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-155443","number":"155443","sourceNumber":"155443","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma mulher de 76 anos apresenta-se no setor de emergência com piora na falta de ar.\nEla tem uma história médica pregressa de Diabetes Mellitus e estenose aórtica. O exame físico\nidentifica palidez, além de um sopro compatível com estenose aórtica. A concentração de\nhemoglobina dessa paciente é de 7,4 g/dL. Considerando riscos da paciente de apresentar tanto\nanemia por deficiência de ferro como anemia inflamatória, quais dos valores laboratoriais a seguir\nserão mais úteis no diagnóstico da causa de sua anemia?","options":{"A":"Capacidade Total de Ligação ao ferro e Nível de Ferro.","B":"Saturação de Transferrina e Nível de Ferritina.","C":"Nível de Ferritina e Capacidade Total de Ligação ao ferro.","D":"Nível de Ferro e Saturação de Transferrina.","E":"Nível de Ferro e Nível de Ferritina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-149117","number":"149117","sourceNumber":"149117","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à febre reumática, analise a assertivas abaixo: I- A febre reumática pode\ncausar pancardite, o principal folheto atingido é\no pericárdio II- A coréia de Sydenham é uma\nmanifestação do envolvimento dos gânglios da base do sistema nervoso central III- O padrão do\nenvolvimento da artrite é do tipo migratório, assimétrico e muito doloroso, com curso totalmente\nresolutivo IV- O eritema marginado e os nódulos subcutâneos são manifestações clinicas raras e\nem geral, estão associados à presença de artrite. Marque as alternativas corretas:","options":{"A":"Apenas I e II.","B":"Apenas II e III.","C":"Apenas III e IV.","D":"Apenas I e IV.","E":"Apenas II,III e IV."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-126914","number":"126914","sourceNumber":"126914","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre a macrocitose, assinale a alternativa CORRETA.","options":{"A":"A causa mais comum de macrocitose é a deficiência de vitamina B12.","B":"O uso de medicamentos como hidroxiuréia, a gestação e o hipotireoidismo podem levar à\nmacrocitose.","C":"A hemoglobinúria paroxística noturna caracteriza-se por tendência à trombose e predomínio de\nhemólise extravascular.","D":"Apesar de ser uma eritroenzimopatia rara a deficiência de G6PD causa sintomas de anemia\nhemolítica grave em mais de 90% dos pacientes."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-131633","number":"131633","sourceNumber":"131633","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"São dados encontrados nos pacientes portadores de Thalassemia, exceto:","options":{"A":"Reticulocitose.","B":"Esplenomegalia.","C":"Macrocitose.","D":"Cálculos biliares.","E":"Risco de hemocromatose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-131634","number":"131634","sourceNumber":"131634","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Esfregaço periférico de uma mulher de 40 anos revelou a presença de corpos de\nHowell ? Jolly nos eritrócitos. Dos abaixo, o mais provável é haver:","options":{"A":"Presença de hemoglobina C à eletroforese de hemoglobina.","B":"Presença concomitante de esquizócitos.","C":"Antecedente de esplenectomia.","D":"Deficiência de G6PD.","E":"Teste de Coombs positivo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-126901","number":"126901","sourceNumber":"126901","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Os critérios de Jones modificados são utilizados para diagnóstico de primeiro surto\nagudo da Febre Reumática (FR). Em relação\nao diagnóstico da Febre Reumática (FR), assinale a\nalternativa INCORRETA:","options":{"A":"A presença de duas manifestações maiores ou de uma maior e duas menores acrescidas da\nevidência de estreptococcia recente, indica alta probabilidade de FR.","B":"A coreia de Sydenham como manifestação isolada deve ser sempre acompanhada da\ncomprovação da estreptococcia.","C":"Os nódulos subcutâneos, a cardite e a artrite são sinais maiores.","D":"A artralgia, a febre e o intervalo do PR prolongado são sinais menores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-131688","number":"131688","sourceNumber":"131688","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Escolar de 8 anos em tratamento de infecção urinária com Sulfametoxazol +\nTrimetoprim, evolui com icterícia e colúria.\nTem bom estado geral. Baço e Fígado não palpáveis. Os\nexames laboratoriais mostram queda de hemoglobina, reticulocitose e hiperbilirrubinemia indireta.\n\nQual o diagnóstico mais provável?","options":{"A":"Deficiência de Glicose-6-Fosfato-Desidrogenase.","B":"Hepatite medicamentosa.","C":"Esferocitose hereditária.","D":"Hepatite A.","E":"Síndrome de Crigler-Najjar Tipo I."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-127216","number":"127216","sourceNumber":"127216","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Marcelo é um menino com anemia falciforme, de três anos de idade, que deu entrada\nno pronto atendimento apresentando dor\nabdominal, palidez, prostação e febre. No exame físico\napresentava temperatura axilar de 38°C, hipotensão, palidez cutânea acentuada, icterícia de\nesclera, taquipneia e taquicardia. A palpação do abdome foi encontrado fígado à 1 cm do rebordo\ncostal e baço à 5 cm. Qual a hipótese diagnóstica mais provável e qual a conduta ideal?","options":{"A":"Hepatite A + tratamento ambulatorial com repouso.","B":"Septicemia + ceftriaxona.","C":"Crise aplástica + concentrado de hemácia e plaquetas.","D":"Colelitíase aguda + cirurgia imediata da vesícula.","E":"Sequestro esplênico + internação com manutenção da estabilidade hemodinâmica."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-106434","number":"106434","sourceNumber":"106434","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Lara, 3 anos, tem queixas de dor em membros inferiores, principalmente após quadros\ninfecciosos. A mãe reclama que a filha tem uma anemia que nunca melhora, mesmo com uso de\nsulfato ferroso há meses. Ao exame físico: palidez, fígado a 1 cm do rebordo costal direito, baço\nnão palpável. Exames laboratoriais: Hematócrito = 23%; hemoglobina = 7,8 g/dl; reticulócitos: 6%;\nferritina: 88; hematoscopia: normocitose, normocromia, e hemácias em foice. Qual o diagnóstico\nmais provável?","options":{"A":"Anemia de Fanconi.","B":"Talassemia.","C":"Anemia falciforme.","D":"Anemia megaloblástica.","E":"Esferocitose Hereditária."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-111576","number":"111576","sourceNumber":"111576","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina, 4 anos de idade, tem diagnóstico de anemia falciforme (FSC), faz uso de\npenicilina oral desde os 3 meses de idade e recebeu vacinação adequada. Hoje apresenta\nadinamia, cansaço, dispneia, dor abdominal e fezes amolecidas. Ao exame está pálida, a FC é de\n150 bpm e o baço é palpável a 2 cm do RCE. A hemoglobina basal é de 9 g/dL e hoje é de 4,5\ng/dL, reticulócitos ausentes. Foi prescrito transfusão de concentrado de glóbulos e pedido:","options":{"A":"sorologia para eritrovírus.","B":"mielograma.","C":"hemocultura.","D":"dosagem de ferritina.","E":"coprocultura."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-88917","number":"88917","sourceNumber":"88917","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Lactente de 15 meses apresenta palidez das palmas das mãos que motivou a\nsolicitação de hemograma, cujo resultado revelou: Hgb = 7,5 g/dl, VCM = 68 ?3, RDW = 18% e\nreticulócitos corrigidos = 0,9%. São achados esperados para o caso em questão:","options":{"A":"ferritina \"menor ou igual\" 15, porcentagem de saturação em ferro da transferrina \"maior ou igual\"\n12, anisocitose e hipocromia.","B":"ferritina diminuída, porcentagem de saturação em ferro da transferrina > 16 e HCM \"menor ou\nigual\" 25 pg e anisocitose.","C":"ferritina \"menor ou igual\" 10 µg/L, porcentagem de saturação em ferro da transferrina entre 10 e\n16,\n\nanisocitose e HCM diminuído.","D":"ferritina < 10 µg/L, porcentagem de saturação em ferro da transferrina < 12, HCM diminuído e\nanisocitose.","E":"ferritina diminuída, porcentagem de saturação em ferro da transferrina \"maior ou igual\" 16, HCM\nnormal, anisocitose."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-77489","number":"77489","sourceNumber":"77489","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Lactente de 12 meses procura o ambulatório de pediatria do HUCAM com história de\npalidez, irritabilidade e anorexia. Não aceita alimentação (almoço e jantar). Ainda mama leite\nmaterno, que alterna com leite de vaca engrossado desde os 4 meses de idade. Não tem nenhum\nantecedente de doença ou internação. Em sua avaliação inicial:","options":{"A":"Deve-se pensar em anemia ferropriva, pois se trata de lactente em faixa etária de risco para\nesse tipo de anemia.","B":"O ferro do leite materno é muito bem absorvido e a amamentação mantida até essa idade,\nmesmo que quase exclusivamente, evita o aparecimento de anemia ferropriva.","C":"Como se trata de lactente sem nenhuma doença prévia, a possibilidade de talassemia minor\nestá afastada quando se pensa na etiologia da anemia.","D":"Não se pode afastar a possibilidade de esferocitose hereditária, já que as manifestações clínicas\nda doença só aparecem após os 4 meses de idade.","E":"A possibilidade de anemia ferropriva está afastada nessa situação clínica, especialmente se\ndurante o exame físico detectarmos esplenomegalia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-77495","number":"77495","sourceNumber":"77495","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um paciente de cinco anos de idade, sem história recente de amigdalite sintomática,\napresenta há dois meses quadro de movimentos\ninvoluntários incoordenados e rápidos, que\ndesaparecem durante o sono, associados à disartria, e que se mantêm até a consulta atual. O\ninício foi insidioso e caracterizado por labilidade emocional com fraqueza muscular. O único quadro\nconhecido de amigdalite sintomática seguida de elevação de ASLO (Antiestreptolisina O) ocorreu\nhá quatro meses. Não houve nenhuma outra manifestação clínica associada ao quadro atual,\nincluindo febre, artralgia, artrite ou qualquer outra anormalidade do sistema cardiovascular. No\nmomento, a proteína C-reativa e outros reagentes de fase aguda, como a VHS (Velocidade de\nHemossedimentação), estão dentro dos valores da normalidade. Analisando a situação acima, é\nCORRETO afirmar que a hipótese de febre reumática:","options":{"A":"É improvável se não houver pelo menos um critério de Jones maior e dois menores.","B":"Não deve ser confirmada se não houver pelo menos dois critérios de Jones maiores.","C":"Deve ser descartada se não houver alteração sugestiva de cardite na ecocardiografia.","D":"É provável, uma vez que a coreia é um critério de Jones que, se presente, mesmo isoladamente,\npermite o diagnóstico da doença.","E":"Deve ser afastada, uma vez que a comprovação de infecção recente pelo Streptococcus\npyogenes ocorreu muito tempo antes do início dos\nsintomas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-43930","number":"43930","sourceNumber":"43930","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente JCO apresenta quadro clínico compatível com abscesso esplênico. Na\ninvestigação diagnóstica, a doença hematológica que mais frequentemente causa abscesso\nesplênico é:","options":{"A":"Anemia hemolítica autoimune.","B":"Púrpura trombocitopênica idiopática.","C":"Anemia falciforme.","D":"Esferocitose hereditária.","E":"Talassemia maior."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-23125","number":"23125","sourceNumber":"23125","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"FT, 56 anos, previamente diabética tipo 2 e hipertensa, submetida à gastroplastia\nvertical com rescontrução em Y-de-Roux há 05 anos.\nAtualmente, não manifesta mais diabetes\nmellitus ou hipertensão arterial. Entretanto, refere há 06 meses astenia progressiva. Descorada\n\n++/4, com hemoglobina= 7,2 g/dL. Não usa qualquer suplemento vitamínico há 02 anos. A conduta\nmais apropriada seria:","options":{"A":"Transfusão de 02 concentrados de hemáceas e reintrodução do complexo vitamínico oral.","B":"Prescrição de suplemento de ferro por via oral + viatamina B12 por via parenteral.","C":"Prescrição de ferro por via parenteral + vitamina B12 parenteral.","D":"Prescrição de polivitamínico oral padrão + vitaminas A e B12 por via parenteral.","E":"Orientação nutricional + polivitamínico padrão para uso contínuo."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-9447","number":"9447","sourceNumber":"9447","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Está AUMENTADO na anemia por deficiência de ferro:","options":{"A":"Volume corpuscular médio (VCM).","B":"Capacidade total de ligação do ferro.","C":"Ferro sérico.","D":"Ferritina sérica.","E":"Saturação da transferrina."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-8115","number":"8115","sourceNumber":"8115","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 81 anos, gastrectomizado há 10 anos por adenocarcinoma gástrico,\napresentando disfagia, fraqueza muscular,\nalteração da memória e desequilíbrio. Qual a principal\nhipótese diagnóstica?","options":{"A":"Doença de Alzheimer.","B":"Neoplasia de esôfago.","C":"Deficiência de vitamina B12.","D":"Insuficiência vascular cerebral.","E":"Hipotiroidismo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-353844","number":"353844","sourceNumber":"353844","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre as manifestações clínicas articulares e extra-articulares da Artrite Reumatoide\n(AR): I. Caracteristicamente, a dor é de\nritmo inflamatório, piorando ao longo do dia e melhorando à\nnoite, além de piorar ao longo de exercícios físicos. II. Os nódulos subcutâneos são as\nmanifestações extra-articulares mais frequentes e localizam-se habitualmente sobre superfícies\nextensoras articulares, áreas submetidas à pressão e, mais raramente, em olhos, pulmões e cordas\nvocais. III. O derrame pleural da AR possui exsudato que apresenta, frequentemente, pH alto (>\n7,6), glicose aumentada (> 40 mg/dL), DHL diminuída (< 1000 UI/L) e dosagem do fator reumatoide\nnão reagente. Das proposições acima:","options":{"A":"Apenas II está correta.","B":"Apenas I está correta.","C":"Apenas I e II estão corretas.","D":"Todas estão incorretas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-363975","number":"363975","sourceNumber":"363975","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo feminino, 41 anos, parda, arquiteta, apresenta diagnóstico de artrite\nreumatoide. Ela procura o ambulatório de reumatologia com poliartrite em mãos, cotovelos, joelhos\ne tornozelos, há cerca de 3 meses, após suspensão de todas as medicações de uso contínuo, ao\nreceber a confirmação de que estava grávida. No momento está utilizando apenas a prednisona, 10\nmg por dia, prescrita por médico da Estratégia de Saúde da Família. Considerando que a paciente\nse encontra na 18ª semana de gestação, o esquema terapêutico adequado para o manejo do\nquadro articular deve ser","options":{"A":"Hidroxicloroquina, associada ao Rituximabe.","B":"Sulfassalazina, associada ao Tocilizumabe.","C":"Hidroxicloroquina, associada ao Certolizumabe.","D":"Sulfassalazina, associada ao Abatacepte."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-354764","number":"354764","sourceNumber":"354764","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A artrite gonocócica é causa comum de artrite séptica aguda em jovens sexualmente\nativos. Neste contexto, sabe-se que a artrite\ngonocócoca","options":{"A":"é 3-4 vezes mais comum em homens que mulheres, sendo mais frequente 3 a 4 semanas do\ncontato sexual.","B":"é comum a ocorrência de artrite supurativa, poliarticular em grandes articulações periféricas\ncomo joelhos, punhos, tornozelos e cotovelos.","C":"apresenta a tríade de tenossinovite, dermatite e poliartralgia, sendo que a tenossinovite ocorre\ncom maior frequência em dorso das mãos, dedos\ne pés.","D":"apresenta com padrão de oligoartrite assimétrica de membros inferiores com acometimento das\nsacroilíacas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-363916","number":"363916","sourceNumber":"363916","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Qual é a doença reumática mais comum na faixa etária pediátrica?","options":{"A":"Febre reumática.","B":"Lúpus eritematoso sistêmico.","C":"Espondilite anquilosante.","D":"Artrite reumatoide."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-334780","number":"334780","sourceNumber":"334780","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 57 anos de idade, na terceira semana do tratamento de tuberculose\npulmonar em uso do esquema preferencial\nconforme Manual e Recomendações para Controle da\nTuberculose no Brasil (Ministério da Saúde), passou a apresentar náuseas, vômitos e dor em\nhipocôndrio direito. Procurou Unidade Básica de Saúde, onde não foram constatados sinais de\ngravidade clínica, porém exames laboratoriais demonstraram TGO 460 U/L e TGP 530 U/L.\nPaciente sem história de hepatopatias prévias. Em qual condição o uso de um uricosúrico (droga\nredutora do ácido úrico) é fortemente recomendado ao paciente?","options":{"A":"Logo após a primeira crise de gota aguda.","B":"Na segunda crise de gota aguda e com diabetes mellitus.","C":"Com duas ou mais crises agudas de gota por ano.","D":"Com hiperuricemia (maior que 7 mg/dL) assintomática."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-321560","number":"321560","sourceNumber":"321560","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A artrite reumatoide é uma doença inflamatória autoimune, progressiva, que acomete\nprimariamente a membrana sinovial das articulações. De acordo com as Recomendações da\nSociedade Brasileira de Reumatologia, o primeiro esquema terapêutico a ser utilizado deve incluir\num DMARD (droga modificadora do curso da doença)","options":{"A":"biológico, preferencialmente anti-TNF.","B":"sintético alvo específico, preferencialmente tofacitinibe.","C":"bloqueador da coestimulação do linfócito T, preferencialmente abatacepte.","D":"sintético convencional, preferencialmente metotrexato."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-342650","number":"342650","sourceNumber":"342650","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma escolar de 8 anos apresenta quadro agudo de febre alta, dor e sinais inflamatórios\nno joelho direito e exantema serpiginoso\nevanescente e não pruriginoso no tronco, que piora com o\ncalor. Exames complementares: leucocitose e elevação da VHS. Nesse caso, a hipótese\ndiagnóstica mais provável é:","options":{"A":"artrite reumatoide","B":"febre reumática","C":"lúpus eritematoso","D":"artrite juvenil"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-302834","number":"302834","sourceNumber":"302834","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um paciente de 60 anos, diabético e hipertenso procurou o médico para avaliação de\nhiperuricemia. Vinha em uso de losartan, hidrocolorotiazida e merformina. Referia consumo\nalcoólico cerca de quatro vezes por semana, e o IMC estava em 32 kg/m2. Os níveis de ácido úrico\noscilaram nos últimos anos, entre 8,0 e 9,0 mg/dl. Dentre as medidas abaixo, qual NÃO deve ser\nrecomendada nesse caso?","options":{"A":"A Substituição do esquema anti-hipertensivo.","B":"Redução do consumo alcoólico.","C":"Engajamento em tratamento para redução de peso, com dieta e exercícios.","D":"Dosagem da excreção urinária de ácido úrico nas 24 horas.","E":"Alopurinol na dose inicial de 100 mg/dia, com elevações graduais até 300 mg/dia."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-300800","number":"300800","sourceNumber":"300800","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente, sexo masculino, 68 anos, relata dor intensa e rigidez em ambos os\ntornozelos. No exame físico, mostra calor,\nedema e grande derrame articular também em ambos os\ntornozelos. A artrocentese do tornozelo direito mostra a presença de cristais fracamente\nbirrefringentes positivos no líquido sinovial. A coloração de Gram é negativa. O diagnóstico mais\nprovável é:","options":{"A":"Doença de depósito de oxalato de cálcio.","B":"Artrite séptica.","C":"Artrite reativa.","D":"Pseudogota."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-314110","number":"314110","sourceNumber":"314110","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A artrite reumatoide é uma doença autoimune sistêmica, cuja prevalência é de cerca de\n1% no mundo, que acomete ambos os sexos,\ncom predomínio no sexo feminino. Dentre as\ndeformidades dos dedos que podem ser encontradas na doença estabelecida estão os \"dedos em\npescoço de cisne\", que se caracterizam por","options":{"A":"flexão das articulações metacarpofalangeanas e hiperextensão das articulações\ninterfalangeanas dos polegares.","B":"flexão das articulações interfalangeanas proximais e hiperextensão das articulações\ninterfalangeanas distais.","C":"hiperextensão das articulações interfalangeanas proximais e flexão das articulações\ninterfalangeanas distais.","D":"tumefação das articulações interfalangeanas proximais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-317161","number":"317161","sourceNumber":"317161","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 45 anos com quadro artrite de joelho direito que iniciou 3 dias antes da\nconsulta. Nega febre, perda ponderal e\nsudorese noturna. Não tem relato de trauma local. O\nmesmo refere eventos prévios, aproximadamente cinco vezes no último ano. Exame físico: artrite\nem joelho direito, com sinal da tecla positivo. Sem outras alterações. Traz os seguintes exames:\nhemograma: Hb 14; Ht 42; Leucócitos totais 12000 (VR 4000-10000); Plaquetas 200000; creatinina:\n2,0 mg/dl; uréia: 50: HLA-B27 ausente; análise do líquido sinovial: 10 ml de líquido amarelo\ncitrino,\ncom baixa viscosidade. Presença de 20 mil leucócitos/mm3; com 50% de polimorfonucleares; gram\nausente. Rx de joelhos: aumento de partes moles a direita, sem outras alterações. Qual o\ntratamento farmacológico para o quadro articular atual?","options":{"A":"Prednisona ou Prednisolona até 20mg/dia","B":"Associação de Prednisona 20mg/dia e Colchicina 0,5mg/dia","C":"Ibuprofeno 600mg 3x ao dia","D":"Tramadol 30mg associado a Paracetamol 500mg de 6/6h"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-300820","number":"300820","sourceNumber":"300820","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre é um sinal comum a vários problemas de saúde de crianças. A definição exata\nda temperatura, a partir da qual se considera\nfebre, é dada por pontos de corte arbitrários que\nvariam na literatura e conforme a região de aferição no corpo, geralmente como temperatura ?\n\n38ºC. Considerando a febre em crianças, são causas comuns de febre de origem indeterminada:","options":{"A":"Infecções virais e bacterianas do trato respiratório superior: rinossinusite, amidalite,\nfaringite,\notite média aguda, diarreia aguda.","B":"Infecção do trato urinário, pneumonia, sinusite, bacteremia.","C":"Artrite idiopática juvenil, lúpus eritematoso sistêmico, febre reumática, Doença de Crohn, colite\nulcerativa, leucemia, Linfoma não Hodgkin.","D":"Artrite séptica, osteomielite, síndromes virais, doença da arranhadura do gato, mononucleose\ninfecciosa, citomegalovirose, malária, tuberculose, reação à vacina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-311917","number":"311917","sourceNumber":"311917","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 52 anos comparece ao ambulatório central após internação hospitalar\nrecente para tratamento de um primeiro\nepisódio de monoartrite aguda por gota. Nega hipertensão\narterial ou diabetes, apresenta circunferência de cintura aumentada e obesidade (IMC = 31 kg/m²).\nNão há mais sintomas de artrite há 3 semanas. Em relação à prevenção de novas crises de gota, a\nmelhor abordagem é","options":{"A":"recomendar redução de peso, redução de ingesta de bebida alcoólica e discutir risco-benefício\ndo tratamento hipouricemiante.","B":"iniciar alopurinol, buscando nível sérico de ácido úrico < 7mg/dl.","C":"iniciar alopurinol e colchicina, buscando nível sérico de ácido úrico < 6mg/dl.","D":"iniciar colchicina apenas, reservando alupurinol apenas se ácido úrico ? 9mg/dl."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-313211","number":"313211","sourceNumber":"313211","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um homem de 42 anos está com queixa de dor no joelho direito associado a edema,\nrubor e calor local há 3 dias. Nega outras\nqueixas, e não há outros achados ao exame clínico.\n\nRealizada artrocentese que evidenciou: leucócitos 35.000/mm³, com predomínio de neutrófilos e\ncristais de monourato de sódio com birrefringência negativa. Nesse caso, o diagnóstico e a conduta\nadequada são:","options":{"A":"gota; receitar anti-inflamatório","B":"artrite séptica; prescrever corticoide","C":"pseudogota; receitar rasburicase","D":"artrite reumatoide; iniciar metotrexato"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-314128","number":"314128","sourceNumber":"314128","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"É critério maior de Jones para febre reumática:","options":{"A":"poliartralgia.","B":"intervalo PR aumentado no eletrocardiograma (ECG).","C":"febre maior que 38,5 ºC.","D":"coreia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-295424","number":"295424","sourceNumber":"295424","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma garota de cinco anos tem artrite em joelho direito há aproximadamente dois\nmeses, com contratura em flexão, e, à\ninvestigação, apresentou um teste de FAN positivo, titulação\n1/320, padrão nuclear pontilhado. Isso significa que ela:","options":{"A":"Provavelmente tem lúpus eritematoso.","B":"Tem risco maior de acometimento ocular.","C":"Tem maior risco de apresentar espondilopatia na vida adulta.","D":"Tem pior prognóstico articular."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-295425","number":"295425","sourceNumber":"295425","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Qual a lesão cardíaca mais frequente na fase aguda de febre reumática?","options":{"A":"Estenose mitral.","B":"Insuficiência aórtica.","C":"Estenose aórtica.","D":"Insuficiência mitral."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-281264","number":"281264","sourceNumber":"281264","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Assinale a alternativa incorreta com relação ao diagnóstico da Hiperferritinemia.","options":{"A":"A ferritina sérica pode ser um importante auxiliar no diagnóstico e no prognóstico de pacientes\ncríticos.","B":"Um valor de ferritina dentro da normalidade não exclui o diagnóstico de processo inflamatório.","C":"A ferritina sérica é um exame barato e de fácil execução.","D":"Hiperferritinemia e hemofagocitose são sinônimos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-274758","number":"274758","sourceNumber":"274758","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente com 06 anos de idade, sexo feminino, com história de dor súbita em joelho\nesquerdo há 02 dias e piora progressiva. Apresentou pico febril não medido, com inapetência e\nmarcha impossibilitada pela dor. Sem história prévia conhecida de comorbidades. Deu entrada no\npronto socorro com piora importante da dor nas últimas horas. Ao exame físico, apresenta bloqueio\narticular, com aumento de volume e calor local. Foi submetida a punção articular e a análise do\nlíquido sinovial evidenciou aumento do número de células com predomínio de polimorfonucleares,\nelevação das proteínas e redução da glicose. A hipótese diagnóstica e a respectiva conduta devem\nser:","options":{"A":"artrite séptica. Deve-se iniciar antibioticoterapia oral associada a analgesia potente. Liberar\npaciente para retorno ambulatorial em 48 horas com exames laboratoriais.","B":"artrite reativa. Deve-se iniciar uso de anti-inflamatórios não esteroidais e corticoides orais.\n\nLiberar a paciente para retornar em 48 horas com exames laboratoriais.","C":"artrite séptica. Deve-se iniciar antibioticoterapia venosa, encaminhar imediatamente para\ndesbridamento cirúrgico de urgência da cavidade articular com coleta de material para cultura.","D":"artrite reativa. Deve-se iniciar pulsoterapia com internação para avaliação da resposta ao\ntratamento e seguimento da função renal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-277412","number":"277412","sourceNumber":"277412","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma paciente de 25 anos apresenta astenia, febre baixa, oligoartrite assimétrica dos\nmembros inferiores, dactilite em mãos e pés,\ndisúria e hiperemia ocular há 1 semana. O diagnóstico\nmais provável para essa paciente é?","options":{"A":"lúpus eritematoso sistêmico","B":"doença de Behçet","C":"sarcoidose aguda","D":"artrite reativa"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-273147","number":"273147","sourceNumber":"273147","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Considerando os tipos de Artrite Idiopática Juvenil (AIJ), a alternativa que se\nrelaciona à\nAIJ oligoarticular é:","options":{"A":"É o tipo mais frequente, que corresponde a cerca de metade dos casos de AIJ e se caracteriza\npela presença de artrite que atinge até quatro\narticulações, geralmente joelho e/ou tornozelo.","B":"Ocorre quando mais de cinco articulações são atingidas de maneira simétrica nos primeiros 6\nmeses da doença, como pés, tornozelos, joelhos, mãos, pescoço etc.","C":"Ocorre por transmissão hereditária, onde normalmente afeta mais meninas entre o 1º e o 4º ano\nde vida.","D":"É o tipo menos frequente e, além da artrite, tem como característica principal a presença de\nfebre muito alta (acima de 39° C) que vai e\nvolta por um tempo prolongado em 100% dos casos,\nfrequentemente acompanhada de manchas róseas na pele, que tendem a aparecer com a febre e\ndesaparecer quando a temperatura normaliza."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-257735","number":"257735","sourceNumber":"257735","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em pacientes com doenças autoimunes, a principal citocina responsável por elevação\nsérica das proteínas de fase aguda, leucocitose e anemia de doença crônica, e seu respectivo\nmedicamento imunobiológico, é:","options":{"A":"IL-6 - tocilizumabe.","B":"IL-1 - adalimumabe.","C":"BAFF - anti-Blys.","D":"TNF-alfa - abatacepete."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-258185","number":"258185","sourceNumber":"258185","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é uma doença inflamatória e autoimune que apresenta como\ncaracterística:","options":{"A":"A artrite é a manifestação clínica mais frequente da doença aguda, com dor de pequena\nintensidade e proporcional aos demais achados inflamatórios.","B":"As valvas cardíacas mais acometidas são a mitral e a tricúspide e, durante o surto agudo, a\nlesão predominante é a de estenose.","C":"Na eletrocardiografia, o alongamento do intervalo PR é a anormalidade mais importante, sendo\nconsiderado um critério menor para o diagnóstico de cardite.","D":"A profilaxia secundária pode ser feita com penicilina V oral, a qual proporciona menor risco de\nrecorrência da doença quando comparada com a penicilina benzatina intramuscular."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-257736","number":"257736","sourceNumber":"257736","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em 2011, o EULAR (European League Against Rheumatism) publicou novas\nrecomendações para a classificação dos\npacientes com doenças por deposição de cristais de\npirofosfato di-hidratado de cálcio, definindo quatro tipos de apresentação da doença. Nesse\ncontexto,","options":{"A":"a forma assintomática é a apresentação menos comum, e caracteriza-se pelo achado de\ncondrocalcinose em exame de imagem.","B":"a forma de artrite aguda caracteriza-se por poliartrite, com dor forte e edema, sendo bastante\nfrequente em indivíduos com menos de 60 anos de idade.","C":"na forma associada com osteoartrite , observa-se envolvimento de articulações muito usuais na\nosteoartrite primária, tais como os joelhos e a coluna vertebral.","D":"na forma de artrite inflamatória crônica, observa-se poliartrite de grandes e pequenas\narticulações, semelhante à artrite reumatoide."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-258243","number":"258243","sourceNumber":"258243","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na Artrite Idiopática Juvenil (AIJ):","options":{"A":"O exantema típico, caracterizado por lesões maculares ou maculopapulares na cor\nrosado-salmão, é frequentemente pruriginoso.","B":"A febre de caráter intermitente, com um a dois picos diários, ocorre em 80% dos casos.","C":"A esplenomegalia é volumosa e é mais comum do que a hepatomegalia.","D":"O envolvimento cardíaco pode preceder as manifestações articulares da doença."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-246523","number":"246523","sourceNumber":"246523","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Considerando-se os critérios de Jones modificados, na evidência de infecção\nestreptocócica anterior, qual das associações de\nsinais e sintomas preenche critérios para febre\nreumática?","options":{"A":"Febre e artrite.","B":"Cardite e Febre.","C":"Nódulos subcutâneos e artralgia.","D":"Coreia de Sydenham e artrite.","E":"Eritema Marginatun e febre."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-254214","number":"254214","sourceNumber":"254214","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 35 anos, artralgia em joelho com sinal de tecla positivo. Submetida a\nartrocentese que revelou presença de cristais\nrombóides com birrefringência positiva. Pode-se\nafirmar que o provável diagnóstico é:","options":{"A":"Gota.","B":"Pseudogota.","C":"Artrite reumatoide.","D":"Nenhuma das anteriores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-246524","number":"246524","sourceNumber":"246524","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Entre os agentes imunobiológicos utilizados no tratamento da artrite reumatoide, qual\nagente não atua através do bloqueio do TNF-alfa?","options":{"A":"Infliximabe.","B":"Etanercepte.","C":"Golimumabe.","D":"Adalimumabe.","E":"Tocilizumabe."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-241692","number":"241692","sourceNumber":"241692","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"É contraindicação para a realização de artrocentese na artrite séptica:","options":{"A":"hiperglicemia.","B":"imunossupressão.","C":"infecção sistêmica tratada.","D":"trombocitopenia.","E":"uso de antiplaquetários."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-229500","number":"229500","sourceNumber":"229500","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Artrite Reumatoide apresenta um curso de doença progressivo, determinando\ndeformidades decorrentes de ruptura dos tendões e das\nerosões articulares. Entre os achados\ntemos desvio e lesões diversas, qual dos itens está ERRADO pela descrição?","options":{"A":"?Mãos em dorso de camelo?, aumento de volume do punho e das articulações MCF com atrofia\ninteróssea dorsal.","B":"Joelhos valgos, desvio medial.","C":"Tornozelos valgos, eversão da articulação subtalar.","D":"Hálux valgo, desvio medial do hálux."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-229502","number":"229502","sourceNumber":"229502","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A doença reumatoide do pulmão e a vasculite reumatoide são manifestações\nextra-articulares geralmente graves, devendo ser tratadas\ncom imunossupressores. Podemos\nassim aceitar como CORRETA a alternativa:","options":{"A":"Apenas pulsoterapia com succinato de metilprednisolona intravenosa é opção terapêutica.","B":"Pulsoterapia com succinato de metilprednisolona intravenosa, prednisona por via oral,\nazatioprina por via oral, ciclosporina por via\noral intravenosa são opções terapêuticas e nunca a\nciclofosfamida.","C":"Pulsoterapia com succinato de metilprednisolona intravenosa, prednisona por via oral,\nazatioprina por via oral, ciclosporina por via oral e ciclofosfamida intravenosa são opções\nterapêuticas.","D":"Pulsoterapia com succinato de metilprednisolona intravenosa, e ciclofosfamida intravenosa são\nopções terapêuticas não sendo indicado prednisona\npor via oral, azatioprina por via orale\nciclosporina por via oral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-229503","number":"229503","sourceNumber":"229503","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O tratamento de Artrite Reumatoide (AR) deve ser iniciado o mais breve possível, uma\nvez que a terapia medicamentosa intensiva\ninstituída precocemente previne danos estruturais\n(erosões), melhorando a capacidade funcional. Podemos CONCORDAR que:","options":{"A":"O período inicial da doença, principalmente as dez primeiras semanas (AR inicial), configura\numa janela de oportunidade terapêutica, isto é,\num momento em que a intervenção farmacológica\nefetiva pode mudar o curso da doença.","B":"O período inicial da doença, principalmente os doze primeiros meses (AR inicial), configura uma\njanela de oportunidade terapêutica, isto é, um momento em que a intervenção farmacológica efetiva\npode mudar o curso da doença.","C":"O período inicial da doença, principalmente os doze primeiros meses (AR inicial), já não\nconfigura uma janela de oportunidade\nterapêutica, visto que a intervenção farmacológica não é\nefetiva pode mudar o curso da doença.","D":"O período tardio da doença, principalmente os dois primeiros anos (AR inicial), configura uma\njanela de oportunidade terapêutica, isto\né, um momento em que a intervenção farmacológica efetiva\npode mudar o curso da doença."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-246531","number":"246531","sourceNumber":"246531","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Considerando as características da artrite reumatoide, assinale a alternativa incorreta.","options":{"A":"Fator reumatoide positivo, além de compor os critérios prognósticos, é um fator prognóstico.","B":"Anti-peptídeos citrulinados cíclicos são marcadores com sensibilidade semelhante à do fator\nreumatoide, mas com especifidade superior, sobretudo na fase inicial da doença.","C":"As manifestações articulares tendem a ser simétricas, embora, quando se trate das IFP, das\nMCF e das metatarsofalangeanas (MTF), a\nsimetria não necessite se completa.","D":"A doença é predominante oligo-articular, acometendo predominantemente grandes articulações,\ncom acometimento menor de pequenas articulações.","E":"Alterações articulares como dedo em pescoço de cisne, dedo em botoeira e desvio ulnar são\nmanifestações tardias da doença, não sendo evidenciadas nas fases precoces da doença."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-229505","number":"229505","sourceNumber":"229505","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A falha secundária da Artrite Reumatoide aos Medicamentos Modificadores do Curso\nda Doença (MMCD), quando, após resposta\nsatisfatória inicial, pode ser explicada:","options":{"A":"Esta falha tem sido atribuída ao surgimento de anticorpos contra a molécula dos MMCD\nbiológicos, que apresentam menor imunogenecidade do que os MMCD sintéticos.","B":"Esta falha tem sido atribuída ao surgimento de anticorpos contra a molécula dos MMCD\nbiológicos, que apresentam maior imunogenecidade do que os MMCD sintéticos.","C":"Esta falha tem sido atribuída ao surgimento de anticorpos contra a molécula dos MMCD\nsintéticos, que apresentam maior imunogenecidade do que os MMCDbiológico.","D":"Esta falha não tem sido atribuída ao surgimento de anticorpos contra a molécula dos MMCD\nbiológicos, que apresentam maior imunogenecidade do que os MMCD sintéticos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-246533","number":"246533","sourceNumber":"246533","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente masculino, 58 anos, obeso, com história de episódios de artrite recorrente em\nprimeira articulação metatarso-falangiana (MTF) direita. Procura atendimento na unidade de saúde\ncom presença de edema, hiperemia e rubor em primeira articulação MTF direita e joelhos, piorando\nao deambular - sintomas iniciados há 18 horas. O ácido úrico sérico apresenta-se 9,4 mg/dl (VR.\naté 6.0 mg/dl). Qual o melhor tratamento indicado para o caso?","options":{"A":"Colchicina + alupurinol.","B":"Prednisona + alopurinol.","C":"Ibuprofeno + alopurinol.","D":"Alopurinol.","E":"Colchicina e, após resolução da artrite, iniciar alopurionol."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-229508","number":"229508","sourceNumber":"229508","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Artrite Reumatoide tem seu diagnóstico estabelecido com base em achados clínicos e\nexames complementares. Podemos APENAS aceitar que:","options":{"A":"O exame histopatológico, estabelece o diagnóstico isoladamente.","B":"Somente exame laboratorial isoladamente estabelece o diagnóstico.","C":"Nenhum exame isoladamente, seja laboratorial, de imagem ou histopatológico, estabelece o\ndiagnóstico.","D":"Nenhum exame de imagem ou histopatológico, estabelece o diagnóstico mesmo em conjunto."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-229509","number":"229509","sourceNumber":"229509","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Além da perda de capacidade funcional na Artrite Reumatoide, pode haver aumento\ntambém da mortalidade, o que demonstra a gravidade da doença, sendo CORRETO que:","options":{"A":"As manifestações articulares como nódulos reumatoides, vasculite, derrame pleural, episclerite e\nescleromalacia perfurante correlacionam-se com pior prognóstico.","B":"As manifestações extra-articulares (nódulos reumatoides, vasculite, derrame pleural, episclerite\ne\nescleromalacia perfurante, entre outras) não correlacionam-se com pior prognóstico.","C":"As manifestações extra-articulares (nódulos reumatoides, vasculite, derrame pleural, episclerite\ne escleromalacia perfurante, entre outras)\ncorrelacionam-se com melhor prognóstico.","D":"As manifestações extra-articulares (nódulos reumatoides, vasculite, derrame pleural, episclerite\ne escleromalacia perfurante, entre outras)\ncorrelacionam-se com pior prognóstico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-249857","number":"249857","sourceNumber":"249857","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 48 anos apresenta dor, de intensidade 7/10, aumento de volume e limitação\naos movimentos do joelho esquerdo, de início há\numa semana. Nega episódios semelhantes\nanteriormente. Nega trauma local. Foi submetido a uma punção articular e a análise do líquido\nsinovial revelou: volume = 20 ml; cor = amarelo; viscosidade = baixa; leucócitos = 5.000/mm³;\npolimorfonucleares = 55%; cultura = negativa. De acordo com as características descritas, o líquido\nsinovial deste paciente pode ser classificado como:","options":{"A":"normal.","B":"não inflamatório.","C":"inflamatório.","D":"séptico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-229513","number":"229513","sourceNumber":"229513","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Entre os Medicamentos Modificadores do Curso da Doença (MMCD) sintéticos para o\ntratamento de AR, o metotrexato é o medicamento padrão, devendo ser iniciado tão logo o\ndiagnóstico seja definido. Podemos ACEITAR que:","options":{"A":"Metotrexato não foi seguro, apesar de eficaz na redução de sintomas, na incapacidade\nfuncional.","B":"Metotrexato foi seguro e eficaz na redução de sintomas, na incapacidade funcional, mas não no\ndano estrutural.","C":"Metotrexato foi seguro e eficaz na redução de sintomas, na incapacidade funcional e no dano\nestrutural, sendo semelhante a leflunomida e superior a outros MMCD sintéticos.","D":"Metotrexato foi inseguro e ineficaz na redução de sintomas, na incapacidade funcional."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-252755","number":"252755","sourceNumber":"252755","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 35 anos, do sexo feminino, procura atendimento referindo rigidez matinal\nnas articulações, com duração de mais de 1 hora,\nprincipalmente nas articulações das mão e pés,\nfadiga, febre, mal-estar e aparecimento de nódulos subcutâneos. Ao exame, há artrite e\ndeformidade em articulações metacarpofalangenas e interfalangenas proximais. Algumas\narticulações apresentam deformidades em pescoço de cisne. Exames mostraram derrame pleural\nna radiografia de tórax, anemia normocítica normocrômica no hemograma, proteína C reativa e\nvelocidade de hemossedimentação aumentadas. Radiografia das articulações mostra edema de\ntecidos moles, perda simétrica do espaço articular, e erosões subcondrais, nas articulações das\nmãos. Anticorpo antipeptídeo citrulinado positivo. O diagnóstico mais provável é:","options":{"A":"Síndrome de Sjogren.","B":"Artrite enteropática.","C":"Granulomatose de Wegener.","D":"Artrite reumatoide."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-252756","number":"252756","sourceNumber":"252756","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A síndrome de Felty se caracteriza por:","options":{"A":"Artrite reumatoide, esplenomegalia e neutropenia.","B":"Lúpus eritematoso sistêmico, leucocitose e hepatomegalia.","C":"Esclerose sistêmica, plaquetopenia e cardiomegalia.","D":"Vasculite crioglobulinêmica, linfocitose e hepatomegalia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-234340","number":"234340","sourceNumber":"234340","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Nos processos articulares inflamatórios, as possibilidades diagnósticas são definidas de\nacordo com o número de articulações envolvidas. Em um paciente com monoartrite aguda, a\nartrocentese contribui para auxílio na investigação diagnóstica e, na suspeita de uma causa\ninflamatória, o líquido sinovial apresenta como características:","options":{"A":"Claridade transparente e cor vermelha.","B":"Viscosidade baixa e contagem de neutrófilos maior que 50%.","C":"Contagem de leucócitos menor que 200 células/mm³ e claridade opaca.","D":"Cor amarela e viscosidade alta."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-232241","number":"232241","sourceNumber":"232241","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A artrite reativa é uma enfermidade sistêmica, caracterizada por sintomas gerais e\nmanifestações articulares. Tem um pico de incidência dos 20 aos 40 anos e é incomum em\nindivíduos menores de 15 anos e em idosos. Vários fatores de risco podem influenciar o\nprognóstico dos pacientes em relação à cronificação da doença. Dentre estes fatores, cita-se:","options":{"A":"Presença de manifestações viscerais.","B":"Sexo feminino.","C":"Etiologia intestinal, associada à Shigella flexneri.","D":"Presença do HLA-DR4."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-234341","number":"234341","sourceNumber":"234341","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 72 anos queixa-se de dor de forte intensidade (9/10) e edema do joelho\nesquerdo, de início há um dia. A radiografia\nsimples mostra calcificação linear do menisco medial. A\nanálise do líquido sinovial mostra, à microscopia de luz polarizada, a presença de cristais\nromboides com birrefringência positiva fraca. A principal hipótese diagnóstica para este paciente\né:","options":{"A":"Gota.","B":"Artrite reativa.","C":"Condrocalcinose.","D":"Artrite séptica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-249876","number":"249876","sourceNumber":"249876","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Quais os critérios maiores utilizados para se fazer diagnóstico de febre reumática?","options":{"A":"Artrite, cardite, coreia, nódulos subcutâneos e eritema marginado.","B":"Febre, artralgia, alteração no eletrocardiograma (ECG), aumento de VHS (velocidade de\nhemossedimentação) e aumento de PCR (proteína C reativa).","C":"Faringotonsilite, gânglios cervicais, febre, taquicardia.","D":"Alteração de ASLO (antiestreptolisina O), polidipsia, irritabilidade, pletora clínica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-234401","number":"234401","sourceNumber":"234401","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo feminino, de seis anos, apresenta artrite há três meses de punho\nesquerdo e nos joelhos (com contratura em\nflexão e diminuição do espaço articular à radiologia),\nsem outras manifestações clínicas. O resultado do FAN é 1:320, com padrão nuclear pontilhado.\nQual é a melhor interpretação deste achado laboratorial?","options":{"A":"Pior prognóstico do envolvimento articular.","B":"Risco relativo maior para desenvolver espondiloartropatia.","C":"Risco relativo maior para desenvolver lúpus (LES)","D":"Maior chance de desenvolver manifestação extra-articular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-217017","number":"217017","sourceNumber":"217017","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre a fisiopatologia da artrite gotosa, assinale a alternativa correta.","options":{"A":"A maioria dos pacientes com gota produz quantidade elevada de ácido úrico.","B":"Há precipitação de cristais de monourato de cálcio no espaço sinovial.","C":"A doença é rara em homens abaixo de 30 anos e em mulheres antes da menopausa.","D":"Cerca de 75% dos indivíduos com hiperuricemia são afetados pela gota.","E":"Obesidade, dislipidemia e aterosclerose não se associam ao risco da doença."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-210556","number":"210556","sourceNumber":"210556","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A respeito do tratamento da artrite sépica não complicada com hemocultura positiva,\nassinale a afirmativa correta.","options":{"A":"Na presença de cocos gram-positivos, a primeira escolha é vancomicina.","B":"O achado de diplococos gram-negativos contrapõe a suspeita de artrite gonocócica.","C":"Se precedida por mordedura de cão ou gato, é indicada ampicilina-sulbactam.","D":"A artrite pós-procedimento pode ser tratada em monoterapia com cefepime.","E":"No caso de bacilos gram-negativos, ceftazidime é uma opção ineficaz."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-210557","number":"210557","sourceNumber":"210557","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre os fatores desencadeantes da crise aguda de gota, julgue os itens\nsubsequentes. l. Ingesta excessiva de\nálcool; ll. Deficiência dietética de purinas; lll. Exercício físico\nextenuante; lV. Radioterapia. Pode-se afirmar que:","options":{"A":"Apenas os itens l, ll e lll estão certos.","B":"Apenas os itens l e lll estão certos.","C":"Apenas os itens l, lll e lV estão certos.","D":"Apenas os itens ll e lV estão certos.","E":"Apenas os itens lll e lV estão certos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-214170","number":"214170","sourceNumber":"214170","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Segunda a Sociedade Brasileita de Pediatria e a Sociedade Brasileira de Reumatologia,\na artrite idiopática juvenil (AIJ) é\nutilizada para definir um grupo de doenças de etiologia\ndesconhecida, caracterizadas pela presença de artrite crônica de ínicio antes dos 16 anos de idade.\nEsta patologia provoca aumento do volume articular pela presença de dor associada à limitação do\nmovimento articular, presente por pelo menos seis semanas. Na avaliação laboratorial em casos de\nArtrite Idiopática Juvenil afirma-se que","options":{"A":"o fator reumatoide é positivo na maioria dos casos.","B":"a forma poliarticular deve ser acompanhada de fator reumatoide postivo.","C":"a presença de valores normais de marcadores inflamatórios (como proteína C reativa e\nvelocidade de hemossedimentação) exclui o diagnóstico.","D":"a presença de AAN (anticorpo anti-nucleo) positivo está relacionada a maior risco de uveite\nanterior."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-202716","number":"202716","sourceNumber":"202716","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A gota é uma doença hereditária crônica do metabolismo das purinas, que acomete,\nprincipalmente, o sexo masculino, entre a terceira e a quarta décadas de vida. Várias condições\npodem se associar à gota e/ou hiperuricemia, dentre as quais se inclui:","options":{"A":"amiloidose.","B":"hipertireoidismo.","C":"pneumopatia intersticial.","D":"pré-eclâmpsia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-216490","number":"216490","sourceNumber":"216490","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Dentre os agentes infecciosos abaixo, qual é o principal causador da artrite infecciosa\nem adultos?","options":{"A":"Staphylococcus aureus.","B":"Aspergillus spp.","C":"Escherichia coli.","D":"Streptococcus pneumoniae."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-202697","number":"202697","sourceNumber":"202697","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é uma doença inflamatória que ocorre como manifestação tardia de\numa faringotonsilite causada pelo","options":{"A":"Haemophilus influenzae.","B":"Streptococcus piogenes.","C":"Streptococcus Beta-hemolítico do grupo A.","D":"Streptococcus Beta-hemolítico do grupo B."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-202708","number":"202708","sourceNumber":"202708","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Os critérios de Jones existem para facilitar o diagnóstico de um surto agudo de febre\nreumática. Existem os critérios maiores e os menores. É um critério maior:","options":{"A":"Febre.","B":"Artralgia.","C":"Aumento do intervalo PR no Eletrocardiograma (ECG).","D":"Nódulos subcutâneos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-215433","number":"215433","sourceNumber":"215433","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"No Brasil, estudo epidemiológico constatou que a Artrite Psoríaca AP é a segunda\nespondiloartropatia mais frequente, com prevalência de 13,7% em relação às espondiloartrites.\nEstá inadequado apenas o item:","options":{"A":"Ocorre predominância de ocorrência no sexo masculino (59% versus 41%) e a manifestação\nperiférica da doença.","B":"Em relação à patogênese, a AP é uma doença autoimune poligênica, de etiologia definida.","C":"As citocinas relacionadas a linfócito T desempenham papel central.","D":"Fatores ambientais (microtrauma e agentes infecciosos) têm sido relacionados."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-173539","number":"173539","sourceNumber":"173539","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 40 anos apresenta artrite nos pés, tornozelos, joelhos, mãos e punhos, de\ninício há cinco anos, em uso apenas de corticoide injetável durante este período. Sem outras\nqueixas. Ao exame físico, encontra-se em regular estado geral, corada, afebril, com artrite nos\njoelhos, punhos e metacarpofalangianas, squeeze test positivo nos pés e deformidades \"em\nbotoneira\" no 3º e 4º quirodáctilos direitos. Considerando-se a principal hipótese diagnóstica para\nessa paciente, a deformidade descrita nos quirodáctilos caracteriza-se por:","options":{"A":"Hiperextensão da articulação interfalangiana proximal e flexão da articulação interfalangiana\ndistal.","B":"Flexão da articulação interfalangiana proximal e hiperextensão da articulação interfalangiana\ndistal.","C":"Subluxação da articulação interfalangiana proximal e reabsorção da articulação interfalangiana\ndistal.","D":"Reabsorção da articulação interfalangiana proximal e subluxação da articulação interfalangiana\ndistal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-182453","number":"182453","sourceNumber":"182453","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Com relação aos achados laboratoriais da artrite reumatoide, assinale a afirmativa\ncorreta:","options":{"A":"o fator reumatoide é um autoanticorpo dirigido contra a porção Fab de uma imunoglobulina M","B":"o anti-CCP é um anticorpo altamente sensível, porém pouco específico","C":"pacientes com síndrome de Felty têm leucocitose com eosinofilia","D":"o anti-CCP está associado a doença grave e erosiva"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-186519","number":"186519","sourceNumber":"186519","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 35 anos com artrite rematoide há 6 meses, com doses estáveis de\nprednisona 10mg/dia, metotrexato 25 mg/semana,\nácido fólico 10mg/semana, apresenta rigidez\nmatinal de 30 minutos e DAS 28 de 3,6. Qual das afirmativas está correta?","options":{"A":"Paciente com boa resposta articular, com doses terapêuticas adequadas, rigidez matinal mínima;\ndeverá retornar em 3 meses para reavaliação.","B":"Paciente com atividade moderada de doença, em uso de prednisona acima de 7,5mg/dia por\nmais de 3 meses; considerar resistência a DMARD inicial.","C":"Paciente com atividade moderada de doença; deverá aumentar prednisona para 15mg/dia,\nmanter a mesma dose do DMARD e retornar em 3\nmeses.","D":"Paciente com atividade leve de doença, com tratamento adequado; considerar infiltração\nintra-articular e anti-inflamatório não esteroide."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-178831","number":"178831","sourceNumber":"178831","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Segundo os critérios de Jones, qual das alternativas não é um critério menor para febre\nreumática?","options":{"A":"Artrite.","B":"Cardite.","C":"Coreia de Sydenham.","D":"Eritema multiforme.","E":"Nódulos subcutâneos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-186505","number":"186505","sourceNumber":"186505","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Escolar do sexo feminino iniciou com dores articulares em punhos, tornozelos e joelhos\nhá 15 dias, tendo procurado a emergência\nonde prescreveram ácido acetil-salicílico e solicitaram\nexames complementares. Mãe relata que as dores sumiram, mas há 02 dias surgiram diversos\ncaroços no corpo da menina. Exame físico: bom estado geral, afebril e corada. ACV: RR 2T BNF,\nsem sopros, FC: 90bpm; presença de nódulos indolores em topografia de proeminências ósseas e\ntendões. Exames laboratoriais: Hb: 12,2g/dl, leucócitos: 11.000/mm3 sem desvio para a esquerda,\nVHS: 60 mm/1ª hora e ASLO: 1.5350U Todd. Com base no quadro clínico descrito, o exame\ncomplementar que deve ser solicitado com urgência é:","options":{"A":"Ecocardiografia.","B":"Eletrocardiograma.","C":"Ultrassonografia dos nódulos.","D":"Fator antinuclear (FAN)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-158472","number":"158472","sourceNumber":"158472","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A gota é uma doença caracterizada pela deposição intra-articular de cristais. Nessa\ndoença:","options":{"A":"A colchicina é utilizada no tratamento para inibir a xantina-oxidase, bloqueando assim a síntese\nde ácido úrico.","B":"A fase crônica cursa com lesões líticas ósseas Peri articulares, visualizadas por métodos de\nimagem como saca bocado.","C":"Os cristais de ácido úrico, quando visualizados por microscópio de luz polarizada, apresentam\nbirrefringência fortemente positiva.","D":"Os agentes hipouricemiantes, tais como o alopurinol e o febuxostat, inibem a reabsorção de\nácido úrico nos túbulos renais proximais"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-157318","number":"157318","sourceNumber":"157318","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"De acordo com os critérios de Jones para febre reumática, é considerado critério\nmenor:","options":{"A":"Cardite.","B":"Eritema nodoso.","C":"Coreia.","D":"Nódulos subcutâneos.","E":"Artralgia."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-160467","number":"160467","sourceNumber":"160467","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Artrite reumatoide caracterizada por sinovite hipertrófica, destruição articular, ruptura\ntendinosa, compressão de nervos adjacentes e outros, é uma das doenças reumáticas crônicas\nmais dolorosas. Quando acomete a mão, apresenta como característica clínica ser:","options":{"A":"Bilateral.","B":"Assimétrica.","C":"Precoce nas articulações interfalângicas.","D":"Tardia nas articulações metacarpofalângicas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-156982","number":"156982","sourceNumber":"156982","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 60 anos, com quadro de poliartrite simétrica de mãos, pés e joelhos de\nrigidez pós-repouso maior que 1 hora e aumento do\nvolume das articulações das mãos há 2 meses.\nNo momento, a paciente apresenta tosse seca e dispneia. Sua radiografia de tórax revela nódulos\nmúltiplos pulmonares bilaterais e periféricos. Sobre o caso, qual achado é o mais provável para o\ndiagnóstico?","options":{"A":"Fator antinuclear positivo com padrão homogêneo.","B":"Anticorpo anticitoplasma de neutrófilos positivos.","C":"Fator reumatoide positivo em altos níveis.","D":"Teste tuberculínico fortemente positivo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-156989","number":"156989","sourceNumber":"156989","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na artrite reumatoide juvenil:","options":{"A":"Os achados laboratoriais confirmam o diagnóstico.","B":"Para o diagnóstico, é necessário que o paciente apresente febre com duração de no mínimo 6\nsemanas.","C":"O acometimento articular (poli ou oligoarticular) é concomitante às manifestações sistêmicas.","D":"Dentre as manifestações sistêmicas, pode-se citar a hepatomegalia ou esplenomegalia, a\nserosite e o exantema evanescente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-160473","number":"160473","sourceNumber":"160473","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 63 anos é atendida pelo médico de família, referindo que há\naproximadamente 9 meses tem apresentado dor\nprogressiva e deformidade nas mãos, punhos e\njoelhos. Nas últimas semanas, houve piora da artralgia, acompanhada de rigidez matinal\nimportante. Além disso, refere fadiga, astenia, e perda ponderal de 5 kg no último ano. Ao exame\nfísico, nota-se deformidade em ambas as mãos, com desvio radial do pulso e desvio ulnar dos\ndedos. A principal hipótese diagnóstica é:","options":{"A":"Osteoartrite.","B":"Síndrome CREST.","C":"Esclerodermia.","D":"Artrite reumatoide."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-150272","number":"150272","sourceNumber":"150272","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 57 anos, diagnosticada recentemente com artrite reumatoide (DAS 28 = 5,2),\niniciará tratamento com prednisona e metotrexato. Com o objetivo de reduzir os efeitos colaterais\ndo metotrexato, particularmente aftas orais, anemia e intolerância gástrica, deve-se orientar a essa\npaciente a administração simultânea de:","options":{"A":"Omeprazol, 20 mg/dia.","B":"Sulfametoxazol-trimetoprim, 80/400 mg, três vezes ao dia.","C":"Ácido fólico, 10 mg por semana.","D":"Vitamina D, 800 UI/dia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-150764","number":"150764","sourceNumber":"150764","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança diagnosticada com febre reumática aos cinco anos por lesão na válvula mitral e\naórtica, apresenta hoje ecocardiograma sem alterações. Recebe benzetacil há cinco anos. Nesse\ncaso, até quando essa criança deverá continuar com a profilaxia secundária?","options":{"A":"Até os 18 anos.","B":"Até os 21 anos.","C":"Até os 25 anos.","D":"Por toda a vida."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-150241","number":"150241","sourceNumber":"150241","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Pré-escolar de três anos apresenta, há seis meses, artrite envolvendo ambos os\njoelhos e tornozelo esquerdo, acompanhada\nde dificuldade para deambular especialmente pela\nmanhã. Ao exame, apresentava discreta flexão nos joelhos e grande aumento de volume dos\njoelhos e tornozelo esquerdo, sem outras alterações sistêmicas aparentes. De acordo com a\nhipótese diagnóstica, esta paciente poderá ter, também, lesão:","options":{"A":"Cardíaca.","B":"Ocular.","C":"Cerebral.","D":"Renal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-150761","number":"150761","sourceNumber":"150761","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na artrite idiopática juvenil, subtipo AIJ relacionada à entesite, é necessária a\npresença\nde artrite e entesite. Na ausência de uma\ndelas, a presença de quais critérios permite o\ndiagnóstico?","options":{"A":"HLA-B27 e idade maior que oito anos.","B":"HLA-B27 e dactilite.","C":"Idade maior que oito anos e história de espondilite\nanquilosante em parente de primeiro grau.","D":"Dor à compressão de sacroilíaca e história de espondilite anquilosante em parente de primeiro\ngrau."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-160545","number":"160545","sourceNumber":"160545","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança de 8 anos de idade apresenta quadro de febre moderada contínua, prostração\ne dor a deambulação no membro inferior\nesquerdo. No exame físico são observados sinais\nflogísticos no joelho esquerdo, com dor intensa à movimentação da articulação. A mãe do menor\nrefere que o quadro iniciou dois dias após ter passado todo o dia jogando futebol no clube.\n\nHemograma com presença de leucocitose, neutrofilia e presença de mielócitos e metamielócitos.\nVHS aumentado. Rx do joelho mostrando aumento de\npartes moles. A análise do líquido sinovial\nmostrou presença de 70.000 leucócitos com 85% de PMN, aumento de proteína, diminuição da\nglicose. Qual o melhor esquema terapêutico medicamentoso para este paciente?","options":{"A":"Oxacilina 200 mg/kg/dia.","B":"Ampicilina 200 mg/kg/dia.","C":"Ceftriaxona 100 mg/kg/dia.","D":"Cefepima 100 mg/kg/dia."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-138647","number":"138647","sourceNumber":"138647","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O agente etiológico mais frequentemente envolvido nos episódios de crises aplásicas\nde crianças com anemia falciforme é:","options":{"A":"Parvovírus B19.","B":"Citomegalovírus.","C":"Vírus Epstein-Barr.","D":"Streptococcus pneumoniae."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-137046","number":"137046","sourceNumber":"137046","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"De acordo com a Organização Mundial de Saúde (OMS), anemia é um problema de\nsaúde pública global, que afeta a capacidade\nlaborativa e a qualidade de vida de cerca de 2 bilhões\nde pessoas, sendo que a deficiência de ferro é responsável por 75% dos casos de anemia. O\nachado laboratorial esperado na anemia ferropriva é:","options":{"A":"Capacidade total de ligação do ferro à transferrina aumentada.","B":"Macrocitose.","C":"RDW diminuído.","D":"Índice de saturação da transferrina maior que 55%."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-127706","number":"127706","sourceNumber":"127706","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Quais são as duas situações clínicas mais frequentes na hemoglobinopatia SC em\nrelação à hemoglobinopatia SS homozigótica?","options":{"A":"Esplenomegalia e insuficiência cardíaca.","B":"Colelitíase e úlceras maleolares.","C":"Priapismo e osteomielite por Salmonella sp.","D":"Retinopatia e necrose de cabeça de fêmur."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-138197","number":"138197","sourceNumber":"138197","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Durante a reação transfusional secundária à contaminação bacteriana,","options":{"A":"ocorre hipertensão.","B":"há aumento de 2° C na temperatura corporal pré-transfusional.","C":"é o plasma o hemocomponente mais frequentemente contaminado.","D":"tem como fenômenos raros a dispneia e a taquicardia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-137047","number":"137047","sourceNumber":"137047","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A Púrpra Trombocitopênica Trombótica (PTT) é uma doença caracterizada pela\npresença de microangiopatia trombótica e foi\ndescrita pela primeira vez em 1924 por Eli\nMoschcowitz que, na ocasião, relatou um caso de uma menina de 16 anos com febre, anemia\ngrave que evoluíram com insuficiência cardíaca, acidente vascular cerebral, coma e morte em duas\nsemanas. Em relação à PTT sabe-se que:","options":{"A":"a presença de anemia hemolítica microangiopática associada à trombocitopenia é suficiente\npara iniciar o tratamento com plasmaférese\nterapêutica.","B":"os achados laboratoriais incluem anemia com diminuição de reticulócitos, aumento de bilirrubina\ndireta e presença de esquizócitos no sangue\nperiférico associada à trombocitopenia.","C":"para considerar o diagnóstico e iniciar o tratamento da PTT é necessária a pêntade clínica\nconstituída por anemia hemolítica\nmicroangiopática, trombocitopenia, manifestações neurológicas,\ndisfunção renal e febre.","D":"O tratamento mais indicado é o uso de corticosteroides."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-109199","number":"109199","sourceNumber":"109199","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 65 anos apresentando anemia microcítica e hipocrômica como único dado\nclínico, deve ser investigado quanto a:","options":{"A":"Distúrbio nutricional.","B":"Doença hemolítica.","C":"Alteração da hematopoiese.","D":"Neoplasia de cólon direito."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-109156","number":"109156","sourceNumber":"109156","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A técnica mais eficaz no diagnóstico laboratorial de anemia falciforme é:","options":{"A":"Eletroforese de proteínas.","B":"Teste do afoiçamento.","C":"Dosagem de imunoglobulinas.","D":"Eletroforese de hemoglobinas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-101170","number":"101170","sourceNumber":"101170","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A condrocalcinose está relacionada a condições clínicas como hipotireoidismo,\nhipomagnesemia, hipofosfatemia e\nhiperparatireoidismo, e manifesta-se como uma monoartrite\nsemelhante à gota. Que substância forma depósitos na articulação de um paciente com\ncondrocalcinose?","options":{"A":"Cristais de urato.","B":"Cristais de fosfato de cálcio.","C":"Cristais de pirofosfato de cálcio.","D":"Cristais de carbonato de cálcio."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-103658","number":"103658","sourceNumber":"103658","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Cálculos biliares na infância são incomuns, porém, podem ser observados em qual\nsituação?","options":{"A":"Anemia falciforme.","B":"Verminose crônica.","C":"Hepatite crônica autoimune.","D":"Fibrose cística."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-106719","number":"106719","sourceNumber":"106719","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação às anemias microcíticas, hipocrômicas, assinale a correta.","options":{"A":"A ferritina sérica estará obrigatoriamente diminuída nos casos de anemia ferropriva.","B":"A coloração pelo azul da Prússia em um esfregaço de medula óssea é o padrão-ouro para\ndiagnóstico das deficiências de ferro em concomitância com outras doenças que dificultem a\ninterpretação dos parâmetros séricos.","C":"As talassemias não estão incluídas nos diagnósticos diferenciais das anemias microcíticas.","D":"A anemia sideroblástica congênita caracteriza-se pelo excesso de incorporação de ferro, com\nmaior produção de hemoglobina."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-110235","number":"110235","sourceNumber":"110235","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"As anemias megaloblásticas constituem um grupo de doenças com alterações\nmorfológicas semelhantes da medula óssea e macrocitose e são decorrentes da carência de\nvitamina B12 e/ou ácido fólico. Uma causa de deficiência de ácido fólico é:","options":{"A":"Anemia perniciosa.","B":"Uso prolongado de antiácidos.","C":"Pancreatite crônica.","D":"Uso de metotrexate."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-103675","number":"103675","sourceNumber":"103675","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança de 8 anos, portadora de anemia falciforme, internada por crise álgica há 48\nhoras, inicia com quadro de dispneia e dor torácica. Quais os dados a seguir que auxiliariam o\ndiagnóstico de síndrome torácica aguda?","options":{"A":"Paciente vinha em uso de morfina contínua para alívio da dor.","B":"Saturação em torno de 90%.","C":"Realizou radiografia de tórax que evidenciou infiltrado.","D":"Todas as opções são corretas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-103727","number":"103727","sourceNumber":"103727","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Correlacione as colunas segundo à classificação fisiopatológica das anemias e, em\nseguida, marque a sequência CORRETA: 1. Falta de produção; 2. Alteração na maturação\neritroide e eritropoiese ineficaz; 3. Perdas hemorrágicas; 4. Excesso de destruição de eritrócitos.\n(\n\n) Agudas ou crônicas; ( ) Deficiência de ferro; ( ) Defeito na membrana do eritrócito; ( )\nAnemia aplásica congênita e adquirida.","options":{"A":"1, 2, 3 e 4.","B":"3, 2, 4 e 1.","C":"4, 3, 2 e 1.","D":"1, 4, 3 e 2."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-89975","number":"89975","sourceNumber":"89975","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"É um fator de risco para Anemia Perniciosa, exceto:","options":{"A":"Dieta vegetariana/vegana.","B":"Doença celíaca.","C":"Esôfago de Barrett.","D":"Gastrectomia.","E":"Gastrite atrófica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-85348","number":"85348","sourceNumber":"85348","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Os exames laboratoriais de uma criança de um ano de idade evidenciaram anemia\nmicrocítica, ferro sérico normal, ferritina sérica e saturação de transferrina diminuídas. A\nprincipal\nhipótese diagnóstica é:","options":{"A":"talassemia minor.","B":"talassemia major.","C":"anemia ferropriva.","D":"anemia de doença crônica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-86347","number":"86347","sourceNumber":"86347","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A presença de desidratação, palidez, extremidades frias, febre, prostração e dor\nabdominal associados à esplenomegalia em uma\ncriança ictérica, 04 anos de idade, e portadora de\nanemia falciforme, deve ter como principal diagnóstico:","options":{"A":"Crise aplástica.","B":"Febre tifoide.","C":"Salmonelose.","D":"Sequestro esplênico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-84404","number":"84404","sourceNumber":"84404","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Assinale o item abaixo que ocasiona Volume Corpuscular Médio (VCM) elevado\n(macrocitose) observado no hemograma.","options":{"A":"Leishmaniose visceral.","B":"Uso prolongado de Abatacepte.","C":"Deficiência de vitamina D3.","D":"Alcoolismo.","E":"Hipertireoidismo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-85395","number":"85395","sourceNumber":"85395","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo masculino, com 50 anos de idade, morador de uma comunidade\nvegetariana em Pirenópolis, chega com queixa de\nperda da propiocepção e sensibilidade vibratória,\nmarcha de base alargada e dificuldade para deambular, fraqueza muscular e hiper-reflexia.\n\nApresenta, também, glossite e queilose. Questionado sobre sua alimentação, confirma que é\nvegetariano exclusivo há dez anos. Exames: anemia com macrocitose (VCM: 120 pg), anisocitose,\nmacro-ovalócitos, leucopenia e neutrófilos com núcleos hipersegmentados. Vitamina B12: 200\npg/ml (valor de referência: 200 - 900 pg/ml). Como confirmar, laboratorialmente, a deficiência de\nvitamina B12?","options":{"A":"Teste de Schilling.","B":"Aferição do nível urinário dos metabólicos acidometilmalônico e homocisteína.","C":"Anticorpo anticélula parietal ou fator intrínseco.","D":"Teste para avaliar a má absorção intestinal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-83821","number":"83821","sourceNumber":"83821","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança que teve AVC secundário e anemia falciforme deve estar sendo tratada com:","options":{"A":"antiagregação plaquetária regular.","B":"anticoagulação regular.","C":"transfusões sanguíneas regulares.","D":"uso regular de vitamina K.","E":"uso regular de hidroxiureia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-85356","number":"85356","sourceNumber":"85356","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menino, 3 anos, negro, com história de doença falciforme, que iniciou-se com queixa de\nfebre e dor difusa no corpo, principalmente no terço proximal da perna esquerda. Feito diagnóstico\nde osteomielite hematogênica aguda, qual organismo é o agente mais comum dessa infecção?","options":{"A":"Pneumococos sp.","B":"Salmonella sp.","C":"E. coli.","D":"S. aureus."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-78140","number":"78140","sourceNumber":"78140","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma menina de três anos de idade, portadora de anemia falciforme, é trazida ao\npronto-socorro com história de dois dias de\nfadiga; palidez; erupção cutânea; febre de 38,2°C. O\nexame físico revelou: frequência cardíaca de 140 bpm; frequência respiratória de 24 irpm; pressão\narterial de 90 x 40 mmHg e oximetria de pulso de 99% em ar ambiente. Observada palidez\nconjuntival e palmar, sem icterícia; não havia nenhuma evidência de esplenomegalia. Havia uma\n\nerupção cutânea difusa rendilhada em seus braços, pernas e peito. Exames laboratoriais revelaram\nhemoglobina de 3,3 g/dl e contagem de reticulócitos inferior a 0,1%, contagem de glóbulos brancos\nde 17 x 103/µl e uma contagem de plaquetas de 250 x 103/µl. O agente etiológico mais provável é\no:","options":{"A":"Mycoplasma pneumoniae.","B":"Bocavírus.","C":"Adenovírus.","D":"Parvovírus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-63232","number":"63232","sourceNumber":"63232","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"As dosagens séricas da homocisteína e do ácido metilmalônico estão AUMENTADAS\nna deficiência da vitamina:","options":{"A":"E.","B":"D.","C":"B12.","D":"B1.","E":"A."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-64579","number":"64579","sourceNumber":"64579","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A anemia de doenças crônicas (ADC) é habitualmente leve ou moderada, e normocítica\nou microcítica. Sua etiologia é multifatorial,\nenvolvendo:","options":{"A":"baixos níveis de citocinas, como interleucinas 1 e 6.","B":"Hemólise intravascular.","C":"Hematopoese extramedular.","D":"Ferro sérico diminuído e quantidade aumentada de ferro de depósito.","E":"A diminuição da hepcidina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-64583","number":"64583","sourceNumber":"64583","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A anemia falciforme corresponde à homozigose para o gene ßs e:","options":{"A":"Raramente cursa com complicações clínicas.","B":"Representa a forma mais grave das síndromes falciformes.","C":"A hematúria é a anormalidade mais frequente nesta doença genética.","D":"Suas manisfestações clínicas iniciam-se no terceiro mês de vida quando diminui a expressão de\nhemoglobina fetal.","E":"Apresenta eletroforese de hemoglobina com predomínio de hemoglobina S, aumento da\nhemoglobina A2 e diminuição da hemoglobina fetal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-61822","number":"61822","sourceNumber":"61822","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Considera-se o mais forte preditor de deficiência em ferro em crianças uma baixa\nconcentração de:","options":{"A":"Ferro sérico.","B":"Hematócrito","C":"Hemoglobina do reticulócito","D":"Ferritina","E":"Transferrina"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-61826","number":"61826","sourceNumber":"61826","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Considera-se o agente infeccioso mais comum na Síndrome Torácica Aguda em\ncrianças portadoras de doença falciforme:","options":{"A":"Pneumococo","B":"H Influenza","C":"S aureus","D":"Salmonella","E":"Klebisiella"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-63231","number":"63231","sourceNumber":"63231","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Laura, 1 ano de idade, apresenta febre e dor nas mãos e pés. Ao exame físico, palidez\nde pele e mucosas, FC = 110 bpm; temperatura\n= 38,5°C, edema doloroso nas mãos e pés\nbilateralmente. Hemoglobina = 6,5 g/dl; contagem de leucócitos = 15.500/mm³ (55% linfócitos, 4%\nmonócitos, 8% bastonetes, 33% segmentados); plaquetas = 350.000/mm³. Reticulócitos = 18%. O\ndiagnóstico e a conduta adequada são, respectivamente:","options":{"A":"anemia falciforme/ iniciar antibioticoterapia, hidratação endovenosa e analgesia com morfina.","B":"anemia falciforme/ iniciar hidratação endovenosa e transfusão de concentrado de hemácias;\nevitar uso de morfina.","C":"anemia hemolítica autoimune/ iniciar antibioticoterapia, hidratação endovenosa e analgesia com\ndipirona endovenosa.","D":"artrite séptica/ iniciar antibioticoterapia e transfusão de concentrado de hemácias.","E":"osteomielite com septicemia/ iniciar antibioticoterapia e drenagem cirúrgica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-51031","number":"51031","sourceNumber":"51031","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Rebeca, uma garota de 17 anos, queixa-se de fadiga. Ela tem dificuldade em suportar\nas atividades diárias. Recentemente, passou a ter\npalpitações. O exame físico revela palidez\ncutaneomucosa. Hemograma revela hemácias microcíticas e hipocrômicas. Qual o diagnóstico\nmais provável de Rebeca?","options":{"A":"Deficiência de folato.","B":"Deficiência de vitamina B12.","C":"Esferocitose hereditária.","D":"Anemia falciforme.","E":"Anemia ferropriva."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-49012","number":"49012","sourceNumber":"49012","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 70 anos chega ao ambulatório queixando-se de astenia, sonolência,\npalpitações aos pequenos esforços e um\nepisódio de lipotimia. Além disso, refere alopecia e unhas\nquebradiças. Há seis meses vem apresentando alterações no hábito intestinal, ora obstipada, ora\ncom diarreia, algumas vezes com sangue nas fezes. No exame físico, foi observada palidez\ncutâneo-mucosa (+++/4+), queilite angular, glossite e unhas e cabelos quebradiços. O hemograma\ncom Hb-6,0, VCM-55, HCM-18, CHCM-25 e RDW-27; Leuc-9.300 e Plaq-720.000. Marque a\n\nalternativa correta quanto aos exames necessários para definição do diagnóstico desta paciente.","options":{"A":"Eletroforese de hemoglobinas e CEA.","B":"Perfil de ferro e colonoscopia.","C":"Dosagem sérica de vitamina B12, pesquisa de sangue oculto nas fezes e EPF.","D":"Dosagem sérica de ácido fólico, pesquisa de sangue oculto nas fezes e EPF.","E":"USG abdominal e dosagem sérica de vitamina B12."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-53635","number":"53635","sourceNumber":"53635","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Nas crianças portadoras de anemia falciforme, o agente etiológico mais comum nas\nformas graves de artrite séptica é:","options":{"A":"Streptococcus B hemolítico.","B":"Salmonella.","C":"Hemophilus influenzae","D":"Pseudomonas aeruginosa.","E":"Staphylococcus aureus."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-53632","number":"53632","sourceNumber":"53632","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Pedro, 18 meses de idade, portador de anemia falciforme, foi levado à emergência com\nquadro clínio súbito de palidez, irritabilidade, distensão e dor abdominal. Ao exame, encontra-se\nfebril (38°C), dispneico, hipocorado ++++/++++, ritmo cardíaco irregular, baço palpável a oito cm do\nrebordo costal esquerdo. PA: 60 / 40 mmHg. Hemograma: Hb = 5 g/dl; VCM = 83 fl; Leucócitos =\n\n18.000 / mm3. A PRINCIPAL hipótese diagnóstica é:","options":{"A":"crise de leucemização.","B":"crise álgica.","C":"sequestro esplênico.","D":"crise hiper-hemolítica.","E":"infarto esplênico."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-48278","number":"48278","sourceNumber":"48278","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A anemia falciforme é frequente em nosso meio e caracterizada por doença hemolítica\ncrônica e grave, resultante da destruição prematura dos eritrócitos. Relativamente a esta doença,\nindique a assertiva correta:","options":{"A":"A crise dolorosa deve ser tratada com transfusão sanguínea.","B":"Quando ocorre osteomielite, a salmonella é um agente etiológico importante a ser considerado.","C":"A dactilite ocorre por isquemia de partes moles de mãos e pés em geral em crianças menores de\ndois anos.","D":"A vacina contra pneumococo deve ser feita em crianças maiores de dois anos e confere ampla\nproteção contra esse agente.","E":"A crise de sequestro é mais comum após os cinco anos de idade."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-35651","number":"35651","sourceNumber":"35651","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A anemia falciforme é frequente em nosso meio e caracterizada por doença hemolítica\ncrônica e grave, resultante da destruição prematura dos eritrócitos. Relativamente a esta doença,\nindique a assertiva correta:","options":{"A":"A crise dolorosa deve ser tratada com a transfusão sanguínea.","B":"Quando ocorre osteomielite, a salmonella é um agente etiológico importante a ser considerado.","C":"A dactilite ocorre por isquemia de partes moles de mãos e pés em geral em crianças menores de\ndois anos.","D":"A vacina contra pneumococo deve ser feita em crianças maiores de dois anos e confere ampla\nproteção contra esse agente.","E":"A crise de sequestro é mais comum após cinco anos de idade."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-34039","number":"34039","sourceNumber":"34039","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em pacientes com anemia falciforme, a:","options":{"A":"asplenia funcional ocorre desde o nascimento, devendo a penicilina benzatina ser utilizada\njuntamente com as vacinas BCG e hepatite B, a cada três semanas, até os cinco anos de idade.","B":"hemoglobina S é resultado da troca de um par de bases (tiamina por adenina) na posição 6 do\ncódon do gene da ß-globina, o que codifica a\ntroca do ácido glutâmico por valina na posição 6 da\ncadeia ßs.","C":"capacidade de transporte de oxigênio está reduzida a 20% da apresentada por uma hemácia\nnormal, apesar das hemácias possuírem uma vida média de 120 dias.","D":"crise de sequestro esplênico é comum na faixa etária de 5 a 15 anos, coincidente com a maior\nincidência de infecção pelo Parvovírus B19, nessa faixa etária."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-22996","number":"22996","sourceNumber":"22996","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A hemoglobinúria paroxística noturna caracteriza-se:","options":{"A":"por ausência de clonalidade.","B":"por aumento da expressão de CD 55 e CD 59 em eritrócitos e granulócitos, na citrometria do\nfluxo.","C":"por ter diagnóstico excluído em caso de teste de Ham negativo.","D":"por hemólise intravascular, falência medular e eventos trombóticos"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-22999","number":"22999","sourceNumber":"22999","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um paciente portador de anemia falciforme é internado com febre, taquipneia, dor\ntorácica intensa e radiografia de tórax com infiltrado heterogêneo. Evolui, 24 horas depois, com\npiora do quadro clínico e hipoxemia severa. Qual o provável diagnóstico e qual a conduta mais\nadequada, nesse caso?","options":{"A":"Síndrome torácica aguda: suporte ventilatório.","B":"Pneumonia: antibioticoterapia ambulatorial.","C":"Insuficiência cardíaca congestiva: diurético endovenoso.","D":"Tromboembolismo pulmonar: iniciar anticoagulação com varfarina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-27201","number":"27201","sourceNumber":"27201","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Dentre as alternativas abaixo, qual representa fatores/grupos de risco para anemia\nferropriva:","options":{"A":"Recém-nascido prematuro e o recém-nascido grande para a idade gestacional.","B":"Baixo peso ao nascer e ingestão excessiva de leite de vaca.","C":"Refluxo gastroesofágico e fórmulas lácteas infantis.","D":"Leite de cabra e escolares.","E":"Icterícia fisiológica e doença hemorrágica do recém-nascido."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-8941","number":"8941","sourceNumber":"8941","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo feminino, 30 anos, apresenta dispneia aos grandes esforços, pressão\nsistólica de 90/60 mmHg, cianose de extremidade (+/4+), Hemoglobina de 8,5 g/dl e gasometria\ncom PaO2 de 60 mmHg, PaCO2 de 30 mmHg, pH de 7,35, saturação de oxigênio de 91% e\nbicarbonato normal. Conduta:","options":{"A":"Intubação mais O2","B":"Mascara de Venturi, pois ela oferece oxigênio de 60%","C":"Tratar anemia","D":"Cateter de O2 a 10 L/min"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-9330","number":"9330","sourceNumber":"9330","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Dentre as síndromes falciformes, a hemoglobinopatia SC tem um comportamento\nclínico mais brando do que a hemoglobinopatia\nSS. Duas situações clínicas são mais frequentes na\nhemoglobinopatia SC:","options":{"A":"esplenomegalia e AVCis","B":"colelitíase e úlceras maleolares","C":"priapismo e osteomelite por salmonella sp","D":"retinopatia e necrose de cabeça de fêmur"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-9308","number":"9308","sourceNumber":"9308","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na anemia falciforme:","options":{"A":"a maioria dos pacientes apresenta icterícia.","B":"o baço, no primeiro ano de vida, aumenta muito pouco.","C":"os pulmões são preservados.","D":"a cardiomegalia ocorre primeiro por hipertrofia do ventrículo esquerdo e, posteriormente, do\ndireito."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-273984","number":"273984","sourceNumber":"273984","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"São contraindicações ao uso dos inibidores do Fator de Necrose Tumoral (TNF) em\nportadores de artrite reumatoide:","options":{"A":"Hepatite B, infecções ativas e insuficiência cardíaca classe III.","B":"Tuberculose sem tratamento, bronquite crônica e nefropatia.","C":"Infecção por HIV, idoso, tireoidopatia.","D":"Idoso, infecções ativas e nefropatia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-176261","number":"176261","sourceNumber":"176261","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Poliartrite simétrica e cumulativa é mais provável com qual das moléstias abaixo?","options":{"A":"Artrite psoriásica.","B":"Gota.","C":"Febre reumática.","D":"Artrite reumatoide juvenil.","E":"Síndrome de Reiter."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-176274","number":"176274","sourceNumber":"176274","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é uma complicação não supurativa de uma infecção das vias aéreas\nsuperiores pelo estreptococo beta?hemolítico do grupo A (EBHA) de Lancefield. Sobre essa\ndoença reumática, assinale a alternativa CORRETA.","options":{"A":"Caracteriza-se por um processo inflamatório transitório que acomete as articulações, o coração,\na pele e os rins.","B":"No Brasil, a febre reumática é a terceira principal causa de cardiopatia crônica adquirida nos\nindivíduos menores de 20 anos de idade.","C":"Sua ocorrência é mais frequente antes dos 5 anos de idade.","D":"A artrite tem caráter migratório, fugaz e autolimitado, poliarticular, geralmente acomete grandes\narticulações (como joelhos, tornozelos, pulsos e cotovelos).","E":"A coreia é a manifestação mais frequente e ocorre de forma isolada mais em meninas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-155295","number":"155295","sourceNumber":"155295","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O achado de luxação atlantoaxial em paciente sem histórico de trauma sugere a\nhipótese de:","options":{"A":"Espondilite anquilosante.","B":"Lúpus eritematoso sistêmico.","C":"Artrite reumatoide.","D":"Síndrome de Marfan.","E":"Tuberculose de coluna vertebral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-155311","number":"155311","sourceNumber":"155311","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menor do sexo masculino, 6 anos de idade, iniciou quadro de febre há 2 dias, com dor\nem terço distal da coxa esquerda, com\nmal-estar e claudicação. Após a avaliação no setor da\nurgência, identificou-se o local doloroso na coxa esquerda. Solicitado hemograma, que evidenciou\nleucocitose e neutrofilia. Resolvido puncionar a região da metáfise do fêmur no local da dor, com\ncoleta e drenagem de secreção purulenta, enviada para exames, inclusive cultura do material. Qual\né o antimicrobiano MAIS ADEQUADO para esse caso?","options":{"A":"Ceftriaxona.","B":"Oxacilina.","C":"Vancomicina.","D":"Amicacina.","E":"Ciprofloxacina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-131879","number":"131879","sourceNumber":"131879","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"De acordo com o Protocolo Clínico e Diretrizes Terapêuticas (Portaria SAS/MS\n55/2010) para Doença Falciforme, serão\nincluídos nesse protocolo de tratamento os pacientes que\napresentarem pelo menos um dos seguintes critérios nos últimos 12 meses:","options":{"A":"Dois ou mais episódios de crises de dor, com necessidade de atendimento médico hospitalar.","B":"Idade superior a 5 anos.","C":"Concentração de hemoglobina <7g/dL (média de 3 valores fora do evento agudo).","D":"Hipoxemia crônica: saturação de oxigênio persistentemente menor que 92% medidas em duas\nvisitas clínicas consecutivas fora do evento agudo.","E":"Contagem de leucócitos maior ou igual a 30.000/mm³, na ausência de infecção."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-131901","number":"131901","sourceNumber":"131901","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"De acordo com o Protocolo Clínico e Diretrizes Terapêuticas - Portaria SAS/MS,\n1.247/2014, constitui-se em exame NÃO OBRIGATÓRIO\npara diagnóstico de Anemia Ferropriva?","options":{"A":"Hemograma com avaliação do esfregaço periférico.","B":"Ferritina.","C":"Ferro sérico.","D":"Contagem de plaquetas.","E":"Avaliação dos índices hematimétricos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-131885","number":"131885","sourceNumber":"131885","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menino de 2 anos de idade é trazido pela mãe ao pronto atendimento com quadro de\nfebre, prostração e dor nas articulações de início há dois dias. Ao exame físico, a criança\napresenta-se com choro intenso, pálido, taquipneico, taquicárdico, edema de mãos e punhos. A\nmãe relata que seu filho sempre teve anemia e já recebeu duas transfusões de sangue. Assim,\npode afirmar-se que:","options":{"A":"A informação da mãe não ajuda a definir o diagnóstico, portanto, deve ser ignorada.","B":"Deve-se pensar em esferocitose hereditária como principal hipótese diagnóstica.","C":"A doença falciforme deve ser considerada como provável hipótese diagnóstica.","D":"O quadro clínico não permite pensar em uma hipótese diagnóstica.","E":"A principal hipótese é a doença de Kawasaki."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-105715","number":"105715","sourceNumber":"105715","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Não é consequência da Anemia Ferropriva em crianças:","options":{"A":"Atraso no crescimento.","B":"Atraso do desenvolvimento neuro-psicomotor.","C":"Menor rendimento escolar e intelectual.","D":"Menor desempenho físico e trabalho.","E":"Atraso no desenvolvimento puberal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-80923","number":"80923","sourceNumber":"80923","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à anemia hemolítica, é CORRETO afirmar:","options":{"A":"O paciente apresenta hiperuricemia.","B":"Se a hemólise for intravascular, haverá hemoglobinúria e hemossiderinúria.","C":"A contagem de reticulócitos está normal.","D":"Os níveis de haptoglobina aumentam na tentativa de se ligar a toda hemoglobina liberada das\nhemácias.","E":"Desidrogenase láctica está aumentada somente quando a hemólise é induzida por exercício\nfísico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-80875","number":"80875","sourceNumber":"80875","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 66 anos, com queixa de cansaço progressivo. Exames mostram Hb: 8,7 g/dl;\nHtc: 26%; VCM: 123 fl; HCM: 30,4 pg; RDW 25%;\nplaquetas: 170.000/mm³; reticulócitos: 0,5%;\nbilirrubinas totais: 1,0 mg/dl; Ferro sérico: 86 mcg/dl; ferritina: 200 ng/ml; PCR: 3,0 mg/dl;\nvitamina\nB12: 240 pg/ml (Referência: 239-931 pg/ml); ácido metilmalônico: 350 nanomol/L (Referência:\n\n70-270 nanomol/L); homocisteína: 50 micromol/L (Referência:1-15 micromol/L). A principal causa\nda anemia da paciente é:","options":{"A":"Anemia ferropriva.","B":"Anemia de doença crônica.","C":"Anemia hemolítica.","D":"Talassemia.","E":"Deficiência de vitamina B12."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-80908","number":"80908","sourceNumber":"80908","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A asplenia funcional é um fenômeno que ocorre progressivamente na criança com\nanemia falciforme. São medidas corretas para diminuir a probabilidade de infecções graves,\npropostas pelo Ministério da Saúde, EXCETO:","options":{"A":"Profilaxia com penicilina benzatina ou V oral até os 10 anos de idade.","B":"Vacina polissacáride contra pneumococo: 1 dose após 2 anos de idade, reforço após 5 anos.","C":"Vacina antivaricela: dose única após 1 ano de idade.","D":"Vacina anti-hepatite A: uma dose após 1 ano de idade, reforço após 6 meses.","E":"Profilaxia com eritromicina em caso de alergia à penicilina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-62561","number":"62561","sourceNumber":"62561","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O ferro da dieta existe sob duas formas químicas: o ferro heme, que é encontrado na\nhemoglobina, mioglobina e nas enzimas (ferro em alimentos de origem animal) e o ferro não heme,\nque é encontrado, principalmente, em alimentos de origem vegetal. A absorção intestinal do ferro\nheme e não heme acontece por meio de processos diferentes no enterócito. A absorção de ferro é\ninfluenciada por diversos fatores, EXCETO:","options":{"A":"Pelas reações de oxidação e redução que são elementos altamente reativos que podem interagir\ncom o oxigênio e formar produtos\nintermediários os quais podem agir como radicais livres,\ndiminuindo a absorção.","B":"Pela dieta no caso do ferro não heme.","C":"Por um hormônio produzido no fígado chamado hepcidina, que atua inibindo a absorção de\nferro.","D":"Pela saturação de transferrina ou porcentagem de ferro ligado à transferrina que, se estiver\nbaixa, estimula a saída de ferro do enterócito para circulação pela membrana basolateral.","E":"Pela presença de fatores dietéticos estimuladores (ex.: Vitamina C) ou inibidores (ex.: Taninos)\nde sua absorção."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-47443","number":"47443","sourceNumber":"47443","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A manutenção de baço acessório ou implantes de fragmentos de tecidos esplênicos\nsão procedimentos cirúrgicos que devem ser considerados\nna remoção completa do baço.\n\nEntretanto, esses procedimentos podem contribuir para o insucesso terapêutico de qual das\ndoenças abaixo?","options":{"A":"Esferocitose hereditária.","B":"Talassemia maior.","C":"Anemia falciforme.","D":"Hipertensão porta.","E":"Deficiência de fator V."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-47466","number":"47466","sourceNumber":"47466","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um lactente saudável de 6 meses de idade chega ao consultório pediátrico para uma\nconsulta de rotina. Apresenta-se com o exame físico normal e crescimento e desenvolvimento\nadequados para a idade. Na investigação da história alimentar, o pediatra descobre que o lactente\nalimenta-se apenas com leite de cabra. Qual problema hematológico deve ser investigado?","options":{"A":"Anemia megaloblástica.","B":"Anemia ferropriva.","C":"Anemia hemolítica.","D":"Anemia falciforme.","E":"Anemia autoimune."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-35720","number":"35720","sourceNumber":"35720","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Cirurgião faria gastrectomia e preocupou-se com a deficiência de vitamina B12,\nprovocada pelas células produtoras de fator intrínseco de Castle. Quais seriam elas?","options":{"A":"Células oxínticas.","B":"Células zimogênicas.","C":"Células principais.","D":"Células D e parietais.","E":"Células enterocromafim."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-35749","number":"35749","sourceNumber":"35749","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na síndrome torácica aguda no paciente com anemia falciforme, deve-se avaliar a\nhipótese por Mycoplasma pneumoniae. Em caso de osteomielite no falcêmico, o agente etiológico\nque predomina, é:","options":{"A":"Staphylococcos áureos.","B":"Mycoplasma.","C":"Streptococcus viridams.","D":"Salmonella.","E":"Clamydia trachomatis."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-35771","number":"35771","sourceNumber":"35771","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Lactente de dois meses apresenta atraso do crescimento linear, manchas café com\nleite, hiperpigmentação cutânea e malformação esquelética, como ausência dos polegares.\n\nHemograma: pancitopenia. O diagnóstico provável é:","options":{"A":"Talassemia maior.","B":"Neurofibromatose.","C":"Anemia de Fanconi.","D":"Síndrome de Marfan.","E":"Disceratose congênita."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-35781","number":"35781","sourceNumber":"35781","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Escolar pálido com cefaleia persistente, dor torácica, dores ósseas generalizadas,\nereção peniana persistente e dolorosa ocorre em:","options":{"A":"Anemia carencial.","B":"Anemia hemolítica.","C":"Anemia aplástica.","D":"Anemia autoimune.","E":"Anemia megaloblástica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-28269","number":"28269","sourceNumber":"28269","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A tríade caracterizada por pancitopenia, macrocitose e presença de neutrófilos\nhipersegmentados no sangue periférico ocorre na:","options":{"A":"Síndrome de Blackfan-Diamond (anomalia congênita primária da stem cell)","B":"Deficiência de folato e/ou vitamina B12","C":"Síndrome HELLP","D":"Doença de Kasabach Merritt","E":"Hemoglobinopatia C"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-11486","number":"11486","sourceNumber":"11486","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menino, 10 anos, apresenta astenia, mau desempenho escolar, insônia há 03 meses.\nExame físico: mucosas hipocoradas RCR 2T, BNF, FC 106 bpm. Considerando a hipótese\ndiagnóstica, a alteração mais provável no hemograma é:","options":{"A":"microcitose com anisocitose.","B":"micrositose sem anisocitose.","C":"macrositose com anisocitose.","D":"normocitose com anisocitose.","E":"macrositose sem anisocitose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-11500","number":"11500","sourceNumber":"11500","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Crianças de 03 anos atendida no SPA com síndrome mão-pé, febre, dor abdominal,\npalidez e discreta icterícia. Dentre as doenças hematológicas qual seria sua primeira hipótese:","options":{"A":"Leucemia.","B":"Anemia megaloblástica.","C":"Anemia Falciforme.","D":"Hemofilia.","E":"Anemia Ferropriva."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-308638","number":"308638","sourceNumber":"308638","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Assinale a opção em que se encontra a associação CORRETA que compõe a síndrome\nde Caplan.","options":{"A":"Artrite reumatoide, esplenomegalia e neutropenia.","B":"Artrite reumatoide, nódulos pulmonares e pneumoconiose.","C":"Artralgia, xerostomia e tireoidopatia.","D":"Artrite, pericardite e pleurite.","E":"Artrite, mononeurite e mielopatia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-281498","number":"281498","sourceNumber":"281498","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem jovem procura serviço de emergência por dor de forte intensidade com\nlimitação funcional e sinais flogísticos no\njoelho direito. Febril (38 graus). Sem trauma. Nega\nepisódios anteriores. Restante do exame físico sem alterações. Considerando a principal hipótese\ndiagnóstica, qual a melhor conduta:","options":{"A":"Dosagem de ácido úrico e início de alopurinol","B":"Raio x joelho e início de anti-inflamatórios.","C":"Artrocentese e infiltração articular com corticoide.","D":"Artrocentese e início de antibióticos.","E":"Ressonância magnética de joelho e encaminhamento para ortopedista."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-278930","number":"278930","sourceNumber":"278930","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 42 anos com quadro de artrite aguda em 1ª articulação\nmetatarsofalangiana. A melhor opção terapêutica\nque pode ser utilizada na crise aguda e como\nprevenção de novas crises é:","options":{"A":"Probenecida.","B":"Alopurinol.","C":"Prednisona.","D":"Colchicina.","E":"Alopurinol associado à prednisona."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-218019","number":"218019","sourceNumber":"218019","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"No diagnóstico de febre reumática, utilizamos como critérios maiores de Jones exceto:","options":{"A":"Cardite.","B":"Artrite.","C":"Coreia.","D":"Nódulos subcutâneos.","E":"Elevação de VHS (? 60 mm na 1ª hora) e/ou PCR ? 3 mg/dl (ou > que valor de referência\nindicado)."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-203614","number":"203614","sourceNumber":"203614","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"No tratamento da febre reumática, o antibiótico de primeira linha para a erradicação do\nestreptococo beta-hemolítico (grupo A) da orofaringe é:","options":{"A":"Cefalexina.","B":"Amoxicilina + clavulanato.","C":"Eritromicina.","D":"Azitromicina.","E":"Penicilina benzatina."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-203264","number":"203264","sourceNumber":"203264","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre o tratamento de Artrite Séptica em pediatria, selecione o antimicrobiano de\nprimeira escolha recomendado para o tratamento de um lactente de oito meses de idade, com\ndiagnóstico de Artrite Séptica.","options":{"A":"Vancomicina","B":"Oxacilina","C":"Amicacina","D":"Ceftriaxona","E":"Ciprofloxacina"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-177505","number":"177505","sourceNumber":"177505","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança de 9 meses de idade foi diagnosticada com artrite séptica, sendo realizada\ndrenagem e coleta do material para\ncultura. Qual esquema empírico deve ser iniciado, baseado na\netiologia mais comum nesta faixa etária?","options":{"A":"Ampicilina e Gentamicina","B":"Ceftriaxona","C":"Oxacilina","D":"Ampicilina e Amicacina","E":"Vancomicina"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-108058","number":"108058","sourceNumber":"108058","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre a investigação das anemias, é INCORRETO:","options":{"A":"Dacriócitos podem ser visualizados no sangue periférico de pacientes com mielofibrose.","B":"Se o volume corpuscular médio estiver superior a 100 fl, o diagnóstico é de anemia\nmegaloblástica.","C":"Na anemia ferropriva, a capacidade total de ligação de ferro estará elevada.","D":"Os níveis de haptoglobina se reduzem na anemia hemolítica.","E":"A síndrome mielodisplásica promove anemia hipoproliferativa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-87507","number":"87507","sourceNumber":"87507","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Avaliando a hematoscopia de sangue periférico e o EAS de um paciente, internado com\nanemia e icterícia a esclarecer, observou-se a presença de esquizócitos na circulação periférica,\nalém de hemoglobinúria. Qual das etiologias abaixo é mais condizente com a associação destes\ndois achados?","options":{"A":"Síndrome hemolítico-urêmica;","B":"Anemia falciforme;","C":"Hiperesplenismo;","D":"Hemoglobinúria paroxística noturna;","E":"Deficiência de G6PD."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-89552","number":"89552","sourceNumber":"89552","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em um atendimento de uma criança de 9 anos com anemia falciforme, com queixa de\nfebre (39°C), prostração e taquicardia, o hemograma revelou leucocitose de 20.000 células/mm³ e\nhemoglobina de 8 g/dl. rx de tórax com infiltrado pulmonar difuso bilateral. A mãe traz consigo\nhemograma realizado na última consulta de rotina com hemoglobina de 8,5 g/dl e leucócitos de\n\n18.000 células/mm³. Todas as alternativas são importantes para justificar internação, exceto:","options":{"A":"Rx de tórax alterado","B":"Febre > 38°C","C":"Alterações do hemograma","D":"Prostração e taquicardia","E":"N.d.a."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52490","number":"52490","sourceNumber":"52490","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à anemia e gestação todas as respostas estão corretas, exceto uma:","options":{"A":"a expansão da massa eritrocitária materna constitui a principal demanda de ferro na gestação.","B":"a Organização Mundial da Saúde (OMS) estabelece o limite de 11 g/dl para a concentração de\nhemoglobina, abaixo do qual se define anemia na gestação para qualquer período gestacional.","C":"o RDW, que avalia a variação do tamanho das hemáceas, pode ser útil para a definição da\nanemia ferropriva, quando superior a 16%.","D":"o receptor de transferrina geralmente não é afetado pela gestação.","E":"as gestantes devem fazer suplementação de ferro elementar, associados a outros\nmicronutrientes,\n\ncomo ácido fólico, vitamina C ou vitamina A, independente dos níveis de hemoglobina."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52450","number":"52450","sourceNumber":"52450","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à anemia ferropriva assinale a alternativa INCORRETA:","options":{"A":"A ingestão de grandes volumes de leite de vaca cru está relacionada a sangramento intestinal\ncrônico e anemia ferropriva.","B":"No tratamento dietético da anemia ferropriva deve-se evitar a clara de ovo pois esta diminui a\nbiodisponibilidade de ferro.","C":"Em lactentes de cor parda e desnutrido, um dado sugestivo de anemia ferropriva nos exames\nlaboratoriais é o desvio para direita dos neutrófilos e a presença de neutrófilos\nplurissegmentados.","D":"A ferritina sérica é um dado que fornece uma estimativa das reservas corporais de ferro.","E":"O tratamento ideal de uma criança com anemia ferropriva é a reposição oral de ferro em doses\nafastadas das refeições."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52187","number":"52187","sourceNumber":"52187","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à anemia por deficiência de ferro, assinale a alternativa INCORRETA:","options":{"A":"A anemia por deficiência de ferro (ADF) constiui-se em carência nutricional relevante por suas\nrepercussões para o desenvolvimento infantil e magnitude de sua prevalência na atualidade.","B":"A maior vulnerabilidade das crianças menores de dois anos deve-se à necessidade de ferro para\no crescimento e à insuficiente ingestão desse\nnutriente, em quantidade e biodisponibilidade, na\ndieta habitual nessa faixa etária.","C":"Organizações internacionais apontam três estratégias para prevenção da anemia por deficiência\nde ferro: educação nutricional, fortificação de\nalimentos e suplementação com ferro.","D":"No Brasil, estima-se que não há anemia por deficiência de ferro nas crianças com idade entre\nseis e 24 meses de idade.","E":"O Brasil tornou obrigatória a fortificação das farinhas de trigo e milho com ferro e ácido\nfólico a\npartir de 2004 e implantou a suplementação preventiva com sulfato ferroso (SF) para grupos\nvulneráveis a partir de 2005."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-346618","number":"346618","sourceNumber":"346618","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Marque a opção abaixo que é MAIS COMPATÍVEL com a tríade composta por:\ntenossinovite, lesões de pele vesiculopustulares e poliartralgia sem artrite purulenta:","options":{"A":"Doença de Lyme","B":"Infecção gonocócica disseminada","C":"Infecção por Mycobacterium tuberculosis","D":"Infecção por Staphylococcus aureus"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-330840","number":"330840","sourceNumber":"330840","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre artrite reumatoide, assinale a afirmativa INCORRETA.","options":{"A":"Pode ocorrer acometimento pulmonar (pneumopatia intersticial).","B":"A rigidez matinal geralmente melhora com a atividade.","C":"Provas inflamatórias (PCR, VHS) frequentemente estão elevadas.","D":"Tem acometimento frequente das articulações interfalangianas distais."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-348470","number":"348470","sourceNumber":"348470","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 45 anos, chegou ao pronto-socorro trazida pelo SAMU em parada\ncardiorrespiratória. Realizado RCP sem sucesso,\nsendo constatado o óbito. Foi encaminhada à\nnecropsia para investigação da causa do óbito. O exame macroscópico do coração evidenciou\nestenose de valva mitral com fusão das comissuras e dilatação de átrio esquerdo. À microscopia do\nmiocárdio, foram visualizados nódulos de Aschoff nas fibras musculares cardíacas. Qual achado\nsemiológico poderia ser encontrado nessa paciente antes do seu óbito?","options":{"A":"Murmúrio de Carey-Coombs","B":"Sopro de Austin-Flint","C":"Fenômeno de Gallavardin","D":"Sopro circular de Miguel Couto"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-327335","number":"327335","sourceNumber":"327335","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher, 60 anos, em acompanhamento há 15 anos de artrite reumatoide, apresentando\ndeformidades em mãos, retorna ao ambulatório com raio X de mãos e punhos com as seguintes\nalterações radiológicas: hiperextensão das articulações interfalangeanas proximais e flexão das\narticulações interfalangeanas distais. Esses achados correspondem à deformidade em","options":{"A":"dedos em fuso.","B":"dedos em botoeira.","C":"pescoço de cisne.","D":"dedos em martelo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-267291","number":"267291","sourceNumber":"267291","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação aos perfis clínicos de doenças reumáticas, assinale a afirmativa\nINCORRETA.","options":{"A":"Na osteoartrite, a dor é de início gradativo, a rigidez após o repouso é de curta duração, o\nenvolvimento articular é assimétrico e não há queixa sistêmica.","B":"Na artrite reumatoide, o início pode ser agudo, mas usualmente é insidioso, a rigidez matinal é\nprolongada, o envolvimento articular é aditivo e simétrico, o pico de incidência é na quinta década\ne\no envolvimento sistêmico e visceral é frequente.","C":"Nas artrites microcristalinas, o início é agudo, a rigidez é de curta duração, o envolvimento\nusualmente é monoarticular, principalmente em\nmembros inferiores e pode haver febre e adinamia.","D":"Nas artrites infecciosas bacterianas, o início é agudo, há impotência funcional articular,\nusualmente monoarticular."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-267292","number":"267292","sourceNumber":"267292","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre os exames laboratoriais em reumatologia, assinale a afirmativa INCORRETA.","options":{"A":"A ferritina não é usada rotineiramente como reagente de fase aguda. Sua dosagem tem\ninteresse especial na artrite idiopática juvenil do subtipo sistêmico e na síndrome de ativação\nmacrofágica, situações nas quais os níveis costumam ser > 1.000 ng/ml.","B":"A Velocidade de Hemossedimentação (VHS), uma das medidas de inflamação mais usadas na\nprática clínica, apresenta alta sensibilidade e baixa especificidade para o processo inflamatório.\nEla\npode ser alterada por vários fatores, como: idade, microcitose, esferocitose, policitemia, anemia,\nentre outros.","C":"A Proteína C-Reativa (PCR) é o melhor teste de fase aguda na maioria das doenças, pois seus\nníveis refletem o grau de inflamação e caem rapidamente com a melhora da reação. É sintetizada\npelos hepatócitos, em resposta às citocinas pró-inflamatórias.","D":"O Fator Reumatoide (FR) está positivo em cerca de 70-80% dos pacientes com Artrite\nReumatoide (AR), sendo de utilidade apenas no diagnóstico e não no prognóstico da AR."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-267293","number":"267293","sourceNumber":"267293","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre a gota, marque a assertiva CORRETA.","options":{"A":"A homeostase sérica do ácido úrico depende basicamente dos rins. Por ser uma molécula\npequena, ele é totalmente filtrado, sendo 90% reabsorvido no túbulo proximal por meio de\ntransportadores ácidos orgânicos. O mais importante deles é o urati, que pode ser inibido por\nmedicamentos como a losartana potássica e a probenecida.","B":"Apresenta prevalência em torno de 8% e predomínio masculino na proporção de 5:1.","C":"A gota é uma artropatia microcristalina com inexorável evolução para insuficiência renal crônica,\nse não tratada adequadamente. É a forma de\ndoença articular inflamatória mais comum.","D":"Evidências clínicas indicam que indivíduos com a condição denominada hiperuricemia\nassintomática, mesmo que persistente e sem\ndesenvolver gota, não apresentam maior risco para\nhipertensão arterial e doença arterial coronariana."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-288170","number":"288170","sourceNumber":"288170","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 5 anos e sete meses, sexo feminino, branca, natural e procedente de\nVárzea Grande (MT), foi encaminhada para o\nambulatório de reumatologia pediátrica com história\nde artralgia e edema articular no joelho e tornozelo direitos com limitação de movimentos há 6\nmeses. Nega febre. Antecedentes familiares apenas diabetes e hipertensão arterial. Ao exame:\nREG, corada, hidratada, eupneica, acianótica, anictérica, afebril, consciente. AR: MV fisiológico,\nsimétrico, sem RA. ACV: RCR, 2T, sem sopros. Abdômen sem visceromegalias. Osteoarticular:\npresença de edema articular e artralgia nas articulações de joelho e tornozelo direitos. Pele sem\nlesões. Foi solicitada a avaliação oftalmológica e constatada uveíte crônica. Também solicitados e\nrealizados os exames seguintes: hemograma, bioquímica e eletrólitos foram normais. Fator\nReumatoide (FR) não reagente; Velocidade de Hemossedimentação (VHS) de 45 mm/h; Proteína\nC-Reativa (PCR) de 25 mg/dl, Fator Antinuclear (FAN) reagente com padrão homogêneo e\nanticorpos anti-DNA de cadeia dupla (dsDNA), anti-Sm, anti-Ro, anti-La, e anti-RNP, não\nreagentes. Após afastar outras causas, foi estabelecida a hipótese diagnóstica de Artrite Idiopática\nJuvenil (AIJ). Qual o tipo de AIJ segundo a ILAR (International League of Associations for\nRheumatology)?","options":{"A":"Poliarticular fator reumatoide negativo.","B":"Oligoarticular.","C":"Sistêmica.","D":"Artrite psoriásica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-267338","number":"267338","sourceNumber":"267338","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Adolescente, sexo feminino, há 10 dias apresentou artrite em joelho direito com\nduração de 3 dias e, após, em joelho\nesquerdo com duração de 5 dias. No momento da consulta,\napresentava artrite no tornozelo direito há 2 dias. Relata ainda febre não aferida no início do\nquadro. História de dor de garganta há 1 mês, sem uso de medicações. Nega trauma e viagem\nrecentes. Ao exame físico, bom estado geral, corada, afebril, eupneica. Ausculta cardiovascular:\nsopro holossistólico, mais audível em foco mitral. Frequência cardíaca: 72 bpm. Artrite em tornozelo\ndireito, com dificuldade de deambulação. Sem lesões de pele. Exames laboratoriais: hemograma\nsem alterações, VHS 90 mm/h (até 10 mm/h), proteína C reativa: 10 mg/dL (inferior a 0,3 mg/dL) e\nantiestreptolisina O 800 UI/mL (inferior a 200 UI/mL). A hipótese diagnóstica para o caso e a\nprincipal complicação são:","options":{"A":"Artrite Idiopática Juvenil; Uveíte.","B":"Artrite séptica; Osteomielite.","C":"Síndrome de Marfan; Dissecção de aorta.","D":"Febre Reumática; Cardite Reumática."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-247714","number":"247714","sourceNumber":"247714","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina de 9 anos de idade apresentando, há 10 dias, artrite do tipo migratória em\ngrandes articulações. Há relato de febre\nepisódica e de amigdalite purulenta duas semanas antes\ndo início do quadro articular. A criança foi avaliada pelo pediatra que, durante o exame clínico,\nconstatou a presença de um sopro holossistólico em foco mitral, irradiando para a axila. Foram\nsolicitados alguns exames: ecocardiograma (relato verbal) ? problema importante em valva mitral;\ncultura de orofaringe positiva para Estreptococo beta-hemolítico do grupo A (EBHGA); níveis de\nanticorpos antiestreptolisina O (ASLO) aumentados. Com base no exposto e nos critérios de Jones\nmodificados para o diagnóstico de febre reumática, é CORRETO afirmar:","options":{"A":"O caso descrito é de alta probabilidade diagnóstica de febre reumática, pois apresenta um sinal\nmaior e dois sinais menores, além da comprovação de infecção prévia por EBHGA.","B":"O caso descrito é de alta probabilidade diagnóstica de febre reumática, pois apresenta dois\nsinais maiores além da comprovação de infecção prévia por EBHGA.","C":"O caso descrito é de baixa probabilidade diagnóstica de febre reumática, pois não apresenta o\nmais importante sinal: coreia independente da comprovação de infecção prévia por EBHGA.","D":"O caso descrito é de baixa probabilidade diagnóstica de febre reumática, pois apresenta apenas\num sinal maior e um sinal menor independente\nda comprovação de infecção prévia por EBHGA."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-214592","number":"214592","sourceNumber":"214592","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente com diagnóstico de artrite reumatoide, com poliartrite envolvendo mãos,\ncarpos, cotovelos, joelhos e tarsos, PCR elevado,\nfator reumatoide em altos títulos, nódulos\nsubcutâneos e queixas sistêmicas (adinamia, hiporexia e febre baixa). Sobre o caso, assinale a\nafirmativa CORRETA.","options":{"A":"O tratamento inicial deve ser feito com a escolha de uma droga modificadora da evolução da\ndoença (DMARD), a exemplo da leflunomida,\nassociada a Anti-Inflamatórios Não Esteroidais (AINE)\ne prednisona em doses baixas.","B":"O tratamento deve ser prontamente iniciado com Anti-Inflamatórios Não Esteroidais (AINE)\nassociados à pulsoterapia com metilprednisolona.","C":"Os dados apresentados indicam se tratar de uma artrite reumatoide agressiva, com prognóstico\nruim. Deve ser prontamente iniciado, portanto,\ntratamento com imunobiológicos.","D":"O tratamento inicial deve ser feito com a escolha de uma droga modificadora da evolução da\ndoença (DMARD), a exemplo do metotrexato nas\ndoses de 25 a 50 mg/semana, associada a\nAnti-Inflamatórios Não Esteroidais (AINE) e prednisona em doses baixas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-208577","number":"208577","sourceNumber":"208577","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina, 3 anos de idade, apresenta artrite em joelho direito há 5 meses e em tornozelo\nesquerdo há 3 meses. Os exames laboratoriais mostram alteração das provas de atividade\ninflamatória (velocidade de hemossedimentação, proteína C reativa) e fator antinúcleo positivo.\n\nQual o comprometimento oftalmológico esperado?","options":{"A":"retinite aguda","B":"episclerite crônica","C":"conjuntivite aguda","D":"atrofia nervo óptico","E":"uveíte anterior crônica"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-185220","number":"185220","sourceNumber":"185220","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente com 40 anos, procura atendimento na UBS referindo que há quatro meses,\nvem apresentando artrite simétrica de articulações\ndo punho, interfalangeanas proximais e\nmetacarpofalangeanas, além de rigidez articular matinal com duração de pelo menos uma hora.\nAvaliação laboratorial revelou fator reumatoide positivo. Qual dos tratamentos a seguir não modifica\no curso desta doença?","options":{"A":"Prednisona","B":"Sulfassalazina","C":"Metotrexato","D":"Ciclosporina","E":"Nenhuma das alternativas anteriores está correta"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-181592","number":"181592","sourceNumber":"181592","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na consulta de um portador de Gota, sem crise atual, os exames a serem solicitados na\nprimeira avaliação têm as seguintes finalidades: confirmar diagnóstico, classificação, avaliação da\nseveridade da doença, pesquisa de morbidades associadas e definição do plano terapêutico.\n\nNesse sentido, marque a alternativa que melhor representa a propedêutica inicial para a situação\nacima descrita.","options":{"A":"Hemograma, ácido úrico, glicemia de jejum, ureia, creatinina, TGO, TGP, perfil lipídico,\nUltrassom dos rins e vias urinárias, uricosúria de 24 horas e Rx articular (das afetadas).","B":"Hemograma, ácido úrico, glicemia de jejum, hemoglobina glicada, clearance de creatinina, TGO,\nTGP, fosfatase alcalina, perfil lipídico, Ultrassom de abdome total e Rx articular (das afetadas).","C":"Hemograma, ácido úrico, glicemia de jejum, ureia, creatinina, TGO, TGP, perfil lipídico,\nUltrassom dos rins e vias urinárias, proteinúria e uricosúria de 24 horas, Fator Reumatoide e\nRessonância Magnética articular (das afetadas).","D":"Hemograma, ácido úrico, glicemia de jejum, ureia, creatinina, TGO, TGP, perfil lipídico, Rx de\nabdome e Raio X articular (das afetadas)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-181607","number":"181607","sourceNumber":"181607","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à febre reumática, assinale a afirmativa INCORRETA.","options":{"A":"É uma doença inflamatória do tecido conectivo que se desenvolve após o contato do hospedeiro\ncom o estreptococo beta-hemolítico do grupo\nA.","B":"Títulos normais de ASLO excluem o diagnóstico de febre reumática e coreia de Sydenham.","C":"Cardite, poliartrite, coreia de Sydenham, eritema marginado e nódulos subcutâneos são sinais\nmaiores da doença.","D":"A regurgitação mitral é a manifestação mais frequente da cardite aguda, sendo a estenose mitral\nsugestiva de doença crônica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-181562","number":"181562","sourceNumber":"181562","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Quais alterações clínicas NÃO fazem parte do quadro clínico de crianças com artrite\nreumatoide juvenil?","options":{"A":"Artrite cumulativa; febre; anemia.","B":"Pericardite; uveíte; linfonodomegalias.","C":"Alopecia; eritema malar; monoartrite infecciosa.","D":"Exantema maculopapular que acompanha os picos febris; hepatoesplenomegalia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-167796","number":"167796","sourceNumber":"167796","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 30 anos, queixando-se de ardência uretal, olhos vermelhos com ardência e\nlacrimejamento e sinais de poliartrite. Qual o diagnóstico clínico?","options":{"A":"Síndrome de Sjogreen","B":"Espondilite anquilosante","C":"Síndrome de Reiter","D":"Gonococcia"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-158084","number":"158084","sourceNumber":"158084","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre gota, assinale a afirmativa INCORRETA:","options":{"A":"Estudos recentes implicam a hiperuricemia como fator de risco para doença coronariana,\ndevendo ser devidamente corrigida em pacientes\nde risco.","B":"Nos pacientes hipertensos, losartana potássico pode ser uma boa opção e o uso de diuréticos\ndeve ser evitado.","C":"Na avaliação inicial, são importantes os seguintes exames: hemograma, uricemia, uricosúria de\n24 horas, TGO, TGP, creatinina e\nultrassonografia dos rins e vias urinárias.","D":"O alopurinol, que atua aumentando a excreção urinária de ácido úrico, ocupa lugar de destaque\nno tratamento da gota."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-158101","number":"158101","sourceNumber":"158101","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo feminino, 42 anos, referindo que há cerca de 9 meses vem\napresentando dor e edema em articulações das\nmãos, punhos, joelhos, tornozelos e pés, com piora\nprogressiva. Apresenta ainda discreta adinamia e sensação de febre. Ao exame clínico, os dados\nrelevantes são: artrite de metacarpo nas falangeanas, interfalangeanas proximais, joelhos e\ntornozelos. Os exames laboratoriais mostraram FAN não reagente, fator reumatoide reagente =\n512, VHS = 50 e PCR = 24. Sobre o caso, assinale a afirmativa CORRETA:","options":{"A":"O diagnóstico é de AR definida, a doença está ativa e apenas com os dados informados não é\npossível calcular o DAS 28 (Disease Activity Score).","B":"Estão presentes critérios diagnósticos suficientes para concluir o diagnóstico de artrite\nreumatoide (AR) e o tratamento inicial deve incluir o uso de um imunobiológico.","C":"Não estão presentes critérios diagnósticos suficientes para concluir o diagnóstico de artrite\nreumatoide (AR), e o tratamento inicial deve incluir o uso de um imunobiológico.","D":"O diagnóstico é de AR provável, a doença está ativa e o tratamento deve excluir, por enquanto,\no uso de metotrexato."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-156429","number":"156429","sourceNumber":"156429","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Com relação à artrite crônica juvenil, marque a alternativa que apresenta a\nmanifestação extra-articular mais frequente:","options":{"A":"Febre intermitente.","B":"Pleurite.","C":"Linfoadenomegalias.","D":"Uveíte anterior."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-156447","number":"156447","sourceNumber":"156447","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina de 6 anos de idade com diagnóstico de artrite reumatóide juvenil, evolui com\niridociclite de difícil controle e cegueira. Dentre as formas clínicas da doença, marque a mais\nrelacionada com a evolução descrita:","options":{"A":"Poliartrite com FAN positivo e Fator Reumatoide negativo.","B":"Oligoartrite tipo I.","C":"Oligoartrite tipo II.","D":"Poliartrite com FAN negativo e fator reumatoide positivo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-156500","number":"156500","sourceNumber":"156500","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 50 anos acorda com dor intensa em região do hálux direito, acompanhada\nde calor local, vermelhidão e edema. Chega ao\npronto-socorro sem conseguir deambular. Refere\nuso anterior de AINEs (anti-inflamatórios não-esteróides) e de analgésicos em virtude de crises\nsemelhantes, incluindo outras articulações. O ácido úrico era de 11mg%, o hemograma estava\nnormal e a creatinina era de 0,9mg/dL. Nesse caso, a primeira hipótese clínica e a abordagem\nterapêutica adequada são, respectivamente:","options":{"A":"Crise aguda de gota ? iniciar AINE e colchicina","B":"Gota com infecção secundária ? iniciar antibiótico, AINE e colchicina","C":"Crise aguda de gota ? iniciar AINE e alopurinol","D":"Gota com infecção secundária ? iniciar antibiótico, alopurinol e AINE"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-109233","number":"109233","sourceNumber":"109233","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo feminino, de 40 anos, sem nenhuma patologia de base, realiza um\nhemograma para uma consulta de rotina e o resultado é o seguinte: Hb 11, Ht 30, Leucócitos 2.500\n( não foi liberado o diferencial) e plaquetas 128.000. Os termos adequados para as alterações\nlaboratoriais apresentadas por essa paciente são:","options":{"A":"Anemia, leucopenia e plaquetose.","B":"Poliglobulia, leucopenia e plaquetose.","C":"Poliglobulia, leucopenia e plaquetopenia.","D":"Anemia, leucopenia e plaquetopenia."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-108105","number":"108105","sourceNumber":"108105","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Y.D.L., sexo feminino, 34 anos, internada na enfermaria do hospital com história de\nletargia de início nas últimas duas\nsemanas. Ao exame, descorada +++/4; PA = 85 x 35 mmHg; Hb\n\n= 7,1 mg/dl; VCM = 101 fl; plaquetas = 430.000/mm³; reticulócitos de 29%. Mantendo a estratégia\ndiagnóstica, marque o exame necessário para comprovar a possível causa:","options":{"A":"Dosagem de transferrina.","B":"Cobalamina sérica.","C":"Coombs direto.","D":"Ureia e creatinina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-109237","number":"109237","sourceNumber":"109237","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Pré-escolar de quatro anos de idade apresenta quadro de anemia importante. Na\nanamnese, não há nada significativo na sua\nhistória pré-natal, todavia na primeira semana de vida\nteve icterícia que resolveu com fototerapia. Na investigação da icterícia, foram afastadas:\nincompatibilidade ABO, Rh e deficiência de G6PD. O teste do pezinho (fase III) foi normal.\n\nAntecedentes familiares: seus pais são do norte da Europa, o pai foi esplenectomizado aos oito\nanos de idade e a mãe submetida à\ncolecistectomia quando era adolescente. Ao exame físico,o\nlactente apresenta-se em estado regular, pálido, anictérico e baço palpável a 4 cm do rebordo\ncostal esquerdo, de consistência parenquimatosa. Qual tipo de anemia é mais provável para essa\ncriança?","options":{"A":"Anemia falciforme.","B":"Anemia de Fanconi.","C":"Anemia de Cooley.","D":"Anemia ou Doença de Minkowsky-Chauffard."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-109256","number":"109256","sourceNumber":"109256","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre a Doença Falciforme, marque V para as afirmativas verdadeiras e F para as\nfalsas. ( ) É uma anemia hemolítica\nhereditária autossômica dominante. ( ) São hemoglobinopatias\nnas quais pelo menos uma das hemoglobinas alteradas é a Hb S. ( ) O portador assintomático,\nportador do traço de Hb S ou heterozigoto para Hb S, não é anêmico e não é considerado doente. (\n\n) As doenças falciformes mais frequentes são a anemia falciforme (Hb SS), a S/betatalassemia e as\nduplas heterozigozes Hb SC e Hb SD. ( ) O diagnóstico precoce pode ser feito por meio da triagem\nneonatal para Hb S pelo teste do pezinho. Assinale a sequência correta.","options":{"A":"F, V, F, F, F.","B":"V, V, V, V, V.","C":"F, V, V, V, V.","D":"V, F, F, V, V."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-85038","number":"85038","sourceNumber":"85038","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um lactente de 45 dias é trazido a uma Unidade Básica de Saúde por sua mãe. Ela\nestá ansiosa com o resultado do teste do\npezinho. O resultado foi entregue por uma atendente e\nnão foi explicado se havia anormalidades. Os resultados são os seguintes: Fenilalanina: 2,4 mg/dl\n(normal até 3,0 mg/dl); TSH: 1,44 ?U/ml (normal até 5,0 ?U/ml); Tripsina Imunorreativa: 15,90 ng/ml\n(normal até 70 ng/ml); Hemoglobina: FSA. Diante do exposto, qual é a conduta adequada para o\ncaso?","options":{"A":"Explicar que a criança tem o traço falciforme e deverá continuar o acompanhamento de\ncrescimento e desenvolvimento.","B":"Explicar que se trata de um caso de doença falciforme e deverá iniciar, em momento adequado,\npenicilina e ácido fólico.","C":"Explicar que o teste é normal e continuar o acompanhamento de crescimento e\ndesenvolvimento.","D":"Explicar que a criança tem o traço falciforme e deverá iniciar, em momento adequado, penicilina\ne ácido fólico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-243771","number":"243771","sourceNumber":"243771","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"No que diz respeito às cardites por febre reumática, é correto afirmar que:","options":{"A":"o acometimento isolado da válvula aórtica é o achado mais comum","B":"apesar de ser a complicação mais grave, raramente acomete indivíduos com febre reumática","C":"normalmente manifesta-se como uma pancardite, acometendo pericárdio, miocárdio e\nendocárdio","D":"pelos critérios de Jones, a cardite é considerada uma manifestação menor para fins diagnósticos"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-220231","number":"220231","sourceNumber":"220231","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem, 25 anos, queixa-se de dor articular em joelho direito, além de articulação\nmetatarsofalangena do hállux esquerdo, sem história de trauma, de início há 5 semanas. Afirma ser\npreviamente hígido e relata apenas um quadro de disúria com melhora espontânea há algumas\nsemanas. Ao exame, discreta hiperemia ocular, sinais inflamatórios nas articulações acometidas,\nsem presença de deformidades. A principal hipótese diagnóstica e exame a ser solicitado para esse\ncaso seria:","options":{"A":"artrite reumatoide, fator reumatóide.","B":"artrite reacional, análise do líquido sinovial.","C":"artrite séptica, punção articular.","D":"osteoartrose, radiografia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-216844","number":"216844","sourceNumber":"216844","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo feminino, 44 anos, refere quadro de rigidez matinal de 1 hora em\nmãos, associada à artralgia, edema e hiperemia em\narticulações interfalangianas proximais,\nmetacarpofalangianas e punho, bilateralmente, nas últimas 8 semanas. Passou por avaliação\nmédica, sendo realizada a hipótese diagnóstica de artrite reumatoide. Quanto ao diagnóstico dessa\ndoença, assinale a alternativa CORRETA:","options":{"A":"Para o diagnóstico, a duração dos sintomas deve ser superior a 12 semanas.","B":"A presença do fator reumatoide positivo é necessária e suficiente para o diagnóstico.","C":"O anticorpo anti-CCP (antipeptídeos citrulinados cíclicos) pode ser usado como indicador de\nprogressão e prognóstico da doença.","D":"A presença de VHS e PCR positivos são critérios menores, enquanto a presença de nódulos\nsubcutâneos e eritema marginado são critérios maiores para o diagnóstico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-216893","number":"216893","sourceNumber":"216893","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é:","options":{"A":"Uma doença que ocorre em crianças com predisposição genética após uma infecção de\npele causada pelo estreptococo e não tratada adequadamente.","B":"Diagnosticada através do preenchimento dos critérios de Jones, que incluem poliartrite\nmigratória, cardite, crise convulsiva e eritema marginado.","C":"Caracterizada laboratorialmente pela presença de aumento de provas inflamatórias e níveis\nelevados de ASLO (anticorpo antiestreptolisina).","D":"Tratada com profilaxia secundária com penicilina benzatina a cada 21 dias quando ocorre artrite\ne a cada 15 dias se ocorrer cardite."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-187412","number":"187412","sourceNumber":"187412","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança de 1 ano e 2 meses é atendida pelo médico com queixa de hiporexia há 1 mês.\nA mãe informa que a criança ultimamente só\naceita a mamadeira de leite de vaca com mucilon e\nnega alterações gastrointestinais. Ao exame físico observa: criança com palidez cutânea mucosa\n\n++/4 e abdome flácido com leve distensão sem visceromegalias e ruídos hidro aéreos normais. O\nmédico solicita um hemograma e parasitológico de fezes. Assinale a alternativa CORRETA sobre o\ndiagnóstico mais provável e conduta para essa criança:","options":{"A":"Anemia Carencial Ferropriva / tratamento com sulfato ferroso 4 a 5mg/kg/dia de ferro elementar","B":"Parasitose/ tratamento com metronidazol 20mg/kg/dia","C":"Intolerância a lactose / excluir lactose da dieta da criança","D":"Anemia megaloblástica / tratamento com acido fólico","E":"Alergia a proteína do leite de vaca/ mudar o leite da criança para leite de soja."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-151077","number":"151077","sourceNumber":"151077","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à Artrite Idiopática Juvenil, assinale a INCORRETA:","options":{"A":"Caracteriza-se pela presença de artrite persistente em uma ou mais articulações por um tempo\nmínimo de seis semanas.","B":"No tipo oligoarticular há ocorrência de artrite em uma a quatro articulações, sendo os joelhos e\nos tornozelos as mais comprometidas.","C":"No tipo sistêmico há febre intermitente, geralmente vespertina, com duração mínima de 15 dias.","D":"Os exames laboratoriais estão sempre alterados, sendo que o fator reumatóide está presente\nem mais de 40% dos pacientes com subtipo\npoliarticular."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-133816","number":"133816","sourceNumber":"133816","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em crianças com diagnóstico confirmado de deficiência de G6PD, a medida terapêutica\nMAIS importante é","options":{"A":"Esplenectomia eletiva.","B":"Hemotransfusão preventiva.","C":"Prevenção da hemólise.","D":"Exsanguineotransfusão parcial."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-130087","number":"130087","sourceNumber":"130087","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O primeiro exame laboratorial a se alterar na anemia ferropriva é:","options":{"A":"Ferro sérico.","B":"Capacidade de ligação do ferro.","C":"Ferritina.","D":"Saturação da transferrina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-132249","number":"132249","sourceNumber":"132249","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma menina de 5 anos apresenta o gene para Hemoglobina S em homozigose (HbSS).\nEla queixou de parestesia por dois dias em\nregião lombar. No terceiro dia apresentou dor nesta\nregião, que aumentou progressivamente. Ao final do terceiro dia, a dor se tornou muito intensa e foi\ninternada. Qual a conduta mais adequada?","options":{"A":"Hidratação e analgesia, podendo ser necessárias oxigenoterapia e transfusão sanguínea.","B":"Antibioticoterapia e analgesia, podendo ser necessária restrição de volume.","C":"Transfusão sanguínea e analgesia, podendo ser necessária diureticoterapia.","D":"Esplenectomia e analgesia, podendo ser necessária transfusão sanguínea."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-107571","number":"107571","sourceNumber":"107571","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente do sexo masculino, 63 anos, procura serviço médico por fraqueza progressiva\nhá 6 meses. Refere ainda perda de 8 kg nesse\nperíodo e diarreia recorrente. Ao exame físico:\npálido ++/4+; anictérico; emagrecido; PA: 150 x 80 mmHg; RCR2T; FC: 100 bpm. Abdome: flácido,\ncom massa móvel, dolorosa, palpável em FID. Ausência de edemas. Seu hemograma inicial\nmostra: Hb: 8,2 g/dl; VCM: 70 fl e HCM: 21; leucócitos: 6.800/mm³ (eosinófilos: 2%, segmentados:\n68%, linfócitos: 22%, monócitos: 8%); plaquetas: 580.000/mm³. Qual dos perfis abaixo é adequado\nao caso?","options":{"A":"Ferro sérico normal, índice de saturação de transferrina aumentado, ferritina baixa.","B":"Ferro sérico baixo, índice de saturação de transferrina aumentado, ferritina baixa.","C":"Ferro sérico, índice de saturação de transferrina e ferritina diminuídos.","D":"Ferro sérico baixo, índice de saturação de transferrina diminuído e ferritina elevada.","E":"Ferro sérico e índice de saturação normais, ferritina elevada."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-107764","number":"107764","sourceNumber":"107764","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"E.A.B., 20 anos, dá entrada em Serviço de Pronto Atendimento queixando-se de\nfraqueza progressiva nos últimos 15 dias, com\nsintomas aos pequenos esforços há 2 dias. Ao\nexame físico, apresenta palidez cutâneo-mucosa = +++/4+, icterícia = +/4+, PA = 110/60 mm³, FR =\n25 mrpm FC = 125 bpm RCR2T MV fisiológico bilateral, abdome: ponta de baço palpável, ausência\nde púrpuras e edemas. Seu Hemograma mostra: Hb = 5,0 g/dl VCM = 105 fl, leucócitos = 12.300\n(Segmentados = 80% Linfócitos = 15% e Monócitos = 5%), Plaquetas:405.000/mm³. Qual a\nabordagem diagnóstica?","options":{"A":"Solicitar dosagem de Vitamina B12 e ácido fólico.","B":"Indicar punção aspirativa de medula óssea.","C":"Solicitar contagem de reticulócitos, LDH e Sorologias para Hepatites.","D":"Solicitar contagem de reticulócitos, LDH e Eletroforese de Hemoglobina.","E":"Solicitar contagem de Reticulócitos, LDH e Teste de Coombs direto."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-107541","number":"107541","sourceNumber":"107541","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente com artrite reumatoide com DAS 28 = 5,33, apesar do uso de terapêutica\notimizada com DMARDs sintéticos. Você opta por\niniciar terapêutica biológica com anti-TNF para\ncontrole da doença. Quais exames são mais importantes solicitar antes de iniciar a medicação?","options":{"A":"Fator reumatoide, RX de mãos, urina I e enzimas canaliculares.","B":"Transaminases, hemograma, sorologia para citomegalovírus e toxoplasmose.","C":"Hemograma, transaminases, RX de tórax e PPD.","D":"Parasitológico de fezes, creatinina, transaminases e hemograma.","E":"Anti-CCP, fator reumatoide e Waaler-Rose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-106795","number":"106795","sourceNumber":"106795","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Assinale a alternativa correta sobre ANEMIA:","options":{"A":"O diagnóstico da Anemia falciforme é feito pela eletroforese de hemoglobina que detecta a\npresença da hemoglobina A2.","B":"São características da anemia ferropriva: hipocromia e microcitose, ferritina elevada, ferro\nsérico\n\n< 30 mcg%; TBIC baixa.","C":"Anemia associada a doença renal crônica manifesta-se com macrocitose, reticulocitose e está\nassociada à baixa produção de eritropoetina.","D":"Anemia megaloblástica tem macrocitose, reticulocitose, ácido metilmalônico baixo.","E":"Anemia hemolítica pode ser causada por deficiência de glicose 6 fosfato desidrogenase\nmanifestada na exposição por sulfas e amiodarona."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-107526","number":"107526","sourceNumber":"107526","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em consulta de rotina, mãe refere que seu filho está muito pálido e com falta de apetite.\nSolicita a você exame de sangue. De acordo com as diretrizes de triagem para anemia ferropriva.\n\nQual é a melhor conduta?","options":{"A":"Solicitar hemograma e ferretina para todos lactentes independente da idade gestacional.","B":"Solicitar hemograma e ferretina apenas aos lactentes pré-termo.","C":"Solicitar hemograma e ferretina apenas em lactentes com 1 ano de idade independente da idade\ngestacional.","D":"Solicitar hemograma e ferretina apenas em lactentes com 9 meses de idade independente da\nidade gestacional.","E":"Não solicitar exames."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-83416","number":"83416","sourceNumber":"83416","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente masculino, branco, 68 anos, queixa-se de fraqueza progressiva há cerca de\num ano, com piora nos últimos 2 meses, além\nde tonturas, quedas frequentes e parestesias de\npernas. Ao exame físico apresenta palidez cutâneo-mucosa de +++/4+; icterícia +/4+; taquicardia;\nausência de hepatoesplenomegalia e edema discreto de MMII. Seu hemograma inicial mostra: Hb:\n6,7 g%; Ht: 20%; VCM: 105; leuco.: 2.500 (38% de neutrófilos); plaq.: 85.000; reticulócitos: 0,3% e\nLDH: 1.800. Qual das afirmações abaixo é mais adequada?","options":{"A":"Trata-se de hepatopatia crônica com agudização induzida por infecção.","B":"Trata-se de polineuropatia periférica induzida por infecção viral crônica, inclusive HIV.","C":"Anemia aplástica é a principal hipótese diagnóstica e o diagnóstico definido será por biópsia de\nmedula óssea.","D":"Os principais exames de avaliação diagnóstica são as sorologias para hepatites e HIV e\neletroneuromiografia.","E":"As dosagens de vitamina B12 e homocisteína são importantes para o diagnóstico seguidas de\nEDA."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-81210","number":"81210","sourceNumber":"81210","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O Staphylococcus aureus é o agente que mais causa osteomielite em todas faixas\netárias. Em um paciente portador de anemia falciforme, o agente etiológico frequentemente\nrelacionado à osteomielite é:","options":{"A":"Moraxella catarrhalis.","B":"Streptococcus do grupo A.","C":"Haemophilus influenzae.","D":"Pseudomonas.","E":"Salmonella."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-81114","number":"81114","sourceNumber":"81114","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Sobre Anemias Carenciais, assinale a alternativa correta:","options":{"A":"O hemograma da anemia por deficiência de ácido fólico evidencia anemia microcítica e\nsegmentação dos núcleos dos neutrófilos.","B":"As manifestações clínicas da anemia por deficiência da vitamina B12 incluem hipertrofia das\npapilas linguais, cansaço, palidez acentuada e sensações parestésicas em mãos e membros\ninferiores.","C":"O primeiro estágio da deficiência de ferro caracteriza-se pela depleção do estoque do mesmo\nsem anemia, caracterizado pela queda do ferro\nsérico, com o nível de hemoglobina normal.","D":"Em casos de aleitamento exclusivo, a suplementação profilática de ferro estará indicada,\nsomente, a partir dos 6 meses de vida.","E":"São alimentos com alta biodisponibilidade de ferro: vísceras, ovo, feijão e beterraba."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-60234","number":"60234","sourceNumber":"60234","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Dentre as causas de anemia macrocítica, assinale a CORRETA.","options":{"A":"Anemia sideroblástica congênita.","B":"Anemia por intoxicação por chumbo.","C":"Anemia perniciosa.","D":"Anemia ferropriva.","E":"Talassemia minor."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-62424","number":"62424","sourceNumber":"62424","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Uma vítima de acidente automobilístico é submetida a tratamento operatório por lesões\nabdominais e recebe dez unidades de concentrados de hemácias nas primeiras horas de\ninternação hospitalar. As complicações que podem resultar dessa hemotransfusão maciça são as\nseguintes:","options":{"A":"Hipotermia, alcalose metabólica, hipocalcemia, hipercalemia.","B":"Hipertermia, acidose metabólica, hipercalemia, hipercalcemia.","C":"Hipertermia, acidose respiratória, hipocalcemia, hipocalemia.","D":"Hipotermia, alcalose respiratória, hipercalemia, hipercalcemia.","E":"Hipertermia, alcalose respiratória, hipocalcemia, hipocalemia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-64960","number":"64960","sourceNumber":"64960","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente feminina, 26 anos, dá entrada em pronto-socorro com queixa de fraqueza\nintensa e progressiva há sete dias,\nacompanhada de palpitações e urina escura. Ao exame físico,\napresenta palidez cutâneo-mucosa +++/4+, icterícia +/+4, taquicardia e baço palpável a 3 cm de\nRCE. O hemograma inicial mostra: Hb = 4,2 g/dl; VCM= 102; leucócitos= 12.000 com\nsegmentados= 82%; linfócitos= 12% e monócitos= 6%; plaquetas= 480.000; bilirrubina total = 4,2;\nbilirrubina direta= 0,8 e indireta= 3,4; AST e ALT normais. Qual a abordagem diagnóstica e\nterapêutica mais adequada?","options":{"A":"Transfusão de concentrado de hemácias conforme prova cruzada compatível, solicitar teste de\nHAM e iniciar reposição de ácido fólico.","B":"Transfusão de concentrado de hemácias e iniciar pesquisa para perda oculta de sangue.","C":"Transfusão imediata de concentrado de hemácias sem prova cruzada, após coleta de perfil de\nferro e marcadores de hepatites B e C.","D":"Manter paciente em repouso, solicitar contagem de reticulócitos. LDH, teste de Coombs direto e\niniciar corticoterapia (prednisona 1 mg/kg/d) e ácido fólico 5 mg/d.","E":"Manter repouso e iniciar reposição de vitamina B12 após coleta de dosagem sérica de vitamina\nB12 e homocisteína."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-45875","number":"45875","sourceNumber":"45875","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente diabético de 60 anos apresentando adinamia, letargia e dispneia aos grandes\nesforços, retorna ao ambulatório de Clínica\nMédica com resultados de exames: Hemoglobina 8 g/dl,\ncontagem de reticulócitos 1%, hemoglobina corpuscular média 32 pg e o volume corpuscular médio\n90 fl. Na anamnese e exame físico não foi observado nenhum sintoma ou sinal de perda\nsanguínea. Neste momento, qual o exame laboratorial mais importante e útil para a determinação\nda etiologia da Anemia?","options":{"A":"Dosagem de ferro sérico","B":"Dosagem de ácido fólico","C":"Dosagem de vitamina B12","D":"Dosagem de transaminases","E":"Dosagem de creatinina sérica"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-45881","number":"45881","sourceNumber":"45881","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente feminina, 50 anos, queixa-se de astenia e emagrecimento nos últimos 2\nmeses. Já apresenta na consulta um hemograma com os seguintes resultados: Hb 9.8, HT 30,\nVCM 110, HCM 34, leucócitos 8.000, plaquetas 200.000. Nesta condição é correto afirmar:","options":{"A":"A paciente deverá ser avaliada quanto aos estoques de ferro, pois trata-se de anemia\nmicrocítica.","B":"Deve-se investigar o uso de drogas tais como barbitúricos, fenitoína e sulfassalazina.","C":"Deve-se investigar causas de anemia da doença crônica considerando que apresenta anemia\nnormocrômica e normocítica e emagrecimento.","D":"Anemia perniciosa deverá ser investigada com tomografia de abdome total.","E":"Talassemia deverá ser investigada com eletroforese de hemoglobina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-45912","number":"45912","sourceNumber":"45912","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação as indicações de esplenectomia, assinale a alternativa mais correta:","options":{"A":"Na doença de Cooley a esplenectomia é rotineiramente realizada devido o grande benefício\nalcanço com este procedimento","B":"No paciente vítima de trauma com lesão esplênica a retida do mesmo se faz mandatório","C":"Na doença de Gaucher a esplenectomia total é realizada para se evitar o agravamento da\ninfiltração gordurosa do fígado da medula óssea","D":"Na Drepanocitose a esplenectomia esta sempre indicada","E":"Na hipertensão porta a esplenectomia se da devido a doença instalada no baço"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-45932","number":"45932","sourceNumber":"45932","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"As crises aplásticas da Doença Falciforme estão vinculadas, muito frequentemente a\nprocessos infecciosos. As crises severas estão relacionadas na maioria das vezes a infecções por:","options":{"A":"Varicela","B":"Haemophilus influenzae","C":"E. coli","D":"Pneumococo","E":"Parvovírus B19"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-34535","number":"34535","sourceNumber":"34535","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na avaliação inicial diagnóstica de paciente com Anemia e contagem de reticulócitos\nnão elevada, devemos considerar no diagnóstico\ndiferencial o valor do Volume Corpuscular Médio\n(VCM) ou volume celular. Assinale a alternativa CORRETA:","options":{"A":"Se o VCM é normal, o paciente pode ter aplasia da medula óssea.","B":"Se o VCM é baixo, o paciente pode ter deficiência de vitamina B12.","C":"Se o VCM é baixo, o paciente pode ter deficiência de folato.","D":"Se o VCM é alto, o paciente pode ter deficiência de ferro.","E":"Se o VCM é alto, o paciente pode ter traço talassêmico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-34523","number":"34523","sourceNumber":"34523","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"É indicação para transfusão de concentrado de hemácias:","options":{"A":"Hb < 10 g/dl em pacientes sem comorbidades que vão ser submetidos à cirurgia.","B":"Hb < 10 g/dl em pacientes críticos.","C":"Ht < 38% em pacientes com IAM.","D":"Hb < 10 g/dl em pacientes com insuficiência cardíaca.","E":"Profilaticamente em indivíduos com Hb entre 6,0 e 8,0 g/dl."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-31903","number":"31903","sourceNumber":"31903","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança de 9 meses de idade dá entrada no PS com história de irritabilidade e choro\nfrequente há 2 dias. Mãe informa que é a\nsegunda vez que apresenta o quadro, sendo a primeira\nmanifestação aos 7 meses de idade. Relata, ainda, que um primo da criança teve o mesmo quadro\ne, hoje, faz tratamento para \"doença no sangue\". Ao exame físico, apresenta-se hipocorada,\nictérica, taquicárdica, dor e edema nas mãos e pés. Hemograma revela Hb = 6,8 g/dL ; VCM = 83 fl;\npoiquilocitose; eritroblastos = 5%; reticulócitos = 8%; leucócitos = 18.000/mm³ (7% bastonetes,\n45% segmentados, 43% linfócitos, e 5% monócitos). A principal hipótese diagnóstica é:","options":{"A":"Leucemia aguda.","B":"Anemia falciforme.","C":"Talassemia.","D":"Anemia hemolítica autoimune.","E":"Esferocitose."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-255909","number":"255909","sourceNumber":"255909","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 53 anos queixa-se de dispneia ao andar um quarteirão no plano há cerca de\n1 ano. Não percebeu piora recente e nega\ndor torácica, tosse ou ortopneia. Relata dor e edema nas\narticulações das mãos, punhos e joelhos há 3 meses, associada à dificuldade de movimentação\ndessas articulações por 4 horas após despertar pela manhã e que melhora com a persistência das\natividades usuais. Não possui doenças conhecidas e não faz uso regular de medicamentos. O\nexame físico apresenta PA 130/66 mmHg, FC 65 bpm, FR 16 ipm, SpO2 em ar ambiente 93%. O\nexame respiratório não apresenta anormalidades. O exame cardiovascular revela movimento da\nregião paraesternal inferior esquerda; ritmo cardíaco regular, desdobramento contínuo e variável da\nsegunda bulha, hiperfonese de P2 e sopro holossistólico na borda paraesternal inferior esquerda,\nmais intenso à inspiração. Apresenta dor à palpação, redução da amplitude de movimento e\naumento de volume das articulações metacarpofalangeanas, interfalangeanas proximais, punhos e\njoelhos. Sem outras anormalidades. Exames de laboratório: Hb 10,1 g/dl; LG 5.540/mm³; Plq\n532.000/mm³; PCR 27 mg/L; FR 2 UI/ml; anti-CCP 34 UI/ml; Creat 1,0 mg/dl. Assinale a alternativa\nque apresenta o tratamento relacionado à redução da progressão da doença articular e controle\ndos sintomas articulares nessa paciente.","options":{"A":"Anti-inflamatório não esteroidal.","B":"Colchicina.","C":"Metotrexato.","D":"Prednisona."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-20/255909.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-255912","number":"255912","sourceNumber":"255912","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 64 anos queixa-se de fraqueza aos esforços há uma semana. É portador de\ncâncer gástrico, obesidade grau 2 e osteoartrose dos joelhos. Realizou cirurgia bariátrica\n(Billroth II)\nhá 10 anos. Faz uso regular de ranitidina e ibuprofeno. É tabagista e etilista desde os 20 anos de\nidade. O pai teve câncer gástrico aos 84 anos. Realizou endoscopia digestiva alta que revelou\nlesão ulcerada na curvatura menor e teste da urease positivo. O exame físico não apresenta\nanormalidades. Exames de laboratório: Hb 7,9g/dL; Hct 25,3%; VCM 76fL; HCM 25 pg; CHCM\n30,1g/dL; RDW 16,2%; LG 6.600/mm³; Plq 286.000/mm³; LDH 200U/L; BT 1,2mg/dL; reticulócitos\n2,2%; vitamina B12 215pg/mL; ferritina 10ng/mL; ferro 23mcg/dL; CTLF 230mcg/dL; IST 17%.\n\nAssinale a alternativa que apresenta a causa MAIS PROVÁVEL para a anemia apresentada por\nesse paciente.","options":{"A":"Anemia aplásica","B":"Anemia da doença crônica","C":"Anemia ferropriva","D":"Anemia perniciosa"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-255917","number":"255917","sourceNumber":"255917","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 53 anos queixa-se de piora da dispneia basal, de forma progressiva nos\núltimos cinco dias, presente até ao tomar\nbanho e se vestir. Relata diversos despertares noturnos\npor dispneia, que é mais intensa em decúbito, e episódios paroxísticos e recorrentes de palpitação.\nÉ portador de insuficiência cardíaca, doença de Chagas, diabetes melito e gota. Faz uso regular de\nlosartana, espironolactona, furosemida, carvedilol e insulina NPH. Em consulta realizada há 8 dias,\nfoi prescrito o aumento da dose de carvedilol de 6,25 mg para 12,5 mg de 12/12h. Ao exame físico,\napresenta PA = 120/70 mmHg; FC = 68 bpm; FR = 23 ipm; SpO2 em ar ambiente de 93%; TAx =\n36,4°C. O paciente encontra-se alerta e orientado. As extremidades estão aquecidas e o\nenchimento capilar é imediato. O exame respiratório revela crepitações teleinspiratórias nas\nmetades basais do hemitórax. O exame cardiovascular revela pulso venoso na veia jugular interna\ndireita no nível do ângulo da mandíbula e refluxo hepatojugular presente; o ritmo cardíaco é\nregular,\no ictus está desviado inferiormente e para a esquerda, e é amplo. O fígado é palpado 5 cm abaixo\ndo rebordo costal direito e apresenta-se levemente doloroso à palpação. Não há edemas nos\nmembros inferiores. O paciente queixa-se de dor na 1ª articulação metatarsofalangeana direita. O\nexame físico revela edema, calor e eritema nessa articulação, com limitação da amplitude do\nmovimento, que é muito doloroso. O restante do exame do aparelho locomotor não apresenta\nanormalidades. Assinale a alternativa, dentre as seguintes, que apresenta o tratamento MAIS\nADEQUADO para a fase aguda da artrite apresentada por esse paciente.","options":{"A":"Alopurinol.","B":"Colchicina.","C":"Naproxeno.","D":"Prednisona."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-203252","number":"203252","sourceNumber":"203252","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um homem de 42 anos comparece ao pronto-socorro queixando-se de dor intensa no\njoelho esquerdo e febre há 12 horas. Ele é portador de doença renal crônica (clearance de\ncreatinina de 17 ml/kg/1,73 m²) e diabetes melito mal controlado. Ao exame clínico, está alerta,\norientado, corado e hidratado. PA = 130 x 70 mmHg; FR = 17 irpm; FC = 106 bpm; SpO? = 98%;\nTAx = 38,2°C. Há dor e limitação da amplitude do movimento do joelho esquerdo, além de derrame\narticular, calor e vermelhidão. Exames laboratoriais: hemoglobina = 13,5 g/dl; leucócitos =\n15.100/mm³; neutrófilos = 11.600/mm³; proteína C-reativa = 140 mg/L. Análise do líquido sinovial:\nleucócitos = 13.400/mm³; neutrófilos = 95%; presença de cristais de monourato de sódio, ausência\nde bactérias coráveis ao Gram e cultura para bactérias negativa. Assinale a alternativa CORRETA\nsobre esse caso.","options":{"A":"A colchicina pode ser utilizada no tratamento da dor e dos sinais flogísticos.","B":"A prescrição inicial deve incluir anti-inflamatório não esteroidal e alopurinol como agente\nredutor\nde ácido úrico.","C":"O paciente apresenta artrite séptica e deve ser iniciado o tratamento com ceftriaxona\nintravenosa.","D":"O principal agente etiológico é a Neisseria gonorrhoeae."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-139665","number":"139665","sourceNumber":"139665","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 69 anos, diabética e portadora de artrite reumatóide de longa data, motivo\npelo qual apresenta deformidades articulares principalmente nas mãos, punhos e pés.\n\nDesenvolveu, abruptamente, febre associada a dor, calor, eritema, aumento de volume e restrição\nde movimentos no joelho esquerdo. Considerando-se\ncaso apresentado, assinale a alternativa\nCORRETA:","options":{"A":"Artrite traumática deve ser considerada dentre as principais hipóteses diagnósticas já que nestes\ncasos geralmente não há história de trauma\nprévio.","B":"Deve-se iniciar colchicina e anti-inflamatório não esteroide imediatamente para interromper a\nprogressão do quadro e reverter as manifestações clínicas.","C":"O diagnóstico mais provável é artrite séptica e deve-se colher amostra de liquido sinovial para\nconfirmação diagnóstica.","D":"Trata-se provavelmente de exarcebação da artrite reumatóide e deve-se prescrever prednisona\n40mg/dia"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-127490","number":"127490","sourceNumber":"127490","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Nos casos de anemia hemolítica é frequente encontrar:","options":{"A":"Níveis séricos aumentados de Desidrogenase Lática (DHL) e diminuídos de haptoglobina.","B":"Aumento do nível sérico de haptoglobina ou redução do nível sérico de Desidrogenase Lática\n(DHL).","C":"Níveis séricos de Desidrogenase Lática (DHL) e haptoglobina aumentados.","D":"Níveis séricos de Desidrogenase Lática (DHL) reduzidos e sem alterações da haptoglobina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-141306","number":"141306","sourceNumber":"141306","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Crianças com três anos de idade, sabidamente com doença falciforme, apresenta crise\ndolorosa intensa em membros inferiores. A conduta CORRETA para controle da dor é prescrever:","options":{"A":"Dipirona","B":"Dipirona intercalada com ibuprofeno e hiperidratação","C":"Ibuprofeno","D":"Morfina e hiperidratação"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-127501","number":"127501","sourceNumber":"127501","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 42 anos, previamente assintomático, apresenta-se com dor em articulação\nmetatarsofalangiana à E de início súbito, noturna, de forte intensidade e após libação etílica\n(cerveja). Ao exame físico, está afebril e observam-se sinais evidentes de artrite na referida\narticulação. Entre as afirmativas abaixo relacionadas, assinale a ERRADA:","options":{"A":"O diagnóstico de certeza é confirmado a partir do achado de cristais de urato no líquido\narticular.","B":"Formação de cálculos renais de ácido úrico e insuficiência renal crônica são complicações em\nlongo prazo.","C":"Nível sérico de ácido úrico dentro dos valores de referência não é compatível com este caso\nclínico.","D":"Obtém-se resposta clínica dramática com o uso de anti-inflamatórios não esteroides."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-139730","number":"139730","sourceNumber":"139730","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança de dois anos de idade, gênero masculino, com diagnóstico de anemia\nfalciforme (SC) é admitida no Pronto\nAtendimento com queixa de tosse e inapetência há 4 dias. Há\n12 horas iniciou com palidez intensa e aumento do volume abdominal. Ao exame está hipocorada,\nprostrada, extremidades frias. Pulsos finos, pressão arterial sistólica = 70mmHg. Ausculta cardíaca\nevidencia sopro holossistólico. Ausculta respiratória sem alterações. Abdômen distendido, fígado\npalpado a 2cm do rebordo costal direito e baço palpado na crista ilíaca esquerda. O diagnóstico\nMAIS PROVÁVEL é:","options":{"A":"Choque séptico","B":"Crise álgica","C":"Crise aplásica","D":"Sequestro esplênico"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-101845","number":"101845","sourceNumber":"101845","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menino de dois anos e seis meses, com diagnóstico de Anemia Falciforme (SS) no\nteste do pezinho (triagem neonatal), dá entrada na Unidade de pronto atendimento (UPA) com\nqueixa de febre (38°C) há quatro dias, coriza hialina, tosse seca, inapetência e prostração. Ao\nexame físico não são observadas alterações que indiquem foco infeccioso ou instabilidade\nhemodinâmica. De acordo com o Manual de Eventos Agudos em Anemia Falciforme de 2009\npublicado pelo Ministério da Saúde do Brasil, a conduta MAIS ADEQUADA nesse caso será:","options":{"A":"Alta com prescrição de amoxicilina oral.","B":"Alta com reavaliação em 48 horas.","C":"Internação hospitalar com prescrição de ampicilina venosa.","D":"Internação hospitalar para observação por 48 horas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-112026","number":"112026","sourceNumber":"112026","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"O diagnóstico laboratorial da anemia ferropriva é caracterizado por:","options":{"A":"Ferro sérico diminuído, índice de saturação de tranferrina diminuído, capacidade total de ligação\nde ferro elevada e ferritina diminuída","B":"Ferro sérico diminuído, índice de saturação de tranferrina diminuído, capacidade total de ligação\nde ferro diminuída e ferritina diminuída","C":"Ferro sérico diminuído, índice de saturação de transferrina aumentado, capacidade total de\nligação de ferro diminuída e ferritina diminuída","D":"Ferro sérico diminuído, índice de saturação de transferrina aumentado, capacidade total de\nligação de ferro aumentada e ferritina diminuída"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-101797","number":"101797","sourceNumber":"101797","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 75 anos com anemia macrocítica associada à deficiência de vitamina B12 é\natendido no Centro de Saúde com pesquisa de anticorpo sérico anti-célula pariental positivo e\nendoscopia digestiva alta evidenciando gastrite atrófica de corpo e fundo gástrico. Assinale a\nalteração, dentre as abaixo, que NÃO deve ser encontrada neste caso:","options":{"A":"Acloridria.","B":"Anticorpo anti- fator intrínseco positivo.","C":"Hipergastrinemia.","D":"Pepsinogênio sérico I aumentado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-101821","number":"101821","sourceNumber":"101821","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"H.M., sexo feminino, 42 anos, comparece ao ambulatório relatando fraqueza. Foram\nsolicitados exames laboratoriais que evidenciaram anemia (Hb = 10,2 mg%). À anamnese e ao\nexame físico, não foi evidenciada nenhuma alteração. Dentre as opções abaixo, assinale a\nMELHOR conduta:","options":{"A":"Solicitar pesquisa de sangue oculto nas fezes.","B":"Prescrever sulfato ferroso por via oral.","C":"Prescrever ferro por via parenteral.","D":"Solicitar endoscopia digestiva alta e colonoscopia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-78387","number":"78387","sourceNumber":"78387","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 19 anos em convalescença de episódio de hepatite aguda não A, não B,\nnão C, evolui com cansaço, fraqueza,\nepistaxe, hemorragia gengival, além de petéquias e\nequimoses. Está pancitopênico e a biópsia de medula óssea evidencia marcante hipocelularidade,\ncom menos de 30% do espaço medular ocupado por células hematopoiéticas (o restante contém\napenas células adiposas). Em relação à abordagem terapêutica desta afecção, assinale a\nafirmativa ERRADA:","options":{"A":"A terapia imunossupressora, quando indicada, é composta pela associação entre imunoglobulina\nantitimócito e ciclosporina.","B":"A tipagem do Antígeno Leucocitário Humano (HLA) deve ser feita tão logo é diagnosticada a\ndoença.","C":"O transplante de medula óssea constitui-se na primeira opção terapêutica, quando há doador\ncompatível.","D":"Quando comparada à terapia imunossupressora, a mortalidade associada ao transplante é\nmenor, contudo o risco de evolução para a neoplasia é maior."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-60292","number":"60292","sourceNumber":"60292","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Você está atendendo uma criança de 9 anos de idade, com diagnóstico de anemia\nfalciforme com queixa de febre (39°C),\nprostração e taquicardia. O hemograma evidenciou\nleucometria de 20.000 células/mm³ e hemoglobina de 8 g/dl. O estudo radiológico de tórax mostra\ninfiltrado pulmonar difuso bilateral. Apresenta valores basais de hemoglobina de 8,5 g/dl e\nleucócitos totais de 18.000/mm³. Todas as alternativas são importantes para justificar a internação,\nEXCETO:","options":{"A":"Alteração da radiografia do tórax.","B":"Febre \"maior que\" 38°C.","C":"Hemograma com leucocitose e anemia.","D":"Prostração e taquicardia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-71483","number":"71483","sourceNumber":"71483","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 75 anos, com história de hipertensão arterial e de hiperuricemia, deu\nentrada no pronto atendimento com artrite de\njoelho esquerdo de 48 horas de evolução. Ao exame,\nencontrava-se levemente prostrado, com temperatura axilar de 37,8ºC e hemodinamicamente\nestável. Dentre as opções abaixo, qual é a conduta MAIS adequada?","options":{"A":"Solicitar hemograma e dosagem sérica de ácido úrico com o objetivo de avaliar a necessidade\nde artrocentese.","B":"Prescrever colchicina e anti-inflamatório não esteroide.","C":"Artrocentese e análise do líquido sinovial.","D":"Prescrever 10 mg de prednisona."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-60322","number":"60322","sourceNumber":"60322","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A hematoscopia é parte da avaliação do hemograma. Permite observar tamanho e\ncaracterísticas morfológicas das hemácias, plaquetas e leucócitos, bem como presença e\ncaracterísticas de células anormais. Algumas alterações são frequentemente encontradas em\ndeterminadas doenças ou processos patológicos. Abaixo estão relacionadas algumas dessas\nassociações. Qual delas está ERRADA?","options":{"A":"Corpos de Howell-Jolly e hipofunção ou ausência do baço.","B":"Eritrócitos grandes e ovalados e anemia megaloblástica.","C":"Esferócitos e anemia hemolítica autoimune.","D":"Neutrófilos hipersegmentados e infecção."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-60414","number":"60414","sourceNumber":"60414","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 58 anos procura Posto de Saúde com queixa de fadiga e intolerância aos\nexercícios de cerca de 2 meses de evolução. Sem outras queixas. Nega perda de peso, mas\ninforma não se alimentar bem. Não faz uso de medicamentos. A não ser pela presença de palidez\ncutâneo-mucosa (++/4+) e sopro sistólico ejetivo, grau II/VI, audível em todo o precórdio, o exame\nfísico está normal. Dos exames inicialmente solicitados, chamam a atenção: hemoglobina: 10 g/dl,\nVCM: 72 fl, ferro sérico: 14 mcg/dl (VR: 50-150 mcg/dl), capacidade total de ligação do ferro: 450\nmcg/dl (VR: 250-370 mcg/dl), índice de saturação da transferrina: 3%. Feita pesquisa de sangue\noculto nas fezes que resultou negativa. Dentre as alternativas abaixo, qual deve ser o próximo\npasso na abordagem da anemia apresentada pela paciente?","options":{"A":"Iniciar sulfato ferroso e encaminhá-lo à nutricionista.","B":"Prescrever dieta balanceada e repetir o hemograma e a cinética de ferro em 3 meses.","C":"Solicitar colonoscopia.","D":"Solicitar ultrassonografia de abdome superior."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-45138","number":"45138","sourceNumber":"45138","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Gestante de 30 anos, diagnóstico prévio de doença de Crohn, gravidez de 20 semanas,\ncom queixa de perda de apetite, náuseas e\nvômitos frequentes. Resultado do hemograma: Hb 9,9\ng/dL; VCM 100 fL (Fentolitro); leucócitos globais 3.500/mm³, neutrófilos com núcleos\nhipersegmentados. O diagnóstico mais provável é:","options":{"A":"Anemia aplástica.","B":"Anemia ferropriva.","C":"Anemia hemolítica.","D":"Anemia perniciosa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52432","number":"52432","sourceNumber":"52432","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"No que concerne à anemia ferropriva, é CORRETO afirmar que:","options":{"A":"Hemácias microcíticas e hipocrômicas e níveis séricos de ferro diminuídos podem ser\nencontrados tanto na anemia ferropriva quanto na anemia de doença crônica.","B":"O diagnóstico de ancilostomíase em paciente de 60 anos com anemia ferropriva é suficiente\npara estabelecer a etiologia da deficiência de ferro.","C":"O número de plaquetas é usualmente diminuído em pacientes com anemia ferropriva.","D":"Sangramento gastrointestinal é a principal causa de anemia ferropriva em mulheres jovens."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52344","number":"52344","sourceNumber":"52344","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Menina com 3 anos de idade e história de anemia crônica. Relato de três ?transfusões\nde sangue?. Em uso de ácido fólico (1 mg/dia).\nExame físico: palidez, icterícia e esplenomegalia.\nOs exames laboratoriais mostram anemia, reticulocitose, presença de esferócitos no esfregaço de\nsangue periférico e hiperbilirrubinemia com aumento de bilirrubina indireta. Teste do pezinho com o\nseguinte resultado: Hemoglobina FA. O pai da paciente foi submetido à esplenectomia da infância.\nEm relação ao caso clínico, assinale a afirmativa CORRETA:","options":{"A":"A paciente provavelmente é portadora de uma hemoglobinopatia.","B":"A presença de esferócitos no esfregaço é suficiente para confirmar o diagnóstico de esferocitose\ncongênita.","C":"Caso seja indicada a esplenectomia, ela deve ser realizada, preferencialmente, após os cinco\nanos de idade.","D":"Não há indicação para a prescrição de ácido fólico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-52419","number":"52419","sourceNumber":"52419","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança com 10 meses de idade é encaminhada ao hospital para transfusão de\nconcentrado de hemácias. Tem história de\nparto prematuro e baixo peso ao nascimento, está em\naleitamento artificial desde o sexto mês de vida, com pequena ingestão de carne. Iniciou o uso de\nsulfato ferroso profilático (1 mg/Kg/dia) no sexto mês de vida, administrado com suco de laranja.\nExame físico: ativa, palidez cutâneo-mucosa, eupneica. Sem alterações à ausculta pulmonar e\ncardíaca (frequência cardíaca: 100 bpm). Baço palpável a 2 cm do rebordo costal esquerdo.\n\nHemograma: Anemia hipocrômica e microcítica (hemoglobina = 6,0 g/dL), contagem de reticulócitos\nnormal, índice de anisocitose (RDW) aumentado,\ntrombocitose, leucograma sem alterações.\n\nConsiderando a história clínica, os exames laboratoriais e o exame físico do paciente, assinale a\nalternativa CORRETA:","options":{"A":"A profilaxia da anemia ferropriva foi iniciada em momento adequado.","B":"A transfusão foi bem indicada, pois o paciente apresenta nível de hemoglobina inferior a 8 g/dL.","C":"O sulfato ferroso não deve ser administrado com suco de laranja, pois a vitamina C inibe a\nabsorção do ferro na forma ferrosa.","D":"O sulfato ferroso poderá ser prescrito em dose terapêutica sem necessidade de outros exames\nlaboratoriais nesse momento."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-55325","number":"55325","sourceNumber":"55325","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de sete anos, com diagnóstico de anemia falciforme, internado com quadro de\ndor intensa em membro inferior esquerdo. Sem melhora após uso de dipirona e paracetamol.\n\nAfebril. Exame físico: Hipocorado. Ausência de sinais flogísticos no membro acometido. Frequência\ncardíaca respiratória ? 100 bpm. Saturação de\nO2 ? 96%, em ar ambiente. Hemoglobina ? 7,5 g/dl.\nRestante do hemograma sem alterações. Em relação a este caso clínico, qual das condutas abaixo\nvocê considera INADEQUADA neste momento?","options":{"A":"Iniciar hidratação venosa","B":"Iniciar o uso de analgésicos mais potentes, como opioides","C":"Não iniciar antibioticoterapia empírica","D":"Solicitar imediatamente a transfusão de concentrado de hemácias e iniciar oxigenioterapia"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-31483","number":"31483","sourceNumber":"31483","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Homem de 42 anos encontra-se em tratamento para tuberculose pulmonar há quatro\nmeses. Após os primeiros 40 dias de\ntratamento, aproximadamente, passou a usar a medicação de\nforma muito irregular. Encontra-se deprimido em decorrência da morte de sua esposa há três\nmeses. Há cerca de um mês, voltou a apresentar tosse com expectoração amarelada. Não sabe\ninformar sobre a ocorrência de febre. Não é etilista e nem tabagista. Nega passado mórbido de\nimportância. Ao exame encontra-se abatido e emagrecido. Hemograma: Hb = 10,3 g/dl, VCM = 80\nfl, ferro sérico = 28 µg/dl (valor de referência = 50-150 µg/dl), capacidade total de ligação do\nferro =\n200 µg/dl (VR = 250-370 µg/dl). Qual é a explicação mais provável para a anemia desse paciente?","options":{"A":"Anemia de doença crônica.","B":"Anemia sideroblástica.","C":"Deficiência de vitaminas.","D":"Perda oculta de sangue."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-22843","number":"22843","sourceNumber":"22843","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Mulher de 77 anos com dispneia aos esforços, sensação de queimação na língua,\nacometimento da sensibilidade vibratória (avaliada com auxílio do diapasão), trombocitopenia e\nleucopenia discretas, icterícia leve, baço palpável sob o rebordo costal esquerdo e anemia\n(hemoglobina 6,5 g/dL, VCM 132 L). O tratamento de escolha é?","options":{"A":"Eritropoetina por via parenteral","B":"Esplepectomia","C":"Acido fólico","D":"Vitamina B12 por via parenteral"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-346217","number":"346217","sourceNumber":"346217","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"C.M.A, 13 anos, sexo feminino, procurou atendimento no PSF após admissão\nhospitalar na qual, segundo a paciente,\napresentou diagnóstico de febre reumática. Critérios de\nJones foram criados para realizar o diagnóstico dessa patologia. De acordo com esses critérios, a\npaciente deve possuir faringoamigdalite documentada ou ASLO em ascensão, além de\nmanifestações que podem ser classificadas como critério menor ou maior. Das manifestações\ndescritas abaixo, qual a considerada um critério menor?","options":{"A":"Cardite.","B":"Nódulo subcutâneo.","C":"Cefaleia.","D":"Poliartrite migratória.","E":"Febre."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-301022","number":"301022","sourceNumber":"301022","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Analise os seguintes procedimentos. I. Pesquisa de cristais; II. Citologia / citometria;\nIII.\nCultura; IV. LDH, proteínas totais e frações e glicose; V. PH. Em pacientes adultos com monoartrite\naguda, após a punção e coleta de líquido sinovial, deve-se obrigatoriamente solicitar","options":{"A":"I e III, apenas.","B":"I, II e III, apenas.","C":"II, III e IV, apenas.","D":"I, II, IV e V."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-287612","number":"287612","sourceNumber":"287612","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"As terapias sintomáticas dos pacientes com Artrite Psoriaca (AP) incluem\nmedicamentos:","options":{"A":"anti-inflamatórios não-esteroides, glicocorticoides sistêmicos e nunca injeções locais de\nglicocorticoide.","B":"anti-inflamatórios não-esteroides, glicocorticoides sistêmicos e injeções locais de\nglicocorticoide.","C":"anti-inflamatórios não-esteroides, nunca glicocorticoides sistêmicos e sim injeções locais de\nglicocorticoide.","D":"Não estão indicados os anti-inflamatórios não-esteroides, e sim glicocorticoides sistêmicos e\ninjeções locais de glicocorticoide."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-287617","number":"287617","sourceNumber":"287617","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Para oferecer uma melhor qualidade de vida e evitando a perda da capacidade\nfuncional dos pacientes com Artrite Psoriaca (AP), pode-se afirmar que:","options":{"A":"O tratamento da Artrite Psoriaca (AP) não objetiva a redução dos sintomas, e sim a remissão ou\no controle da atividade da\n\ndoença com mínima ou baixa atividade.","B":"O tratamento da Artrite Psoriaca (AP) objetiva a redução dos sintomas, a remissão sem o\ncontrole da atividade da doença com\n\nmínima ou baixa atividade.","C":"O tratamento da Artrite Psoriaca (AP) objetiva a manutenção dos sintomas, a remissão ou o\ncontrole da atividade da doença com\n\nmínima ou baixa atividade.","D":"O tratamento da Artrite Psoriaca (AP) objetiva a redução dos sintomas, a remissão ou o controle\nda atividade da doença com\n\nmínima ou baixa atividade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-260540","number":"260540","sourceNumber":"260540","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Renato de 30 anos, procedente de Paraguaçu, procura a Santa Casa com relato de há\n1 semana ter iniciado com quadro de astenia,\nfebre baixa, oligoartrite assimétrica nos membros\ninferiores, daquitilite em mãos e pés associado a disúria e hiperemia ocular, qual o diagnóstico\nmais\nprovável para este paciente:","options":{"A":"Lupus eritematoso sistêmico.","B":"Sarcoidose aguda.","C":"Artrite reativa.","D":"Doença de behçet"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-260246","number":"260246","sourceNumber":"260246","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Após intensa libação alcoólica em uma confraternização, paciente masculino de 58\nanos de idade, obeso e dislipidêmico,\ninicia com dor intensa e aumento do volume da articulação\ndo primeiro metatarso do pé esquerdo, associado à febre. Sobre esse quadro, assinale a alternativa\nincorreta.","options":{"A":"O diagnóstico de artrite gotosa é feito com a pesquisa de cristais de birrefringência negativa no\naspirado articular.","B":"Durante a crise de artrite gotosa aguda, deve ser iniciado tratamento imediato com alopurinol.","C":"O diagnóstico diferencial principal é entre artrite séptica e artrite gotosa, devendo ser\nprocedido\no aspirado do líquido articular.","D":"Na artrite séptica, a via hematogênica é a principal forma de entrada da bactéria na\narticulação."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-260554","number":"260554","sourceNumber":"260554","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Criança com diagnóstico estabelecido de Febre Reumática, sem cardite prévia ou atual\ndeverá receber profilaxia secundária com Penicilina Benzatina até:","options":{"A":"18 anos ou 3 anos após o último surto, o que cobrir maior período.","B":"21 anos ou 5 anos após o último surto, o que cobrir maior período.","C":"25 anos ou 3 anos após o último surto, o que cobrir maior período.","D":"Por toda vida."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-262929","number":"262929","sourceNumber":"262929","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Em relação à artrite reumatoide, assinale com V as afirmativas Verdadeiras e com F as\nFalsas. ( ) Anticorpos anti-CCP (anticitrulina) são menos específicos que o fator reumatoide. ( )\nDerrame pleural, esplenomegalia e poliartrite assimétrica com predileção para grandes articulações\nsão características da artrite reumatoide. ( ) Início insidioso com rigidez matinal e artralgia são\nmanifestações frequentes e características. ( ) Nódulos subcutâneos ocorrem em 20% dos\npacientes e se correlacionam a uma menor soropositividade para o fator reumatoide. ( )\nManifestações extra-articulares que surgem antes do início da artrite são mais comuns nos\npacientes com história de tabagismo. Assinale a sequência CORRETA.","options":{"A":"F?F?V?F?V.","B":"F?V?V?F?F.","C":"V?V?F?F?F.","D":"F?V?V?F?V."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-259406","number":"259406","sourceNumber":"259406","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 4 anos de idade apresentou picadura de inseto na região da coxa direita.\nApós 72h da picada, a pequena lesão papular\ninicial evoluiu para lesão nodular de 4 cm de\ndiâmetro, edema da pele circunjacente, vermelhidão, dor local à palpação e ponto de flutuação de\naspecto purulento. Procurou pronto atendido e foi prescrito neomicina tópica. Após 2 dias de\ntratamento a criança começou a queixar de dificuldade de deambulação, dor a flexão do joelho\ndireito, derrame articular, febre (38,9°C) e prostração. Quanto ao quadro clínico supracitado marque\na afirmativa CORRETA:","options":{"A":"O agente etiológico mais comum é o Staphylococcus aureus, sendo a oxacilina uma boa opção\ncomo tratamento medicamentoso.","B":"Nesta patologia, embora frequentemente o hemograma e as provas inflamatórias são normais, a\nhemocultura é positiva em mais de 50% dos casos.","C":"A drenagem cirúrgica é indicada somente se houver persistência dos sinais flogísticos após 72h\nde antibioticoterapia adequada.","D":"Provavelmente se trata de artrite inflamatória reacional, uma vez que a antibioticoterapia\nadequada da celulite é eficaz na prevenção de\nquadros infecciosos secundários como artrite\nséptica ou osteomielite."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-259408","number":"259408","sourceNumber":"259408","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é uma doença sistêmica de caráter autoimune desencadeada após a\ninfecção pelo streptococo B-hemolítico do grupo A de Lancefield. Seu diagnóstico é eminentemente\nclínico. São manifestações maiores segundo os Critérios de Jones modificados, EXCETO:","options":{"A":"Eritema marginado.","B":"Nódulo subcutâneo.","C":"Artralgia.","D":"Coréia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-266654","number":"266654","sourceNumber":"266654","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A febre reumática é a doença reumática mais comum em crianças na idade escolar e\nadolescentes. Sobre a febre reumática, assinale a alternativa INCORRETA:","options":{"A":"Normalmente ocorre entre crianças de 5 a 15 anos, podendo se manifestar com insuficiência\ncardíaca.","B":"Segundo os critérios de Jones, um caso de coreia típica confirma diagnóstico não necessitando\nde outros critérios.","C":"O ecocardiograma é um exame bem importante na confirmação das lesões valvares.","D":"A profilaxia por via oral tem o mesmo efeito da intramuscular, podendo ser decidida juntamente\ncom a equipe médica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-238748","number":"238748","sourceNumber":"238748","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Um homem de 43 anos procura o consultório de clínica médica com a queixa de\npalpitação e dispneia aos esforços\nmoderados. Nega uso de medicamentos e doenças conhecidas.\nAo exame físico, apresenta-se alerta e orientado. Os dados vitais são PA 130/80mmHg, FC 65bpm,\nFR 18ipm, SpO2 95%. Os exames respiratório e abdominal não apresentam anormalidades. Traz\nresultados de exames prévios. Ecocardiograma: aumento importante do átrio esquerdo; demais\ncâmaras de dimensões e contratilidade normais. Pressão sistólica de artéria pulmonar 53mmHg\n(VR<40mmHg), Fração de ejeção do ventrículo esquerdo 65% (VR >50%). Espessamento das\ncúspides da valva mitral, restrição da abertura valvar durante a diástole, área mitral de 1cm2 (VR\n\n>4cm2) e regurgitação mitral moderada. Eletrocardiograma: Assinale o achado do exame físico\ncardiovascular que provavelmente NÃO deve estar presente neste paciente.","options":{"A":"Sopro holossistólico suave em platô mais audível no Apex.","B":"Estalido mesossistólico no foco mitral mais audível com o diafragma do estetoscópio.","C":"Desdobramento da segunda bulha contínuo e mais acentuado à inspiração, com hiperfonese de\nP2.","D":"Sopro mesodiastólico em ruflar com reforço pré-sistólico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-20/238748.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-239823","number":"239823","sourceNumber":"239823","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"A.F.L.K, 63 anos, masculino, sem comorbidades prévias, iniciou com dor intensa em\njoelho direito, associado a eritema e importante edema. Admitido ao pronto atendimento febril\n(38,5ºC), PA 110x60, FC 112, ritmo cardíaco regular em 2 tempos e sem sopros, sem outras\nalterações ao exame físico. O diagnóstico mais importante a ser avaliado por suas implicações\nprognósticas e a propedêutica mais indicada são?","options":{"A":"Gota e dosagem de uricemia.","B":"Doença do depósito de pirofosfato de cálcio e radiografia de joelho direito.","C":"Artrite Reativa e Reação de cadeia de polimerase para clamídia.","D":"Artrite séptica e artrocentese com análise do líquido sinovial e culturas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-253928","number":"253928","sourceNumber":"253928","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Paciente de 15 anos, sexo feminino, foi atendida na emergência com quadro de\nfaringoamigdalite. O médico avaliou a paciente e liberou para casa com prescrição de\n\nanti-inflamatório. Evoluiu com poliartrite, nódulos subcutâneos e cardite. Qual a lesão valvar mais\nfrequente na febre reumática crônica?","options":{"A":"Estenose mitral.","B":"Estenose aórtica.","C":"Estenose tricúspide.","D":"Insuficiência mitral."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-20-254630","number":"254630","sourceNumber":"254630","collectionBlock":"med:med-clinica-medica-med-clm-20","collectionLabel":"MED · MED CLM 20","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 20","subtopic":"","stem":"Na febre reumática, a válvula mais frequentemente comprometida é a:","options":{"A":"Pulmonar","B":"Tricúspide","C":"Mitral","D":"Aórtica"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 20/MED CLM 20.txt","sourceLabel":"MED · MED CLM 20","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 20","MED"],"answerSource":"explicit","commentDeferred":true}]};
